import{services,equipment,statuses,defaults,money,number,escape as e,today,dateText,uid,calculate,requiredEquipment,jobTasks,conflicts,radicalBlocked,financials,roundMoney,invoicePayments,invoiceBalance,recordPayment,expenseCost,trackedHours,actualResult,migrateState,annualWatch,copyFollowUp,removePayment,validISODate}from './core.js';
const icons={leaf:'<path d="M20 4c-11-2-17 5-14 11 4 5 13 1 14-11Z"/><path d="m4 21 12-13"/>',dashboard:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',jobs:'<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M9 3h6v4H9zM8 12h8M8 16h5"/>',calc:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 11h2m4 0h2M8 15h2m4 0h2M8 18h2m4 0h2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M7 15h2m3 0h2m3 0h1"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 4a5 5 0 0 1 3 5"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18m-1 4h-5v4h5"/>',tools:'<path d="m14 6 4 4m-6-7a6 6 0 0 0-7 7L2 20l2 2 10-9a6 6 0 0 0 7-7l-4 4-4-4 4-4"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Zm7-2v4m-2-2h4"/>',settings:'<path d="m10 3-1 3-3 1-3 3 3 2-1 4 3 2 3-1 3 4 3-3 1-3 3-2-2-3 1-4-4-1-2-3z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',camera:'<path d="M3 7h4l2-3h6l2 3h4v13H3z"/><circle cx="12" cy="13" r="4"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',check:'<path d="m5 12 4 4L19 6"/>',euro:'<path d="M18 5a7 7 0 1 0 0 14M4 10h11M4 14h10"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5m-4 0h8"/>',send:'<path d="m3 3 19 9-19 9 4-9-4-9Zm4 9h15"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M9 10v7m6-7v7"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',clean:'<path d="m9 3 2 5m-4 1 7-3 6 13-7 3L7 9ZM3 8l2-2m13-3v4m-2-2h4"/>',print:'<path d="M6 8V3h12v5M6 17H3V8h18v9h-3M6 14h12v7H6z"/>',back:'<path d="m14 6-6 6 6 6"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 5 9 7 9-7"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.leaf}</svg>`;
const initial=()=>({version:3,quotes:[],timeEntries:[],activeTimer:null,settings:{...defaults},customers:[],jobs:[],invoices:[],expenses:[],owned:[],demo:false});let state=initial(),view='dashboard',filter='Alle',month=today().slice(0,7),draft=null,photo=null,photoSuggestions=[],chatMessages=[{role:'assistant',text:'Hallo! Ich bin dein WerkPilot-Fachassistent. Ich berechne Preise, prüfe die Marge und empfehle Geräte anhand deiner Eingaben.\n\nZum Beispiel: „Kalkuliere 200 m² Rasen“, „100 Quadratmeter Wand streichen“ oder „Welche Geräte brauche ich für Fensterreinigung?“\n\nIch arbeite mit dem hinterlegten Leistungskatalog und Regeln, ohne API-Key. Maße und Aufwand vor Ort bitte bestätigen.'}];let db,durableState=initial(),saveQueue=Promise.resolve(),writeEpoch=0,recoveryRequired=false,unreadableState=null;
let offerFilter='all';
const serviceRate=s=>configuredRate(s,state.settings);
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
function toast(t){const el=document.querySelector('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',4500)}
async function openDB(){return new Promise((res,rej)=>{const req=indexedDB.open('werkpilot-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
async function load(){try{db=await openDB();const saved=await new Promise((res,rej)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(saved){try{state=validateRestore(saved)}catch{recoveryRequired=true;unreadableState=saved;toast('Gespeicherter Bestand konnte nicht sicher geladen werden. Rohdaten exportieren und eine gültige Sicherung importieren.')}}durableState=structuredClone(state)}catch{db=null;toast('Gerätespeicher nicht verfügbar. Speicherberechtigung und freien Speicher prüfen.')}}
async function persist(){const next=structuredClone(state),epoch=writeEpoch;const save=async()=>{try{if(epoch!==writeEpoch)throw Error("Vorheriger Speichervorgang fehlgeschlagen. Bitte erneut prüfen.");if(!db)throw Error('Gerätespeicher nicht verfügbar');if(recoveryRequired)throw Error('Gespeicherter Bestand muss zuerst über eine Sicherung wiederhergestellt werden.');await new Promise((res,rej)=>{const t=db.transaction('data','readwrite');t.objectStore('data').put(next,'state');t.oncomplete=res;t.onerror=()=>rej(t.error);t.onabort=()=>rej(t.error||Error('Speichern abgebrochen'))});durableState=next}catch(err){writeEpoch++;state=structuredClone(durableState);throw err}};const result=saveQueue.then(save);saveQueue=result.catch(()=>{});return result}
async function commit(){try{await persist();render();return true}catch{state=structuredClone(durableState);render();toast('Speichern fehlgeschlagen. Der zuletzt gespeicherte Bestand wurde wieder angezeigt. Eingabe bitte erneut prüfen.');return false}}
const customer=id=>state.customers.find(c=>c.id===id);const jobCustomer=j=>customer(j.customer)?.name||'Kunde nicht zugeordnet';
const statusPill=s=>`<span class="pill ${s==='Angebot'?'amber':s==='Erledigt'?'gray':s==='Storniert'?'red':''}">${e(s)}</span>`;
const categoryPill=j=>`<span class="pill">${e([...new Set((j.lines||[]).map(l=>groupName(services.find(s=>s.id===l.service)?.category)))].join(' + '))}</span>`;
const btn=(text,action,ico='',className='',extra='')=>`<button class="btn ${className}" data-action="${action}" ${extra}>${ico?icon(ico):''}${text}</button>`;
const empty=(text,ico='jobs')=>`<div class="empty">${icon(ico)}${text}</div>`;
function pageHeading(title,subtitle,action=''){return `<div class="heading"><div><div class="eyebrow">DEIN BETRIEB. IM GRIFF.</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`}
function render(){const nav=appNavigation(), title=nav.find(n=>n[0]===view)?.[1]||'Foto-Aufmaß';app.innerHTML=`<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandmark">${icon('leaf')}</div><div>${e(state.settings.company===defaults.company?'werkpilot':state.settings.company)}<small>WERKPILOT · DEIN BETRIEB</small></div></div><div class="navcaption">ARBEITSPLATZ</div><nav class="nav" aria-label="Arbeitsbereiche">${nav.map(([id,title,ico])=>`<button data-view="${id}" class="${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(ico)}${title}</button>`).join('')}</nav><div class="sidebarfoot"><div class="localnote"><strong>${icon('check')} Dein Betrieb auf deinem Gerät</strong>Aufträge, Fotos und Finanzen lokal speichern. Regelmäßig eine Sicherung exportieren.</div><div class="user"><div class="avatar">${e((state.settings.owner||'WP').slice(0,2).toUpperCase())}</div><div>${e(state.settings.owner||'Mein Betrieb')}<small>${state.demo?'BEISPIELDATEN AKTIV':'HANDWERK & SERVICE'}</small></div></div></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb">Arbeitsplatz &nbsp; / &nbsp; <b>${title}</b></div><div class="mobile-brand"><span class="mobile-mark">${icon('leaf')}</span><div><strong>${view==='dashboard'?e(state.settings.company===defaults.company?'werkpilot':state.settings.company):title}</strong><small>${view==='dashboard'?'HANDWERK & SERVICE':e(state.settings.company)}</small></div></div><div class="topactions"><form id="search-form" class="search">${icon('search')}<input name="q" placeholder="Auftrag oder zugeordneten Kunden suchen" aria-label="Aufträge suchen"></form><span class="datepill">${dateText(today())}</span>${state.activeTimer?`<button class="timer-chip" data-action="open-time" aria-label="Laufende Zeiterfassung öffnen">${icon('clock')} Läuft</button>`:''}<button class="iconbtn" data-action="open-voice" aria-label="Sprachassistent starten">${icon('mic')}</button><button class="iconbtn desktop-assistant" data-view="assistant" aria-label="Fachassistent öffnen">${icon('spark')}</button><button class="iconbtn mobile-menu" data-action="more" aria-label="Alle Arbeitsbereiche öffnen">${icon('menu')}</button></div></header><main class="main">${recoveryRequired?'<div class="notice warn">Der gespeicherte Bestand konnte nicht geladen werden. Er wurde nicht überschrieben. Exportiere zuerst die Rohdaten und importiere unter Einstellungen eine gültige Sicherung.</div>':''}${({dashboard:dashboard,jobs:jobsPage,calc:calcPage,calendar:calendarPage,customers:customersPage,finance:financePage,equipment:equipmentPage,assistant:assistantPage,settings:settingsPage,offers:offersPage,workspace:workspacePage,rates:ratesPage,knowledge:knowledgePage,trades:tradesPage,planner:plannerPage,photos:photosPage,time:timePage,business:businessPage,install:installPage,focus:focusPage})[view]?.()||dashboard()}<div class="footerhint">WerkPilot 5.0 · ${!db?'Speichern nicht verfügbar':recoveryRequired?'Wiederherstellung erforderlich':state.demo?'Beispieldaten aktiv':'Auf diesem Gerät gespeichert'}</div></main><nav class="bottom-nav" aria-label="App-Navigation">${[['dashboard','Start','dashboard'],['jobs','Aufträge','jobs'],['calendar','Termine','calendar'],['finance','Finanzen','wallet']].map(([id,t,ico])=>`<button data-view="${id}" ${view===id?'aria-current="page"':''} class="${view===id?'active':''}">${icon(ico)}<span>${t}</span></button>`).join('')}<button data-action="more" class="${!['dashboard','jobs','calendar','finance'].includes(view)?'active':''}" aria-label="Weitere Arbeitsbereiche">${icon('menu')}<span>Mehr</span></button></nav></div></div>`;bindPage();bindV2();bindProPage();bindHandworkPage();bindSpeechControls();document.querySelectorAll?.('form').forEach(guardForm);}

function appNavigation(){return [['dashboard','Übersicht','dashboard'],['workspace','Mein Betrieb','users'],['offers','Angebote','mail'],['jobs','Aufträge','jobs'],['trades','Gewerke & Leistungen','tools'],['planner','Material & Einsatzplan','jobs'],['photos','Fotos & Erkennung','camera'],['calc','Kalkulation','calc'],['calendar','Termine','calendar'],['customers','Kunden','users'],['finance','Finanzen & Zahlungen','wallet'],['time','Zeiterfassung','clock'],['business','Kleinunternehmer','leaf'],['knowledge','Fachwissen & Region','tools'],['rates','Leistungspreise','euro'],['equipment','Geräte & Material','tools'],['assistant','Fachassistent','spark'],['focus','Heute wichtig','check'],['settings','Einstellungen','settings'],['install','App installieren','download']]}
function dashboard(){const d=dailyOverview(state),f=financials(state,today().slice(0,7)),name=state.settings.owner?.split(' ')[0];return `<section class="mobile-home"><div class="home-heading"><span class="eyebrow">${dateText(today())}</span><h1>${name?'Hallo, '+e(name)+'.':'Dein Tag. Dein Betrieb.'}</h1><p>${e(state.settings.company)} · dein Betrieb im Überblick.</p>${companySetup(state).some(c=>!c.done)?'<button class="linkbtn" data-view="workspace">Firmenprofil einrichten '+icon('arrow')+'</button>':''}</div>${state.demo?'<div class="notice">Beispieldaten aktiv · keine echten Geschäftsvorfälle.</div>':''}<section class="balance-card" aria-label="Monatsübersicht"><div><span>Zahlungseingänge · dieser Monat</span><strong>${money(f.cash)}</strong><small>Brutto · ${money(f.netRevenue)} ohne Umsatzsteuer</small></div><button class="iconbtn" data-view="finance" aria-label="Finanzübersicht öffnen">${icon('arrow')}</button><div class="balance-foot"><span><b>${d.agenda.length}</b> Einsätze heute</span><span><b>${money(f.open)}</b> offen</span></div></section><section class="quick-actions" aria-label="Schnellaktionen">${[['Neuer Auftrag','new-job','plus'],['Foto & Aufmaß','photos','camera'],['Zeit erfassen','open-time','clock'],['Ausgabe','new-expense','wallet']].map(([title,action,ico])=>`<button data-action="${action}"><span>${icon(ico)}</span><b>${title}</b></button>`).join('')}</section><div class="card"><div class="cardhead"><h2>Heute wichtig</h2><button class="linkbtn" data-view="focus">${icon('arrow')} Anzeigen</button></div>${attentionRows(d, true)}</div><section class="card"><div class="cardhead"><h2>${d.agenda.length?'Deine Einsätze heute':'Dein nächster Einsatz'}</h2><button class="linkbtn" data-view="calendar">Kalender</button></div>${mobileJobs(d.agenda.length?d.agenda:d.upcoming.slice(0,1))}${!d.upcoming.length?btn('Einsatz planen','new-job','plus','secondary full'):''}</section><button class="voice-banner" data-action="open-voice"><span class="voice-banner-icon">${icon('mic')}</span><span><strong>Dein Fachassistent</strong><small>Aufmaß nennen. Kosten und Geräte planen.</small></span>${icon('arrow')}</button>${d.missing.length?`<section class="card"><h2>Packliste für heute</h2><p class="sectiondesc">Im Bestand noch nicht markiert:</p><div class="tags">${d.missing.map(eq=>`<span class="pill gray">${e(eq.name)}</span>`).join('')}</div><button class="linkbtn" data-view="equipment">Geräte prüfen ${icon('arrow')}</button></section>`:''}${getInstallState().installed?'':`<button class="install-teaser" data-view="install">${icon('download')}<span><strong>WerkPilot auf dein Handy</strong><small>Eigenes Symbol auf dem Home-Bildschirm</small></span>${icon('arrow')}</button>`}</section><section class="desktop-home">${workspaceHero()}${desktopDashboard()}<div class="card"><div class="cardhead"><h2>Heute wichtig</h2><button class="linkbtn" data-view="focus">Alle Schritte ansehen ${icon('arrow')}</button></div>${attentionRows(d,true)}</div></section>`}
function mobileJobs(jobs){return jobs.length?`<div class="mobile-job-list">${jobs.map(j=>`<button class="job-tile" data-action="detail" data-id="${e(j.id)}"><span class="job-tile-icon ${(j.lines||[]).some(l=>services.find(s=>s.id===l.service)?.category==='garden')?'garden':'clean'}">${icon((j.lines||[]).some(l=>services.find(s=>s.id===l.service)?.category==='garden')?'leaf':'clean')}</span><span class="job-tile-body"><strong>${e(j.title)}</strong><small>${e(jobCustomer(j))}</small><span>${dateText(j.date)}${j.time?' · '+e(j.time):''}</span></span><span class="job-tile-end"><b>${money(calculate(j,state.settings).gross)}</b>${statusPill(j.status)}</span></button>`).join('')}</div>`:empty('Kein Einsatz eingetragen. Plane deinen nächsten Auftrag.','calendar')}
function attentionRows(d,compact=false){const rows=[[d.overdue.length,'Überfällige Rechnungen',money(d.overdueTotal)+' offener Restbetrag','wallet','focus'],[d.unbilled.length,'Erledigt, noch nicht abgerechnet','Rechnungsentwurf vorbereiten','jobs','focus'],[d.missed.length,'Vergangene Einsätze noch offen','Status oder Termin prüfen','calendar','focus']];return rows.filter(r=>r[0]).map(([count,title,sub,ico,destination])=>`<button class="attention-row" data-view="${destination}"><span class="attention-icon">${icon(ico)}</span><span><strong>${title}</strong><small>${sub}</small></span><b>${count}</b>${icon('arrow')}</button>`).join('')+(d.attention===0?'<div class="clear-state">'+icon('check')+'<span>Keine überfälligen Rechnungen oder offenen Nacharbeiten.</span></div>':'')+(d.backupDue?`<button class="attention-row backup-row" data-action="backup"><span class="attention-icon">${icon('download')}</span><span><strong>Sicherung exportieren</strong><small>${state.settings.lastBackupExportAt?'Letzter Export vor mehr als 7 Tagen':'Noch kein Export auf diesem Gerät erfasst'}</small></span>${icon('arrow')}</button>`:'')}
function focusPage(){const d=dailyOverview(state);return `${pageHeading('Heute wichtig','Offene Schritte, die Geld, Zeit und Daten sichern.')}<div class="metrics">${metric('Überfällige Restbeträge',money(d.overdueTotal),d.overdue.length+' Rechnungen','wallet',true)}${metric('Noch nicht abgerechnet',d.unbilled.length,'Erledigte Aufträge','jobs')}${metric('Vergangene Einsätze',d.missed.length,'Status noch offen','calendar')}${metric('Unter Zielmarge',d.lowMargin.length,'Kalkulation prüfen','euro')}</div><div class="card"><h2>Zahlungseingänge prüfen</h2>${d.overdue.map(i=>`<div class="focus-row"><div><strong>${e(i.number)} · ${e(i.customer.name)}</strong><small>Fällig ${dateText(i.due)} · offen ${money(invoiceBalance(i).open)}</small></div><div class="actions">${btn('Zahlung','pay-invoice','wallet','secondary',`data-id="${e(i.id)}"`)}${btn('Erinnerung / PDF','reminder','print','light',`data-id="${e(i.id)}"`)}</div></div>`).join('')||empty('Keine überfälligen offenen Rechnungen.','check')}</div><div class="card"><h2>Erledigte Aufträge abrechnen</h2>${jobTable(d.unbilled)}</div><div class="card"><h2>Vergangene Einsätze klären</h2>${jobTable(d.missed)}</div><div class="card"><h2>Kalkulation prüfen</h2>${jobTable(d.lowMargin)}<p class="fieldhelp">Hinweise ändern keinen Auftrag und versenden keine Nachricht. Alle Schritte bestätigst du selbst.</p></div><div class="card"><h2>Datensicherung</h2><p>${state.settings.lastBackupExportAt?'Letzter bereitgestellter Export: '+dateText(state.settings.lastBackupExportAt.slice(0,10)): 'Es wurde noch kein Sicherungsexport erfasst.'}</p>${btn('Sicherung exportieren','backup','download')}<p class="fieldhelp">Prüfe, dass die heruntergeladene Datei außerhalb der App gespeichert ist. Der Exportzeitpunkt bestätigt nicht, dass die Datei aufbewahrt wurde.</p></div>`}
function installPage(){const info=getInstallState();return `${pageHeading('WerkPilot als App','Ein eigenes Symbol. Direkter Start vom Home-Bildschirm.')}<div class="card install-card"><img src="icon-192.png" alt="" width="80" height="80"><h2>WerkPilot</h2><p>Gartenpflege · Reinigung · dein Betrieb</p><span class="pill ${info.installed?'':'gray'}">${info.mode==='native'?'Android-App':info.installed?'Bereits im App-Modus':'Installation vorbereiten'}</span><p class="install-message">${e(info.message)}</p>${info.canPrompt?btn('App installieren','install-app','download','full'):''}${info.steps?.length?`<ol class="install-steps">${info.steps.map(step=>`<li>${e(step)}</li>`).join('')}</ol>`:''}<div class="notice">${info.offlineReady?'Die App-Oberfläche ist für den Start ohne Internet gespeichert.':'Für eine installierte Web-App muss WerkPilot einmal über eine sichere HTTPS-Adresse geöffnet werden.'} Sprachdienst und der erste Download des Bildmodells können Internet benötigen.</div><p class="fieldhelp">Eine lokal geöffnete HTML-Datei lässt sich nicht als Web-App installieren. Das mitgelieferte Android-Projekt öffnet WerkPilot direkt vom App-Symbol; es muss zunächst zu einer APK gebaut werden. Eine Play-Store-Veröffentlichung ist nicht enthalten.</p></div><div class="card"><h2>Vor dem Gerätewechsel</h2><p>Die App speichert deinen Bestand lokal. Browser, Web-App und Android-App können getrennte Speicher haben. Exportiere vor dem Wechsel eine JSON-Sicherung und importiere sie in der neuen App.</p>${btn('Daten jetzt sichern','backup','download','secondary')}</div>`}
function moreMenu(){showDialog('Dein Arbeitsplatz',`<nav class="more-grid" aria-label="Alle Arbeitsbereiche">${appNavigation().filter(([id])=>id!=='dashboard').map(([id,title,ico])=>`<button data-view="${id}" class="${view===id?'active':''}"><span>${icon(ico)}</span><b>${title}</b>${icon('arrow')}</button>`).join('')}</nav>`)}
function contactActions(c){const links=contactLinks(c);return `<div class="contact-actions">${links.phone?`<a class="btn secondary small" href="${e(links.phone)}">${icon('users')} Anrufen</a>`:''}${links.maps?`<a class="btn secondary small" href="${e(links.maps)}" target="_blank" rel="noopener">${icon('arrow')} Route öffnen</a>`:''}${links.email?`<a class="btn secondary small" href="${e(links.email)}">${icon('mail')} E-Mail</a>`:''}</div>`}

function metric(label,value,foot,ico='euro',dark=false){return `<div class="metric ${dark?'dark':''}"><div class="metriclabel">${label}${icon(ico)}</div><div class="metricvalue num">${value}</div><div class="metricfoot">${foot}</div></div>`}
function desktopDashboard(){const current=today().slice(0,7),f=financials(state,current),active=state.jobs.filter(j=>!['Erledigt','Storniert'].includes(j.status)),appointments=active.filter(j=>j.status!=='Angebot'&&j.date>=today()).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const projected=active.filter(j=>j.status!=='Angebot').reduce((s,j)=>s+calculate(j,state.settings).profit,0);return `${pageHeading('Alles im grünen Bereich.', 'Ein klarer Blick auf deine Aufträge, deinen Tag und deinen Betrieb.',btn('Neuer Auftrag','new-job','plus'))}${state.demo?'<div class="notice">Beispielbetrieb aktiv. Alle Zahlen sind Demonstrationsdaten. Unter Einstellungen kannst du die Beispieldaten entfernen.</div>':''}<div class="metrics">${metric('Umsatz · Zahlungseingänge',money(f.netRevenue),'Netto · laufender Monat','euro',true)}${metric('Aktive Aufträge',number(active.length),`${active.filter(j=>j.status==='Angebot').length} Angebote · ${active.filter(j=>j.status!=='Angebot').length} Einsätze`,'jobs')}${metric('Offene Rechnungen',money(f.open),'Brutto · alle unbezahlten Rechnungen','wallet')}${metric('Geplanter Deckungsbeitrag',money(projected),'Nach kalkulierten Kosten · vor Steuern','leaf')}</div><div class="grid"><div><div class="card hero"><div><span class="pill">${icon('spark')} DEIN DIGITALER HELFER</span><h2>Aufmaß. Ressourcen. Ein guter Auftrag.</h2><p>Auftrag dokumentieren, Leistung einschätzen und mit deinem Aufmaß sauber kalkulieren.</p>${btn('Foto-Aufmaß starten','photos','camera')}</div><div class="heroart"><div class="orb">${icon('leaf')}</div><span class="floattag one">${icon('camera')} Foto erfassen</span><span class="floattag two">${icon('calc')} Transparent kalkulieren</span></div></div><div class="card"><div class="cardhead"><h2>Deine nächsten Aufträge</h2><button class="linkbtn" data-view="jobs">Alle ansehen ${icon('arrow')}</button></div>${jobTable([...active].sort((a,b)=>(a.date||'9999').localeCompare(b.date||'9999')).slice(0,5),true)}</div><div class="card"><div class="cardhead"><h2>Umsatzentwicklung</h2><span class="pill gray">Zahlungseingänge · netto</span></div>${revenueChart()}</div></div><div><div class="card"><div class="cardhead"><h2>Als Nächstes</h2><button class="linkbtn" data-view="calendar">Kalender ${icon('arrow')}</button></div>${appointments.length?`<div class="timeline">${appointments.slice(0,3).map(j=>`<div class="event"><div class="eventtime">${e(j.time||'–')}</div><div class="eventbody ${(j.lines||[]).some(l=>services.find(s=>s.id===l.service)?.category==='clean')?'clean':''}"><h3>${e(j.title)}</h3><p>${e(jobCustomer(j))} · ${dateText(j.date)}</p><p>${number(j.duration)} Std. &nbsp; <button class="linkbtn" data-action="detail" data-id="${j.id}">Details →</button></p></div></div>`).join('')}</div>`:empty('Dein Kalender ist noch frei.<br>Plane deinen ersten Einsatz.','calendar')}</div><div class="card"><div class="cardhead"><h2>Dein Betriebskompass</h2>${icon('leaf')}</div><div class="smallstat"><span>Zielmarge</span><strong>${number(state.settings.targetMargin)} %</strong></div><div class="bar"><span style="width:${Math.min(100,state.settings.targetMargin)}%"></span></div><div class="smallstat"><span>Interne Arbeitskosten</span><strong>${money(state.settings.hourlyCost)} / Std.</strong></div><div class="smallstat"><span>Betriebskosten</span><strong>${money(state.settings.overhead)} / Std.</strong></div><div class="smallstat"><span>Geräte im Bestand</span><strong>${state.owned.length} von ${equipment.length}</strong></div><div class="insight">${icon('spark')}<span>${active.some(j=>calculate(j,state.settings).margin<state.settings.targetMargin)?'Einige Aufträge liegen unter deiner Zielmarge. Prüfe Arbeitszeit und Preise in der Kalkulation.':'Erfasse Anfahrt, Material und deine eigene Arbeitszeit. So siehst du, was dir vom Auftrag bleibt.'}</span></div></div><div class="card"><h3>${state.activeTimer?'Stoppuhr läuft':'Dein Kleinunternehmer-Check'}</h3><p class="sectiondesc" style="margin-top:8px">${state.activeTimer?e(state.jobs.find(j=>j.id===state.activeTimer.jobId)?.title||'Auftrag')+' · '+timerText():money(annualWatch(state).turnover)+' überwachte Umsätze · Jahr '+state.settings.watchYear}</p><div class="actions">${state.activeTimer?btn('Zeit prüfen','open-time','clock'):btn('Jahresübersicht','open-business','leaf','secondary')}</div></div><div class="card"><h3>Bereit für den ersten Auftrag?</h3><p class="sectiondesc" style="margin-top:8px">Starte mit deinen echten Daten oder lerne den Ablauf am Beispielbetrieb kennen.</p><div class="actions">${btn('Kunde anlegen','new-customer','plus','secondary')}${!state.jobs.length?btn('Beispielbetrieb laden','demo','','light'):btn('Sicherung exportieren','backup','download','light')}</div></div></div></div>`}
function revenueChart(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-5+i);return{key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,name:d.toLocaleDateString('de-DE',{month:'short'})}}).map(m=>({...m,value:financials(state,m.key).netRevenue}));const max=Math.max(1,...months.map(m=>m.value));return `<div class="chart">${months.map(m=>`<div class="chartcol"><span class="chartvalue">${money(m.value)}</span><div class="chartbar" style="height:${Math.max(2,m.value/max*110)}px"></div><small>${m.name}</small></div>`).join('')}</div><div class="chartnote"><span>Nur als bezahlt markierte Rechnungen</span><span>${state.demo?'Beispieldaten':'Deine Geschäftsdaten'}</span></div>`}
function jobTable(jobs,compact=false){return jobs.length?`<div class="jobs-mobile">${mobileJobs(jobs)}</div><div class="tablewrap jobs-desktop"><table><thead><tr><th>AUFTRAG / KUNDE</th>${compact?'':'<th>BEREICH</th>'}<th>TERMIN</th><th>STATUS</th><th>NETTO</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><div class="jobname"><span class="jobicon ${(j.lines||[]).some(l=>services.find(s=>s.id===l.service)?.category==='clean')?'clean':''}">${icon((j.lines||[]).some(l=>services.find(s=>s.id===l.service)?.category==='garden')?'leaf':'clean')}</span><div class="cellmain">${e(j.title)}<div class="cellsub">${e(jobCustomer(j))}</div></div></div></td>${compact?'':`<td>${categoryPill(j)}</td>`}<td>${dateText(j.date)}<div class="cellsub">${e(j.time||'')}</div></td><td>${statusPill(j.status)}</td><td class="amount">${money(calculate(j,state.settings).net)}</td><td><button class="iconbtn" data-action="detail" data-id="${j.id}" aria-label="${e(j.title)} öffnen">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Aufträge. Lege einen Auftrag mit Kunde, Leistungen und Termin an.')}
function jobsPage(){let list=state.jobs.filter(j=>filter==='Alle'||j.status===filter);if(window.searchQuery){const q=window.searchQuery.toLowerCase();list=list.filter(j=>(j.title+' '+jobCustomer(j)).toLowerCase().includes(q))}return `${pageHeading('Aufträge', 'Vom ersten Angebot bis zum erledigten Einsatz.',btn('Neuer Auftrag','new-job','plus'))}<form id="mobile-search-form" class="mobile-search">${icon('search')}<input name="q" value="${e(window.searchQuery||'')}" placeholder="Auftrag oder Kunde suchen" aria-label="Aufträge durchsuchen"><button class="iconbtn" type="submit" aria-label="Suche ausführen">${icon('arrow')}</button></form><div class="tabs">${['Alle',...statuses].map(s=>`<button class="${filter===s?'selected':''}" data-action="filter" data-filter="${s}">${s} <small>(${state.jobs.filter(j=>s==='Alle'||j.status===s).length})</small></button>`).join('')}</div>${window.searchQuery?`<div class="notice">Suche: ${e(window.searchQuery)} <button class="linkbtn" data-action="clear-search">Suche zurücksetzen</button></div>`:''}<div class="card">${jobTable(list)}</div>`}
function field(name,label,value='',type='text',extra='',help=''){return `<div><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}>${help?`<div class="fieldhelp">${help}</div>`:''}</div>`}
function select(name,label,value,options,extra=''){return `<div><label for="${name}">${label}</label><select name="${name}" id="${name}" ${extra}>${options.map(([v,t])=>`<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`).join('')}</select></div>`}
function newDraft(){return{id:uid(),title:'',customer:state.customers[0]?.id||'',status:'Angebot',date:'',time:'09:00',duration:2,lines:[{service:'lawn',qty:100,rate:serviceRate('lawn')}],factor:1,travelHours:.5,setupHours:.25,km:10,travelPrice:15,material:0,disposal:0,rental:0,notes:'',routeFrom:state.settings.homeBase||state.settings.address||'',routeTo:'',siteDetails:{},resources:[],resourceCostsApplied:false,photos:[],checks:[],tax:state.settings.taxMode==='standard'?state.settings.tax:0,taxMode:state.settings.taxMode}}
function calcPage(){draft??=newDraft();return `${pageHeading('Sauber kalkuliert.', 'Plane den Aufwand. Kenne deine Kosten. Verdiene an jedem Auftrag.',btn('Foto hinzufügen','photos','camera','secondary')+btn('Gewerk wählen','open-trades','tools','secondary')+btn('Einsatzplan','open-planner','jobs','secondary'))}<form id="job-form"><div class="grid"><div><div class="card"><h2>Auftrag & Kunde</h2><div class="formgrid">${field('title','Auftragsbezeichnung',draft.title,'text','required maxlength="120" placeholder="z. B. Gartenpflege Familie Müller"')}${select('customer','Kunde',draft.customer,[['','Bitte auswählen'],...state.customers.map(c=>[c.id,c.name])])}${select('status','Status',draft.status,statuses.map(s=>[s,s]))}${field('date','Einsatzdatum',draft.date,'date')}${field('time','Beginn',draft.time,'time')}${field('duration','Geplante Einsatzdauer · Std.',draft.duration,'number','min="0.25" max="72" step="0.25" required')}</div><p class="fieldhelp">${!state.customers.length?'Lege einen Kunden an, damit Angebot und Rechnung korrekt zugeordnet werden können.':'Für mehrere Mitarbeitende getrennte Aufträge anlegen.'}</p>${btn('Kunde anlegen','new-customer','plus','light small')}</div><div class="card"><div class="cardhead"><h2>Leistungen & Aufmaß</h2><span class="pill gray">${draft.taxMode==='small'?'Endpreise ohne Umsatzsteuer':'Netto-Preise'}</span></div><div id="lines">${draft.lines.map((l,i)=>lineForm(l,i)).join('')}</div>${btn('Leistung ergänzen','add-line','plus','light small')}${btn('Vorlage wählen','open-trades','tools','secondary small')}<div class="divider"></div><div class="formgrid">${select('factor','Aufwand / Zeitfaktor',draft.factor,[[.8,'Leicht · 0,8 ×'],[1,'Normal · 1,0 ×'],[1.5,'Aufwendig · 1,5 ×'],[2,'Sehr aufwendig · 2,0 ×']])}${select('taxMode','Steuermodus dieses Auftrags',draft.taxMode||state.settings.taxMode,[['small','Kleinunternehmer · § 19 UStG'],['standard','Regelbesteuerung'],['exempt','Andere Steuerbefreiung']])}${select('tax','Umsatzsteuer',draft.tax,[[0,'0 %'],[7,'7 % · nur bei Berechtigung'],[19,'19 %']],draft.taxMode==='small'?'disabled':'')}</div><div class="notice">Die Richtwerte sind Startannahmen. Menge, Zugänglichkeit und Preise vor Ort prüfen. Der Zeitfaktor verändert die Kosten; passe bei höherem Aufwand auch den Angebotspreis an.</div></div><div class="card"><h2>Anfahrt, Maschinen & Material</h2><div class="formgrid">${field('routeFrom','Startort / Startadresse',draft.routeFrom||state.settings.address||'','text','maxlength="200"')}${field('routeTo','Zielort / Einsatzadresse',draft.routeTo||'','text','maxlength="200"')}${field('km','Anfahrt · km gesamt',draft.km,'number','min="0" max="10000" step="0.1"')}${field('travelHours','Fahrtzeit · Std. gesamt',draft.travelHours,'number','min="0" max="72" step="0.01"')}${field('setupHours','Rüstzeit · Std.',draft.setupHours,'number','min="0" max="72" step="0.25"')}${field('travelPrice',`Anfahrtspauschale · € ${draft.taxMode==='small'?'Endpreis':'netto'}`,draft.travelPrice,'number','min="0" max="100000" step="0.01"')}${field('material',`Zusätzliches Material · € ${draft.taxMode==='small'?'brutto / Kostenbetrag':'netto'}`,draft.material,'number','min="0" max="100000" step="0.01"')}${field('disposal',`Entsorgung · € ${draft.taxMode==='small'?'brutto / Kostenbetrag':'netto'}`,draft.disposal,'number','min="0" max="100000" step="0.01"')}${field('rental',`Maschinenkosten / Gerätemiete · € ${draft.taxMode==='small'?'brutto / Kostenbetrag':'netto'}`,draft.rental,'number','min="0" max="100000" step="0.01"')}<div class="wide"><label for="notes">Aufmaß, Zugang & Absprachen</label><textarea name="notes" id="notes" maxlength="5000" placeholder="Heckenhöhe, Parkmöglichkeit, Wasseranschluss, Schlüssel, Bodenart …">${e(draft.notes)}</textarea></div></div><div class="actions">${btn('Fahrtpreis aus Zeit & km','calculate-travel','calc','light small')}${btn('Route im Kartendienst öffnen','draft-route','calendar','secondary small')}</div><p class="fieldhelp">Fahrtpreis: ${money(state.settings.travelHourlyRate)} / Std. + ${money(state.settings.travelKmRate)} / km. Gesamtstrecke und gesamte Fahrtzeit eintragen. Die Routenansicht berechnet hier keine Kilometer automatisch.</p><p class="fieldhelp">Zusätzliches Material, Entsorgung und Miete werden zum Selbstkostenpreis an den Kunden weiterberechnet. Verbrauchsmaterial aus dem Katalog steckt im Leistungspreis.</p>${siteDetailsForm(draft)}${draft.photos.length?`<div class="photogrid">${draft.photos.map(p=>`<img src="${p.data}" alt="${e(p.name)}">`).join('')}</div>`:''}</div>${resourceForm(draft)}</div><div><div class="card"><h2>Deine Kalkulation</h2><div id="calc-summary">${calcSummary(draft)}</div><div class="divider"></div><div class="actions"><button type="submit" class="btn">${icon('check')} Auftrag speichern</button>${btn('Richtpreis übernehmen','suggest-price','','secondary')}</div><p class="fieldhelp">Gewinnschätzung vor Ertragsteuern. Eigene Arbeit ist als Kosten berücksichtigt. Zeiten sind Personenstunden.</p></div><div class="card"><h2>Was brauchst du?</h2><div id="equipment-summary">${equipmentSummary(draft)}</div></div><div class="card"><h2>Vor Ort prüfen</h2><div id="service-hints">${serviceHints(draft)}</div></div></div></div></form>`}
function lineForm(l,i){const s=services.find(s=>s.id===l.service);return `<div class="lineitem" data-line="${i}">${serviceSelect('service-'+i,'Leistung',l.service,`data-line-field="service" data-index="${i}"`)}${field('qty-'+i,`Menge · ${e(lineUnit(l))}`,l.qty,'number',`min="0.01" max="1000000" step="0.01" required data-line-field="qty" data-index="${i}"`)}${field('rate-'+i,'€ / Einheit',l.rate,'number',`min="0" max="100000" step="0.01" required data-line-field="rate" data-index="${i}"`)}<button type="button" class="iconbtn" data-action="remove-line" data-index="${i}" aria-label="Leistung entfernen">${icon('trash')}</button></div><details class="planner-note"><summary>Leistungsbeschreibung & Zeitannahme</summary><div class="formgrid">${field('description-'+i,'Eigene Leistungsbeschreibung',l.description||'','text',`maxlength="1000" data-line-field="description" data-index="${i}"`)}${field('minutes-'+i,'Personenminuten pro Einheit',l.minutes??s?.minutes??60,'number',`min="0" max="100000" step="0.1" data-line-field="minutes" data-index="${i}"`)}${l.service==='customwork'?select('unit-'+i,'Eigene Leistungseinheit',lineUnit(l),['Std.','m²','lfm','m','Stück','m³','Liter','kg','Pauschal'].map(u=>[u,u]),`data-line-field="unit" data-index="${i}"`):''}</div></details>`}
function calcSummary(j){const c=calculate(j,state.settings),target=j.costSettings?.targetMargin??state.settings.targetMargin;return `${j.costSettings?'<p class="fieldhelp">Kostenbasis dieses Auftrags gespeichert.</p>'+btn('Aktuelle Kostenannahmen verwenden','reset-costs','','light small'):''}${radicalBlocked(j)?'<div class="notice warn">Radikalschnitt im geplanten Zeitraum: grundsätzlich gesperrt (1. März bis 30. September). Termin ändern und Zulässigkeit vor Ort prüfen.</div>':''}${conflicts(j,state.jobs).length?'<div class="notice warn">Terminüberschneidung mit einem anderen aktiven Auftrag. Bitte Beginn oder Dauer anpassen.</div>':''}<div class="summaryrow"><span>Leistungen</span><strong>${money(c.serviceNet)}</strong></div><div class="summaryrow"><span>Anfahrt & Zusatzkosten</span><strong>${money(c.extras)}</strong></div><div class="summaryrow"><span>${j.taxMode==='small'?'Summe ohne Umsatzsteuer':'Gesamt netto'}</span><strong>${money(c.net)}</strong></div>${j.taxMode==='small'?'<div class="notice">Kein Umsatzsteuerausweis · Kleinunternehmer gemäß § 19 UStG.</div>':`<div class="summaryrow"><span>Umsatzsteuer · ${number(j.tax)} %</span><strong>${money(c.tax)}</strong></div>`}<div class="summaryrow total"><span>${j.taxMode==='small'?'Gesamtpreis':'Gesamt brutto'}</span><strong>${money(c.gross)}</strong></div><div class="divider"></div><div class="summaryrow"><span>Arbeits-, Fahrt- & Rüstzeit</span><strong>${number(c.hours)} Std.</strong></div><div class="summaryrow"><span>Arbeitskosten intern</span><strong>${money(c.labor)}</strong></div><div class="summaryrow"><span>Betriebskosten</span><strong>${money(c.overhead)}</strong></div><div class="summaryrow"><span>Verbrauch, Fahrt, Zusatzkosten</span><strong>${money(c.consumables+c.travelCost+c.extraCost)}</strong></div><div class="summaryrow"><span>Kosten gesamt</span><strong>${money(c.costs)}</strong></div><div class="profitbox"><div class="summaryrow"><span>Geschätzter Gewinn</span><strong>${money(c.profit)}</strong></div><div class="summaryrow"><span>Marge</span><strong>${number(c.margin)} %</strong></div></div><div class="notice ${c.margin<target?'warn':''}">${c.margin<target?'Unter deiner Zielmarge. ':'Zielmarge erreicht. '}Für ${number(target)} % Marge benötigst du insgesamt ${money(c.suggested)} netto.</div>`}
function equipmentSummary(j){const required=requiredEquipment(j),missing=required.filter(eq=>!state.owned.includes(eq.id));return required.map(eq=>`<div class="checkitem">${icon(state.owned.includes(eq.id)?'check':'tools')}<span>${e(eq.name)}<div class="fieldhelp">${state.owned.includes(eq.id)?'Im Bestand':'Besorgen / mieten'}</div></span></div>`).join('')+`<div class="notice">${missing.length} Geräte fehlen im Bestand. Orientierungswert für Kauf: ${money(missing.reduce((s,eq)=>s+eq.price,0))}.${missing.some(eq=>!eq.price)?' Für Geräte ohne Preisansatz ein tatsächliches Angebot einholen.':''} Vorhandenes Werkzeug in „Geräte & Material“ markieren.</div>`}
function serviceHints(j){return [...new Set(j.lines.map(l=>l.service))].map(id=>services.find(s=>s.id===id)).filter(Boolean).map(s=>`<p style="font-size:11px"><strong>${e(s.name)}</strong><br>${e(s.hint)}</p>`).join('')}
function customersPage(){let customers=state.customers;if(window.searchQuery)customers=customers.filter(c=>(c.name+' '+c.address+' '+c.email).toLowerCase().includes(window.searchQuery.toLowerCase()));return `${pageHeading('Menschen hinter den Aufträgen.', 'Kontaktdaten, Einsatzorte und Auftragshistorie an einem Platz.',btn('Neuer Kunde','new-customer','plus'))}<form id="customer-search-form" class="customer-search"><input name="q" value="${e(window.searchQuery||'')}" placeholder="Kunde, Adresse oder E-Mail" aria-label="Kunden durchsuchen"><button class="btn secondary" type="submit">Suchen</button></form><div class="customergrid">${customers.map(c=>{const jobs=state.jobs.filter(j=>j.customer===c.id);return `<article class="customer"><div class="avatar">${e(c.name.slice(0,2).toUpperCase())}</div><h3>${e(c.name)}</h3><span class="pill gray">${e(c.type||'Privatkunde')}</span><p>${e(c.address||'Keine Adresse hinterlegt')}</p><p>${e(c.email||'Keine E-Mail hinterlegt')}</p><p>${e(c.phone||'Keine Telefonnummer hinterlegt')}</p>${contactActions(c)}<div class="smallstat"><span>Aufträge</span><strong>${jobs.length}</strong></div><div class="actions">${btn('Bearbeiten','edit-customer','','secondary small',`data-id="${c.id}"`)}${btn('Auftrag','customer-job','plus','light small',`data-id="${c.id}"`)}</div></article>`}).join('')}</div>${!customers.length?`<div class="card">${empty('Erfasse deinen ersten Kunden und lege direkt einen Auftrag an.','users')}</div>`:''}`}
function customerForm(c=null){const data=c||{id:uid(),name:'',type:'Privatkunde',address:'',email:'',phone:'',notes:''};showDialog('Kundendaten',`<form id="customer-form" data-id="${data.id}"><div class="formgrid">${field('name','Name / Firma',data.name,'text','required maxlength="120"')}${select('type','Kundentyp',data.type,[['Privatkunde','Privatkunde'],['Gewerbe','Gewerbe'],['Hausverwaltung','Hausverwaltung'],['Praxis','Praxis']])}<div class="wide">${field('address','Rechnungs- / Einsatzadresse',data.address,'text','maxlength="300"')}</div>${field('email','E-Mail',data.email,'email','maxlength="200"')}${field('phone','Telefon',data.phone,'tel','maxlength="50"')}<div class="wide"><label for="notes">Hinweise & Absprachen</label><textarea id="notes" name="notes" maxlength="2000">${e(data.notes)}</textarea></div></div><div class="divider"></div><div class="actions"><button class="btn" type="submit">${icon('check')} Kunde speichern</button>${c?btn('Kunde löschen','delete-customer','trash','danger',`data-id="${c.id}"`):''}</div></form>`);document.querySelector('#customer-form').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));f.name=f.name.trim();if(!f.name)return;const old=state.customers.findIndex(c=>c.id===data.id);if(old>=0)state.customers[old]={...f,id:data.id};else state.customers.push({...f,id:data.id});if(draft&&!draft.customer)draft.customer=data.id;if(await commit()){dialog.close();toast('Kunde gespeichert')}};guardForm(document.querySelector('#customer-form'))}
function guardForm(form){if(!form?.onsubmit||form.onsubmit.guarded)return;const handler=form.onsubmit;let busy=false;const guarded=async ev=>{ev.preventDefault();if(busy)return;busy=true;const controls=Array.from(form.querySelectorAll?.('button[type="submit"]')||[]);controls.forEach(b=>b.disabled=true);form.setAttribute?.('aria-busy','true');try{return await handler(ev)}finally{busy=false;controls.forEach(b=>b.disabled=false);form.removeAttribute?.('aria-busy')}};guarded.guarded=true;form.onsubmit=guarded}
function showDialog(title,html){dialog.innerHTML=`<div class="dialoghead"><h2>${title}</h2><button class="iconbtn" data-action="close-dialog" aria-label="Schließen">${icon('close')}</button></div>${html}`;if(!dialog.open)dialog.showModal()}
function detail(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;const c=calculate(j,state.settings),invoice=state.invoices.find(i=>i.jobId===j.id);showDialog(e(j.title),`<div class="actions">${statusPill(j.status)}${categoryPill(j)}<span class="pill gray">${dateText(j.date)} ${e(j.time||'')}</span></div><p>${e(jobCustomer(j))} · ${e(customer(j.customer)?.address||'Keine Adresse')}</p>${contactActions(customer(j.customer))}<div class="metrics" style="grid-template-columns:repeat(3,1fr)">${metric('Netto',money(c.net),'Angebotswert')}${metric('Zeitbedarf',number(c.hours)+' Std.','Kalkulierte Personenstunden','clock')}${metric('Gewinnschätzung',money(c.profit),number(c.margin)+' % Marge','leaf',true)}</div><div class="actions">${btn('Bearbeiten','edit-job','','secondary',`data-id="${id}"`)}${btn('Angebot erstellen','create-offer','print','secondary',`data-id="${id}"`)}${btn('Kalenderdatei','ics','calendar','secondary',`data-id="${id}"`)}${btn('Zeit erfassen','job-time','clock','secondary',`data-id="${id}"`)}${btn('Folgeauftrag','follow-up','calendar','secondary',`data-id="${id}"`)}${!invoice&&j.status!=='Storniert'?btn('Rechnung erstellen','invoice','wallet','',`data-id="${id}"`):invoice?`<span class="pill">Rechnung ${e(invoice.number)}</span>`:''}</div><div class="divider"></div><div class="formgrid"><div><h3>Leistungsumfang</h3>${j.lines.map(l=>{const s=services.find(s=>s.id===l.service);return `<div class="summaryrow"><span>${e(lineName(l))}<div class="fieldhelp">${number(l.qty)} ${e(lineUnit(l))} × ${money(l.rate)}</div></span><strong>${money(l.qty*l.rate)}</strong></div>`}).join('')}<p style="font-size:12px;white-space:pre-wrap">${e(j.notes)}</p>${serviceHints(j)}${j.photos.length?`<div class="photogrid">${j.photos.map(p=>`<img src="${p.data}" alt="${e(p.name)}">`).join('')}</div>`:''}</div><div><h3>Checkliste für den Einsatz</h3>${jobTasks(j).map((t,i)=>`<label class="checkitem ${j.checks.includes(t)?'done':''}"><input type="checkbox" data-action="task-check" data-id="${id}" data-task="${e(t)}" ${j.checks.includes(t)?'checked':''}><span>${e(t)}</span></label>`).join('')}</div></div><div class="divider"></div><h3>Nachkalkulation</h3>${actualSummary(j)}<div class="divider"></div><h3>Packliste</h3>${equipmentSummary(j)}<div class="divider"></div><div class="actions">${['Geplant','In Arbeit','Erledigt'].map(s=>btn(s,'job-status','','secondary small',`data-id="${id}" data-status="${s}"`)).join('')}${btn('Auftrag stornieren','job-status','','danger small',`data-id="${id}" data-status="Storniert"`)}</div>`)}
function calendarPage(){const[y,m]=month.split('-').map(Number),d=new Date(y,m-1,1),offset=(d.getDay()+6)%7,days=new Date(y,m,0).getDate();const planned=state.jobs.filter(j=>j.date.startsWith(month)&&!['Storniert','Angebot'].includes(j.status));return `${pageHeading('Gut geplant ist halb erledigt.', 'Deine Einsätze, Zeiten und freien Tage.',btn('Termin eintragen','new-job','plus'))}<div class="card"><div class="cardhead"><h2>${d.toLocaleDateString('de-DE',{month:'long',year:'numeric'})}</h2><div class="monthcontrol"><button class="iconbtn" data-action="month-prev" aria-label="Vorheriger Monat">${icon('back')}</button><button class="linkbtn" data-action="month-today">Heute</button><button class="iconbtn" data-action="month-next" aria-label="Nächster Monat">${icon('arrow')}</button></div></div><div class="calendar">${['Mo','Di','Mi','Do','Fr','Sa','So'].map(n=>`<div class="dayname">${n}</div>`).join('')}${Array(offset).fill('<div class="day blank"></div>').join('')}${Array.from({length:days},(_,i)=>{const date=month+'-'+String(i+1).padStart(2,'0');return `<div class="day ${date===today()?'today':''}" role="button" tabindex="0" data-action="day" data-date="${date}" aria-label="Auftrag für ${dateText(date)} anlegen">${i+1}${planned.filter(j=>j.date===date).map(j=>`<button class="calevent" data-action="detail" data-id="${j.id}" title="${e(j.title)}">${e(j.time)} ${e(j.title)}</button>`).join('')}</div>`}).join('')}</div></div><div class="card"><h2>Einsätze in diesem Monat</h2>${jobTable(planned.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)))}</div><div class="notice">Terminüberschneidungen werden beim Speichern geprüft. Jeder Auftrag kann als .ics-Datei in Apple-, Google- oder Outlook-Kalender importiert werden. Automatische Kalender-Synchronisation ist nicht eingerichtet.</div>`}
function equipmentPage(){return `${pageHeading('Für jeden Einsatz ausgerüstet.','Bestand markieren und Maschinen für jedes Gewerk planen.')}<div class="metrics">${metric('Geräte im Bestand',state.owned.length,'Markierte Werkzeuge','tools',true)}${metric('Orientierungswert Bestand',money(equipment.filter(eq=>state.owned.includes(eq.id)).reduce((s,eq)=>s+eq.price,0)),'Unverbindliche Kaufannahmen','euro')}${metric('Gewerke',businessGroups.length,'Handwerk und Dienstleistungen','tools')}${metric('Katalog',equipment.length,'Werkzeuge und Schutzmaterial','jobs')}</div><div class="notice">Kaufpreise sind grobe Planungswerte. Tatsächliche Einsatz-, Miet- und Verbrauchskosten im Material- und Einsatzplan bestätigen.</div>${businessGroups.map(group=>{const list=equipment.filter(eq=>eq.category===group.id);return list.length?`<section class="card"><h2>${e(group.name)}</h2><div class="equipgrid">${list.map(eq=>`<div class="equipcard">${icon(group.icon||'tools')}<h3>${e(eq.name)}</h3><p>${e(eq.desc)}</p><div class="cost">${eq.price?money(eq.price):'Preis auf Anfrage'} <span class="fieldhelp">${eq.price?'ca. netto · Kauf':'Kaufangebot erforderlich'}</span></div><label class="inlinecheck"><input type="checkbox" data-action="owned" data-id="${eq.id}" ${state.owned.includes(eq.id)?'checked':''}>Im Bestand vorhanden</label></div>`).join('')}</div></section>`:''}).join('')}` }
function matchService(t){const patterns=[['radical',/radikal|radical|auf stock/],['shape',/form.?schnitt|form schneiden/],['hedge',/heck|hedge/],['window',/fenster|glas|window/],['deep',/grundreinig|deep clean/],['stairs',/trepp|stair/],['practice',/praxis|clinic/],['office',/büro|office/],['home',/haushalt/],['house',/hausreinig|reinig|clean/],['weeds',/unkraut|weed/],['lawn',/rasen|mähen|mäh|lawn/],['landscape',/garten|landschaft/]];return services.find(s=>s.id===patterns.find(([,p])=>p.test(t))?.[0])}
function legacyAnswer(text){const t=text.toLowerCase(),s=matchService(t);if(/termin|nächst|ansteh|kalender/.test(t)){const jobs=state.jobs.filter(j=>j.date>=today()&&!['Storniert','Erledigt','Angebot'].includes(j.status)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));return jobs.length?'Deine nächsten Einsätze:\n'+jobs.slice(0,5).map(j=>`${dateText(j.date)} · ${j.time}: ${j.title} bei ${jobCustomer(j)} (${number(j.duration)} Std.)`).join('\n'):'Du hast noch keine bestätigten zukünftigen Einsätze. Unter Termine oder Aufträge kannst du einen Termin eintragen.'}if(/umsatz|buchhalt|rechnung|einnahm/.test(t)){const f=financials(state,today().slice(0,7));return `Im laufenden Monat:\n• Bezahlte Einnahmen ohne Umsatzsteuer: ${money(f.netRevenue)}\n• Erfasste Kostenwerte: ${money(f.deductibleExpenses)}\n• Überschuss aus erfassten Zahlungen: ${money(f.result)}\n• Offene Forderungen brutto, insgesamt: ${money(f.open)}\n\nDer Überschuss enthält keine vollständige steuerliche Gewinnermittlung. Kalkulierte Eigenarbeit ist hier keine gebuchte Ausgabe.`}if(s&&/gerät|werkzeug|material|brauche|benötig|ausrüst/.test(t)){const eq=requiredEquipment({lines:[{service:s.id}]}),missing=eq.filter(eq=>!state.owned.includes(eq.id));return `Für ${s.name} brauchst du:\n${eq.map(eq=>`• ${eq.name} – ${state.owned.includes(eq.id)?'im Bestand':'noch besorgen oder mieten'}`).join('\n')}\n\nFehlende Ausstattung: ca. ${money(missing.reduce((sum,eq)=>sum+eq.price,0))} als unverbindlicher Kauf-Richtwert.\n${s.hint}`}const qtyMatch=t.match(/(\d+(?:[.,]\d+)?)\s*(?:m²|m2|quadratmeter|meter|m\b|lfm|etagen?|stunden?|std)/);if(s&&(qtyMatch||/kalkulier|preis|kost|angebot/.test(t))){if(!qtyMatch)return `Für ${s.name} benötige ich die Menge in ${s.unit}. Schreibe zum Beispiel „Kalkuliere 100 ${s.unit} ${s.name}“. Heckenhöhe, Verschmutzung und Zugang danach in der Kalkulation ergänzen.`;const qty=Number(qtyMatch[1].replace(',','.')),j={...newDraft(),lines:[{service:s.id,qty,rate:serviceRate(s)}]},c=calculate(j,state.settings);window.assistantDraft=j;return `Kalkulation: ${number(qty)} ${s.unit} ${s.name}\n\n• Leistung: ${money(c.serviceNet)} netto\n• Fahrtpauschale: ${money(j.travelPrice)} netto\n• Gesamt: ${money(c.net)} netto / ${money(c.gross)} brutto\n• Zeitbedarf inkl. Fahrt/Rüsten: ${number(c.hours)} Std.\n• Kalkulierte Kosten: ${money(c.costs)}\n• Geschätzter Gewinn vor Steuern: ${money(c.profit)}\n• Marge: ${number(c.margin)} %\n• Preis für ${number(state.settings.targetMargin)} % Zielmarge: ${money(c.suggested)} netto\n\nAnnahmen: normaler Aufwand, 10 km Fahrt, 0,5 Std. Fahrt und 0,25 Std. Rüsten; Umsatzsteuer ${j.tax} %.\n${s.hint}\n\nSchreibe „Übernehmen“, um die Kalkulation zu öffnen.`}if(/übernehm/.test(t)&&window.assistantDraft){draft=window.assistantDraft;view='calc';return 'Die Kalkulation ist vorbereitet. Ergänze Kunde, Titel, Termin und die tatsächlichen Bedingungen und speichere den Auftrag.'}if(/gewinn|marge|lohn|rentab|verdien/.test(t)){const bad=state.jobs.filter(j=>j.status!=='Storniert'&&calculate(j,state.settings).margin<state.settings.targetMargin);return `Deine Zielmarge beträgt ${number(state.settings.targetMargin)} %.\n\n1. Erfasse Fahrt- und Rüstzeit sowie Verbrauch, Entsorgung und Miete.\n2. Berechne Arbeitskosten auch für deine eigene Zeit (${money(state.settings.hourlyCost)} / Std.) und Betriebskosten (${money(state.settings.overhead)} / Std.).\n3. Mindestpreis netto = Gesamtkosten ÷ (1 − Zielmarge). Bei 100 € Kosten und 25 % Marge sind das 133,33 €.\n4. Bündele nahe Einsätze und biete wiederkehrende Pflege an. Vergleiche geplante und tatsächliche Zeiten.\n\n${bad.length?`${bad.length} deiner Aufträge liegen rechnerisch unter der Zielmarge: ${bad.slice(0,4).map(j=>j.title).join(', ')}.`:'Aktuell liegen keine erfassten Aufträge unter der Zielmarge.'}\nAlle Werte sind Schätzungen vor Ertragsteuern.`}if(s)return `${s.name}\n\nRichtwert: ${money(serviceRate(s))} netto / ${s.unit}; ${number(s.minutes)} Minuten / ${s.unit} bei normalem Aufwand.\n\n${s.hint}\n\nArbeitsablauf:\n${s.tasks.map(t=>'• '+t).join('\n')}\n\nFür eine Kalkulation gib die Menge mit Einheit an.`;return 'Ich kann deine Dienstleistungen kalkulieren, Geräte empfehlen, Gewinn prüfen sowie Termine und Umsätze anzeigen.\n\nBitte nenne eine konkrete Leistung, z. B. „50 m² Grundreinigung kalkulieren“, „Welche Geräte für Heckenpflege?“ oder „Wie erhöhe ich meinen Gewinn?“. Für offene Fragen außerhalb des Katalogs habe ich kein allgemeines Sprachmodell.'}
function bindPage(){document.querySelector('#customer-search-form')?.addEventListener('submit',ev=>{ev.preventDefault();window.searchQuery=new FormData(ev.target).get('q').trim();render()});document.querySelector('#mobile-search-form')?.addEventListener('submit',ev=>{ev.preventDefault();window.searchQuery=new FormData(ev.target).get('q').trim();render()});document.querySelector('#search-form')?.addEventListener('submit',ev=>{ev.preventDefault();window.searchQuery=new FormData(ev.target).get('q').trim();view='jobs';filter='Alle';render()});if(view==='calc'){document.querySelector('#job-form').addEventListener('input',ev=>{readDraft(ev.target);updateCalc()});document.querySelector('#job-form').addEventListener('change',ev=>{if(ev.target.dataset.lineField==='service'){const i=+ev.target.dataset.index;draft.lines[i].rate=serviceRate(ev.target.value);delete draft.lines[i].minutes;delete draft.lines[i].unit;document.querySelector('#lines').innerHTML=draft.lines.map(lineForm).join('')}readDraft(ev.target);if(ev.target.dataset.lineField==='unit'){const label=document.querySelector('label[for="qty-'+ev.target.dataset.index+'"]');if(label)label.textContent='Menge · '+lineUnit(draft.lines[+ev.target.dataset.index]);}if(ev.target.name==='taxMode'){draft.tax=draft.taxMode==='standard'?19:0;render();return}updateCalc()});document.querySelector('#job-form').onsubmit=saveJob}if(view==='assistant'){document.querySelector('#chat-form').onsubmit=ev=>{ev.preventDefault();ask(new FormData(ev.target).get('text'),{voiceInput:voiceController.manualPending})};const el=document.querySelector('#chat');el.scrollTop=el.scrollHeight}if(view==='finance')document.querySelector('#finance-month').onchange=ev=>{month=ev.target.value||today().slice(0,7);render()};if(view==='photos')bindPhotosPage();if(view==='settings'){document.querySelector('#settings-form').onsubmit=saveCompanySettings;document.querySelector('#restore').onchange=restore}}
function readDraft(target){if(!draft)return;if(updateResourceField(target))return;if(target.dataset.lineField){const i=+target.dataset.index,key=target.dataset.lineField;if(!draft.lines[i])return;draft.lines[i][key]=['service','description','unit'].includes(key)?target.value:Number(target.value);if(key==='service'||key==='qty')draft.resourceCostsApplied=false;return}const f=new FormData(document.querySelector('#job-form'));for(const k of ['title','customer','status','date','time','notes','taxMode','routeFrom','routeTo'])draft[k]=String(f.get(k)||'');for(const k of ['duration','factor','tax','km','travelHours','setupHours','travelPrice','material','disposal','rental']){const value=Number(f.get(k)||0);if(['material','rental'].includes(k)&&value!==draft[k])draft.resourceCostsApplied=false;draft[k]=value;}if(draft.taxMode!=='standard')draft.tax=0;if(draft.lines.some(l=>['felling','greenhaul','tree','radical','deep','window','practice'].includes(l.service)||tradeGroups.some(g=>g.id===services.find(s=>s.id===l.service)?.category))){draft.siteDetails||={};delete draft.siteDetails.uncertain;for(const key of ['treeHeight','trunkDiameter','greenVolume']){const value=f.get('site-'+key);if(value!==null&&value!=='')draft.siteDetails[key]=Number(value);else delete draft.siteDetails[key]}const access=f.get('site-access');if(access!==null)draft.siteDetails.access=String(access||'unknown');for(const key of ['siteInspected','qualifiedWorkers','permissionsChecked','safetyPlanConfirmed']){if(document.querySelector('#job-form')?.querySelector?.('[name="site-'+key+'"]'))draft.siteDetails[key]=f.get('site-'+key)==='on';}}}
function updateCalc(){document.querySelector('#calc-summary').innerHTML=calcSummary(draft);document.querySelector('#equipment-summary').innerHTML=equipmentSummary(draft);document.querySelector('#service-hints').innerHTML=serviceHints(draft);const resources=document.querySelector('#resource-summary');if(resources)resources.innerHTML=resourceSummaryHTML(draft)}
async function saveJob(ev){ev.preventDefault();readDraft(ev.target);draft.title=draft.title.trim();if(!draft.title){toast('Bitte eine Auftragsbezeichnung eingeben.');return}if(!draft.customer){toast('Bitte einen Kunden auswählen oder anlegen.');return}if((draft.date&&!validISODate(draft.date))||!/^([01]\d|2[0-3]):[0-5]\d$/.test(draft.time)||!Number.isFinite(draft.duration)||draft.duration<.25||draft.duration>72||draft.lines.some(l=>!services.some(s=>s.id===l.service)||!Number.isFinite(l.qty)||l.qty<=0||!Number.isFinite(l.rate)||l.rate<0)){toast('Bitte Datum, Beginn, Dauer und Leistungswerte prüfen.');return}if(!draft.lines.length){toast('Bitte mindestens eine Leistung ergänzen.');return}if(['Geplant','In Arbeit'].includes(draft.status)&&!draft.date){toast('Geplante Einsätze benötigen ein Datum.');return}if(radicalBlocked(draft)&&['Geplant','In Arbeit'].includes(draft.status)){toast('Radikalschnitt bitte außerhalb des grundsätzlich gesperrten Zeitraums planen.');return}if(conflicts(draft,state.jobs).length&&!confirm('Dieser Termin überschneidet sich mit einem anderen Auftrag. Trotzdem speichern?'))return;draft.costSettings??={hourlyCost:state.settings.hourlyCost,overhead:state.settings.overhead,kmCost:state.settings.kmCost,targetMargin:state.settings.targetMargin,taxMode:draft.taxMode,tax:draft.tax};const candidate=structuredClone(state),index=candidate.jobs.findIndex(j=>j.id===draft.id);if(index>=0)candidate.jobs[index]=structuredClone(draft);else candidate.jobs.push(structuredClone(draft));try{state=validateRestore(candidate)}catch(err){toast(err.message);return}const savedId=draft.id;if(await commit()){draft=null;view='jobs';render();toast('Auftrag gespeichert');detail(savedId)}}
async function download(name,content,type){try{if(await saveNativeFile(name,content,type))return true;const a=document.createElement('a');const url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);return true}catch(err){toast('Export fehlgeschlagen: '+err.message);return false}}
function csv(rows){return '\uFEFF'+rows.map(row=>row.map(x=>{let s=String(x??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'}).join(';')).join('\r\n')}
async function backup(){if(recoveryRequired&&unreadableState){await download('werkpilot-rohdaten-'+today()+'.json',JSON.stringify(unreadableState,null,2),'application/json');toast('Ungeprüfte Rohdaten bereitgestellt. Vor einer Wiederherstellung fachlich prüfen.');return}const exported=new Date().toISOString(),copy=structuredClone(state);copy.settings.lastBackupExportAt=exported;try{if(!await download('werkpilot-sicherung-'+today()+'.json',JSON.stringify(copy,null,2),'application/json'))return;state.settings.lastBackupExportAt=exported;try{await persist()}catch{}toast('Sicherung zum Speichern bereitgestellt. Bitte Datei im Download-Ordner oder gewählten Speicherort prüfen.');if(view==='focus')render()}catch(err){toast('Export fehlgeschlagen: '+err.message)}}
function validateRestore(s){return validateBackup(s)}
async function restore(ev){try{const file=ev.target.files[0];if(!file)return;if(file.size>80*1024*1024)throw Error('Sicherung größer als 80 MB.');const restored=validateRestore(JSON.parse(await file.text()));showDialog('Sicherung wiederherstellen',`<p>Die Sicherung enthält ${restored.customers.length} Kunden, ${restored.jobs.length} Aufträge, ${restored.quotes.length} Angebote, ${restored.invoices.length} Rechnungen und ${restored.expenses.length} Ausgaben.</p><div class="notice warn">Dein jetziger Datenbestand wird vollständig ersetzt. Lade vorher eine aktuelle Sicherung herunter.</div><div class="actions">${btn('Aktuellen Bestand sichern','backup','download','secondary')}${btn('Bestand ersetzen','confirm-restore','','danger')}</div>`);window.pendingRestore=restored}catch(err){toast(err.message)}}
function createInvoice(id){const j=state.jobs.find(j=>j.id===id);if(!j||state.invoices.some(i=>i.jobId===id))return;const c=customer(j.customer);if(!c){toast('Bitte einen Kunden zuordnen.');return}if(!j.date){toast('Bitte das Leistungsdatum im Auftrag ergänzen.');return}if(!state.settings.owner||!state.settings.address||!state.settings.taxId||!c.address){toast('Für die Rechnung bitte vollständigen Inhabernamen, Firmenadresse, Steuernummer/USt-IdNr./KU-IdNr. und Kundenadresse ergänzen.');return}const watch=annualWatch(state);if(j.taxMode==='small'&&String(watch.year)===today().slice(0,4)&&(watch.exceeded||watch.priorExceeded)){toast('Umsatzüberwachung meldet eine überschrittene Grenze. Angaben und Steuermodus vor einem neuen §-19-Rechnungsentwurf prüfen.');return}const calc=calculate(j,state.settings),issued=today(),year=issued.slice(0,4),seq=1+Math.max(0,...state.invoices.filter(i=>i.number.startsWith('RE-'+year)).map(i=>Number(i.number.split('-').at(-1))||0));const dueDate=new Date(issued+'T12:00:00');dueDate.setDate(dueDate.getDate()+Number(state.settings.paymentDays));const due=`${dueDate.getFullYear()}-${String(dueDate.getMonth()+1).padStart(2,'0')}-${String(dueDate.getDate()).padStart(2,'0')}`;showDialog('Rechnungsentwurf prüfen',`<p>Empfänger: <strong>${e(c.name)}</strong><br>${e(c.address)}</p><p>Auftrag: ${e(j.title)}<br>Leistungsdatum: ${dateText(j.date)}</p><div class="summaryrow total"><span>Rechnungsbetrag</span><strong>${money(calc.gross)}</strong></div>${j.taxMode==='small'&&String(watch.year)===issued.slice(0,4)&&watch.turnover+calc.net>watch.limit?'<div class="notice warn">Dieser Rechnungsbetrag könnte bei Zahlung die überwachte Grenze überschreiten. Bereits der überschreitende Umsatz kann steuerpflichtig sein. Vor Verwendung Steuerstatus prüfen.</div>':''}<div class="notice">Der gespeicherte Entwurf erhält die fortlaufende Nummer RE-${year}-${String(seq).padStart(4,'0')}. Prüfe Leistungsdatum und Pflichtangaben vor Verwendung. PDF ersetzt keine gegebenenfalls erforderliche strukturierte E-Rechnung.</div><div class="actions">${btn('Entwurf speichern','confirm-invoice','check')}${btn('Abbrechen','close-dialog','','secondary')}</div>`);window.pendingInvoice={id:uid(),jobId:id,number:`RE-${year}-${String(seq).padStart(4,'0')}`,issued,due,paid:'',payments:[],job:structuredClone(j),customer:structuredClone(c),company:structuredClone(state.settings),calc}}
function documentHTML(j,type='Angebot',invoice=null){const settings=invoice?.company||state.settings,c=invoice?.customer||customer(j.customer),calc=invoice?.calc||calculate(j,settings),numberId=invoice?.number||'ANG-'+j.id.slice(0,8).toUpperCase();return `<article class="invoicepage"><header><div><h2>${e(settings.company)}</h2>${e(settings.owner)}<br>${e(settings.address)}<br>${e(settings.email)} · ${e(settings.phone)}${settings.website?'<br>'+e(settings.website):''}</div><div><h1>${type}</h1>${e(numberId)}<br>Datum: ${dateText(invoice?.issued||today())}${invoice?.validUntil?'<br>Gültig bis: '+dateText(invoice.validUntil):''}</div></header><hr><p><strong>${e(c?.name||'Kunde')}</strong><br>${e(c?.address||'Adresse ergänzen')}</p><h2>${e(j.title)}</h2><p>${type.startsWith('Angebot')?'Geplanter Termin':'Leistungsdatum'}: ${dateText(j.date)}</p><table><thead><tr><th>Leistung</th><th>Menge</th><th>${j.taxMode==='small'?'Einzelpreis':'Einzelpreis netto'}</th><th>${j.taxMode==='small'?'Betrag':'Betrag netto'}</th></tr></thead><tbody>${j.lines.map(l=>{const s=services.find(s=>s.id===l.service);return `<tr><td>${e(lineName(l))}</td><td>${number(l.qty)} ${e(lineUnit(l))}</td><td>${money(l.rate)}</td><td>${money(l.qty*l.rate)}</td></tr>`}).join('')}${[['Anfahrtspauschale',j.travelPrice],['Zusatzmaterial',j.material],['Entsorgung',j.disposal],['Gerätemiete',j.rental]].filter(([,v])=>v>0).map(([label,v])=>`<tr><td>${label}</td><td>1</td><td>${money(v)}</td><td>${money(v)}</td></tr>`).join('')}</tbody></table>${j.resourceCostsApplied&&(j.resources||[]).some(r=>r.use)?`<h3>Vereinbartes Material & Maschineneinsatz</h3><p>In den oben genannten Material- und Maschinenkosten enthalten:</p><ul>${j.resources.filter(r=>r.use).map(r=>`<li>${e(r.name)} · ${number(r.quantity)} ${e(r.unit)}</li>`).join('')}</ul>`:''}<div class="sum"><p>${j.taxMode==='small'?'Leistungssumme ohne Umsatzsteuer':'Gesamt netto'}: ${money(calc.net)}${j.taxMode==='small'?'':`<br>Umsatzsteuer (${number(j.taxMode==='exempt'?0:j.tax)} %): ${money(calc.tax)}`}</p><p class="total"><strong>Gesamtbetrag: ${money(calc.gross)}</strong></p></div>${j.taxMode==='small'?'<p>Für diese Leistung gilt die Steuerbefreiung für Kleinunternehmer gemäß § 19 UStG. Umsatzsteuer wird nicht ausgewiesen.</p>':j.taxMode==='exempt'||j.tax===0?'<p>Steuerbefreiungsgrund vor Verwendung ergänzen.</p>':''}<p style="white-space:pre-wrap">${e(j.notes)}</p>${type.startsWith('Angebot')&&settings.offerFooter?'<p style="white-space:pre-wrap">'+e(settings.offerFooter)+'</p>':''}${type.startsWith('Angebot')?'<p>Dieses Angebot basiert auf dem erfassten Aufmaß. Zusätzliche Leistungen nur nach Abstimmung. Bitte Umfang, Termin und Preis vor Ausführung bestätigen.</p>':`<p>Bitte überweise ${money(calc.gross)} bis ${dateText(invoice.due)} unter Angabe von ${e(numberId)}.<br>IBAN: ${e(settings.iban||'Bankverbindung ergänzen')}</p>`}<hr><p>Steuernummer / USt-IdNr.: ${e(settings.taxId||'Bitte ergänzen')}<br>${e(settings.company)} · ${e(settings.address)}</p></article>`}
function printHTML(html){if(printNative(html))return;document.querySelector('#print').innerHTML=html;window.print()}
function exportICS(id){const j=state.jobs.find(j=>j.id===id);if(!j?.date||!j.time){toast('Bitte zuerst Datum und Uhrzeit eintragen.');return}const dt=new Date(`${j.date}T${j.time}:00`),end=new Date(+dt+(Number(j.duration)||1)*3600000),fmt=d=>d.toISOString().replaceAll('-','').replaceAll(':','').replace(/\.\d{3}/,'');const esc=s=>String(s||'').replaceAll('\\','\\\\').replaceAll('\n','\\n').replaceAll(',','\\,').replaceAll(';','\\;');const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//WerkPilot//DE','BEGIN:VEVENT',`UID:${j.id}@werkpilot`,`DTSTAMP:${fmt(new Date())}`,`DTSTART:${fmt(dt)}`,`DTEND:${fmt(end)}`,`SUMMARY:${esc(j.title+' · '+jobCustomer(j))}`,`LOCATION:${esc(customer(j.customer)?.address)}`,`DESCRIPTION:${esc(j.notes)}`,'END:VEVENT','END:VCALENDAR'];const folded=lines.map(line=>Array.from(line).reduce((out,ch)=>{const last=out.length-1;if(new TextEncoder().encode(out[last]+ch).length>70)out.push(' '+ch);else out[last]+=ch;return out},['']).join('\r\n')).join('\r\n');download('werkpilot-termin.ics',folded,'text/calendar;charset=utf-8')}
async function demo(){if(state.jobs.length||state.customers.length||state.invoices.length||state.expenses.length){toast('Beispieldaten können nur in einen leeren Betrieb geladen werden.');return}state.demo=true;const addresses=['Parkstraße 14, 10115 Berlin','Lindenweg 8, 10117 Berlin','Hauptstraße 32, 10119 Berlin'];state.customers=['Familie Müller','Praxis Dr. Weber','Hausverwaltung Nord'].map((name,i)=>({id:uid(),name,address:addresses[i],type:i===1?'Praxis':i===2?'Hausverwaltung':'Privatkunde',email:['mueller@example.com','praxis@example.com','verwaltung@example.com'][i],phone:'+49 30 000000',notes:'Beispielkunde'}));const relative=(offset)=>{const d=new Date();d.setDate(d.getDate()+offset);return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};const definitions=[['Herbstpflege & Hecken',0,'hedge',35,13,'Geplant',1,'08:30',3],['Regelmäßige Praxisreinigung',1,'practice',120,3.6,'Geplant',1,'14:00',6],['Treppenhaus · 4 Etagen',2,'stairs',4,30,'Angebot',3,'09:00',2],['Rasen & Kantenpflege',0,'lawn',250,.9,'Erledigt',-7,'10:00',3],['Fenster im Bürogebäude',2,'window',55,7.2,'Erledigt',-10,'09:00',5]];state.jobs=definitions.map(([title,ci,service,qty,rate,status,offset,time,duration])=>({...newDraft(),id:uid(),title,customer:state.customers[ci].id,lines:[{service,qty,rate}],status,date:relative(offset),time,duration,notes:'Beispielauftrag – Werte dienen zur Demonstration.',disposal:service==='hedge'?30:0}));state.owned=['mower','trimmer','ppe','vacuum','mop','cloths','gloves'];state.settings={...state.settings,company:'Grün & Klar · Beispielbetrieb',owner:'Max Muster',address:'Beispielweg 1, 10115 Berlin',taxId:'BEISPIEL – NICHT VERWENDEN',iban:'BEISPIEL – NICHT VERWENDEN'};state.jobs.filter(j=>j.status==='Erledigt').forEach((j,i)=>{const issued=relative(-7+i),due=relative(7+i);state.invoices.push({id:uid(),jobId:j.id,number:`DEMO-${today().slice(0,4)}-${String(i+1).padStart(4,'0')}`,issued,due,paid:i===0?relative(-5):'',job:structuredClone(j),company:structuredClone(state.settings),customer:structuredClone(customer(j.customer)),calc:calculate(j,state.settings)})});state.expenses=[{id:uid(),date:relative(-5),description:'Mikrofasertücher · Beispiel',category:'Material',gross:35.7,tax:19,taxMode:state.settings.taxMode,receipt:null},{id:uid(),date:relative(-3),description:'Kraftstoff · Beispiel',category:'Fahrzeug',gross:59.5,tax:19,taxMode:state.settings.taxMode,receipt:null}];if(await commit())toast('Beispielbetrieb geladen. Alle Werte sind Demonstrationsdaten.')}
async function handleAction(action,target){const id=target.dataset.id;if(await handleHandworkAction(action,target))return;if(await handleVoiceAction(action,target))return;if(await handleProAction(action,target))return;if(await handleV2(action,target))return;switch(action){
case'menu':case'more':moreMenu();break;
case'install-app':{const result=await requestInstall();if(result.outcome==='accepted')toast('Installation bestätigt. Bitte das App-Symbol auf deinem Home-Bildschirm prüfen.');else if(result.outcome==='dismissed')toast('Installation abgebrochen.');render();break;}
case'reset-costs':draft.costSettings={hourlyCost:state.settings.hourlyCost,overhead:state.settings.overhead,kmCost:state.settings.kmCost,targetMargin:state.settings.targetMargin};render();toast('Aktuelle Kostenannahmen übernommen. Ergebnis vor dem Speichern prüfen.');break;
case'new-job':draft=newDraft();view='calc';render();break;
case'new-customer':customerForm();break;
case'edit-customer':customerForm(customer(id));break;
case'customer-job':draft=newDraft();draft.customer=id;view='calc';render();break;
case'delete-customer':if(state.jobs.some(j=>j.customer===id)||state.invoices.some(i=>i.customer.id===id)||state.quotes.some(q=>q.customer.id===id)){toast('Kunde ist mit Aufträgen oder Rechnungen verknüpft und kann nicht gelöscht werden.');break}if(confirm('Diesen Kunden löschen?')){state.customers=state.customers.filter(c=>c.id!==id);if(await commit())dialog.close()}break;
case'detail':detail(id);break;
case'edit-job':{const j=state.jobs.find(j=>j.id===id);draft=structuredClone(j);dialog.close();view='calc';render();break}
case'close-dialog':dialog.close();break;
case'filter':filter=target.dataset.filter;render();break;
case'clear-search':window.searchQuery='';render();break;
case'add-line':draft.lines.push({service:'home',qty:50,rate:serviceRate('home')});document.querySelector('#lines').innerHTML=draft.lines.map(lineForm).join('');updateCalc();break;
case'remove-line':draft.lines.splice(+target.dataset.index,1);document.querySelector('#lines').innerHTML=draft.lines.map(lineForm).join('');updateCalc();break;
case'suggest-price':{const c=calculate(draft,state.settings);if(!c.serviceNet){toast('Bitte zuerst Leistungen mit Menge und Preis eingeben.');break}const factor=Math.max(0,c.suggested-c.extras)/c.serviceNet;draft.lines=draft.lines.map(l=>({...l,rate:Math.ceil(l.rate*factor*100)/100}));document.querySelector('#lines').innerHTML=draft.lines.map(lineForm).join('');updateCalc();toast('Einheitspreise an die Zielmarge angepasst. Bitte prüfen.');break}
case'job-status':{const j=state.jobs.find(j=>j.id===id),s=target.dataset.status;if(!j||!statuses.includes(s))break;if(['Geplant','In Arbeit'].includes(s)&&!j.date){toast('Bitte zuerst ein Einsatzdatum festlegen.');break}if(['Geplant','In Arbeit'].includes(s)&&radicalBlocked(j)){toast('Radikalschnitt im gesperrten Zeitraum. Bitte Termin prüfen.');break}if(['Geplant','In Arbeit'].includes(s)&&conflicts({...j,status:s},state.jobs).length&&!confirm('Dieser Termin überschneidet sich mit einem anderen Auftrag. Trotzdem planen?'))break;if(['Storniert','Erledigt'].includes(s)&&state.activeTimer?.jobId===j.id){toast('Bitte zuerst die laufende Stoppuhr für diesen Auftrag speichern oder stoppen.');break}if(s==='Storniert'&&!confirm('Auftrag stornieren? Bereits erstellte Rechnungen bleiben bestehen.'))break;if(s==='Erledigt'&&jobTasks(j).some(t=>!j.checks.includes(t))&&!confirm('Noch nicht alle Checklistenpunkte sind abgehakt. Auftrag trotzdem als erledigt markieren?'))break;j.status=s;if(await commit()){detail(id);toast('Auftragsstatus aktualisiert')}break}
case'task-check':{const j=state.jobs.find(j=>j.id===id);const t=target.dataset.task;j.checks=target.checked?[...new Set([...j.checks,t])]:j.checks.filter(c=>c!==t);try{await persist();target.closest('label').classList.toggle('done',target.checked)}catch{detail(id);toast('Checkliste konnte nicht gespeichert werden. Gespeicherter Stand wiederhergestellt.');}break}
case'owned':state.owned=target.checked?[...new Set([...state.owned,id])]:state.owned.filter(x=>x!==id);await commit();break;
case'month-prev':case'month-next':{const[y,m]=month.split('-').map(Number),date=new Date(y,m-1+(action==='month-next'?1:-1),1);month=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0');render();break}
case'month-today':month=today().slice(0,7);render();break;
case'day':draft=newDraft();draft.date=target.dataset.date;draft.status='Geplant';view='calc';render();break;
case'backup':await backup();break;
case'confirm-restore':if(window.pendingRestore){const recovery=recoveryRequired;state=validateRestore(window.pendingRestore);recoveryRequired=false;if(await commit()){draft=null;window.pendingRestore=null;unreadableState=null;dialog.close();toast('Sicherung wiederhergestellt')}else{recoveryRequired=recovery;render()}}break;
case'demo':await demo();break;
case'reset-demo':if(state.demo){showDialog('Beispieldaten entfernen',`<div class="notice warn">Alle Daten dieses Beispielbetriebs werden entfernt. Auch eigene Änderungen seit dem Laden der Beispieldaten gehen verloren.</div><div class="actions">${btn('Vorher sichern','backup','download','secondary')}${btn('Alle Beispieldaten entfernen','confirm-reset','','danger')}</div>`)}break;
case'confirm-reset':state=initial();draft=null;view='dashboard';if(await commit()){dialog.close();toast('Beispieldaten entfernt. Dein Betrieb ist leer.')}break;
case'export-customers':download('werkpilot-kunden.csv',csv([['Name','Typ','Adresse','E-Mail','Telefon','Hinweise'],...state.customers.map(c=>[c.name,c.type,c.address,c.email,c.phone,c.notes])]),'text/csv;charset=utf-8');break;
case'photos':if(view==='calc')readDraft(document.querySelector('#job-form'));view='photos';render();break;
case'analyze-photo':await analyzePhoto();break;
case'photo-service':rememberPhotoForm();photoServiceChoice=id;dialog.close();render();toast('Leistung bestätigt. Bitte gemessene Menge und Zugang ergänzen.');break;
case'attach-photo':rememberPhotoForm();if(!draft){draft=newDraft();draft.lines=[];draft.km=0;draft.travelHours=0;draft.travelPrice=0;}if(photo)mergeDraftPhoto(attachPhotoMetadata());view='calc';render();toast('Foto dem aktuellen Auftragsentwurf hinzugefügt.');break;
case'voice':voice();break;
case'ask':await ask(target.dataset.text);break;
case'speech-toggle':state.settings.speech=target.checked;await persist();if(!target.checked&&'speechSynthesis'in window)window.speechSynthesis.cancel();break;
case'settings':view='settings';render();break;
case'new-expense':await expenseForm();break;
case'edit-expense':await expenseForm('',id);break;
case'delete-expense':{const ex=state.expenses.find(x=>x.id===id);if(!ex)break;if(!confirm('Falsch erfasste Ausgabe '+ex.description+' ('+money(ex.gross)+') entfernen? Dies korrigiert den Datenbestand; eine echte Rückzahlung separat erfassen.'))break;state.expenses=state.expenses.filter(x=>x.id!==id);const j=state.jobs.find(j=>j.id===ex.jobId);if(j)j.actualCostsComplete=false;if(await commit()){dialog.close();toast('Falscher Ausgabeneintrag entfernt.')}break;}
case'invoice':createInvoice(id);break;
case'confirm-invoice':if(window.pendingInvoice){const i=window.pendingInvoice;if(state.invoices.some(x=>x.jobId===i.jobId)){toast('Für diesen Auftrag besteht bereits eine Rechnung.');break}state.invoices.push(i);if(await commit()){window.pendingInvoice=null;dialog.close();view='finance';month=i.issued.slice(0,7);render();toast('Rechnungsentwurf gespeichert. PDF vor Verwendung prüfen.')}}break;
case'invoice-print':{const i=state.invoices.find(i=>i.id===id);printHTML(documentHTML(i.job,'Rechnung',i));break}
case'quote':{const j=state.jobs.find(j=>j.id===id);printHTML(documentHTML(j));break}
case'export-finance':exportFinance();break;
case'ics':exportICS(id);break;
case'receipt':{const ex=state.expenses.find(x=>x.id===id);showDialog(e(ex.description),`<img class="photopreview" src="${ex.receipt.data}" alt="Belegfoto">`);break}
}}
document.addEventListener('click',async ev=>{const target=ev.target.closest('[data-action],[data-view]');if(!target)return;if(target.tagName==='BUTTON'&&!target.hasAttribute('type'))ev.preventDefault();try{if(target.dataset.view){if(target.dataset.view!=='assistant')stopVoice();view=target.dataset.view;window.searchQuery='';filter='Alle';dialog.close();render();window.scrollTo({top:0});return}if(target.matches('input[type=checkbox]'))return;await handleAction(target.dataset.action,target)}catch(err){toast('Aktion konnte nicht abgeschlossen werden. '+err.message)}});
document.addEventListener('change',async ev=>{if(!ev.target.matches('input[type=checkbox][data-action]'))return;try{await handleAction(ev.target.dataset.action,ev.target)}catch{toast('Änderung konnte nicht gespeichert werden.')}});
document.addEventListener('keydown',ev=>{const t=ev.target;if(t.matches('.day[data-action]')&&['Enter',' '].includes(ev.key)){ev.preventDefault();t.click()}});
dialog.addEventListener('click',ev=>{if(ev.target===dialog){const r=dialog.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)dialog.close()}});
function paymentStatus(i){const b=invoiceBalance(i);return b.settled?'Bezahlt':b.partial?'Teilbezahlt':i.due<today()?'Überfällig':'Offen'}
function paymentDialog(id){const i=state.invoices.find(i=>i.id===id);if(!i)return;const balance=invoiceBalance(i);showDialog('Zahlung erfassen',`<p><strong>${e(i.number)}</strong> · ${e(i.customer.name)}</p><div class="summaryrow"><span>Rechnungsbetrag</span><strong>${money(i.calc.gross)}</strong></div><div class="summaryrow"><span>Schon bezahlt</span><strong>${money(balance.paid)}</strong></div><div class="summaryrow total"><span>Offen</span><strong>${money(balance.open)}</strong></div>${balance.open?`<form id="payment-form"><div class="formgrid">${field('paid','Zahlungseingang am',today(),'date',`required max="${today()}"`)}${field('amount','Eingegangener Betrag · €',balance.open,'number',`min="0.01" max="${balance.open}" step="0.01" required`)}${select('method','Zahlungsart','Überweisung',['Überweisung','Bar','Karte','Sonstiges'].map(s=>[s,s]))}${field('note','Beleg / Notiz','','text','maxlength="300"')}</div><div class="divider"></div><button class="btn" type="submit">${icon('check')} Zahlung speichern</button><p class="fieldhelp">Auch Teilzahlungen möglich. Nur tatsächlich eingegangene Beträge erfassen. Überzahlungen werden verhindert.</p></form>`:''}<div class="divider"></div><h3>Zahlungsverlauf</h3>${invoicePayments(i).map(p=>`<div class="summaryrow"><span>${dateText(p.date)} · ${e(p.method||'Überweisung')}<div class="fieldhelp">${e(p.note||'')}</div></span><div><strong>${money(p.amount)}</strong> ${btn('Falschen Eintrag entfernen','remove-payment','trash','danger small',`data-id="${i.id}" data-payment-id="${e(p.id)}"`)}</div></div>`).join('')||empty('Noch keine Zahlung erfasst.','wallet')}`);const form=document.querySelector('#payment-form');if(balance.open&&form)form.onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));try{const currentInvoice=state.invoices.find(x=>x.id===id);if(!currentInvoice)throw Error('Rechnung nicht mehr vorhanden.');recordPayment(currentInvoice,{id:uid(),date:f.paid,amount:+f.amount,method:f.method,note:f.note});if(await commit()){dialog.close();toast('Zahlung erfasst. Restbetrag: '+money(invoiceBalance(currentInvoice).open))}}catch(err){toast(err.message)}};guardForm(document.querySelector('#payment-form'))}

function invoiceTiles(invoices){return `<div class="invoice-mobile">${invoices.map(i=>{const b=invoiceBalance(i);return `<article class="finance-tile"><div class="finance-tile-heading"><div><strong>${e(i.number)}</strong><small>${e(i.customer.name)}</small></div><span class="pill ${b.settled?'':i.due<today()?'red':'amber'}">${paymentStatus(i)}</span></div><div class="finance-tile-amount"><strong>${money(b.open)}</strong><span>${b.settled?'bezahlt':'noch offen'} · fällig ${dateText(i.due)}</span></div><small>Gesamt ${money(i.calc.gross)} · bezahlt ${money(b.paid)}</small><div class="actions">${btn('PDF','invoice-print','print','secondary small',`data-id="${e(i.id)}"`)}${btn(b.open?'Zahlung':'Zahlungen','pay-invoice','wallet','light small',`data-id="${e(i.id)}"`)}${b.open&&i.due<today()?btn('Erinnerung','reminder','','light small',`data-id="${e(i.id)}"`):''}</div></article>`}).join('')}</div>`}
function expenseTiles(expenses){return `<div class="expense-mobile">${expenses.map(ex=>`<article class="finance-tile"><div class="finance-tile-heading"><div><strong>${e(ex.description)}</strong><small>${dateText(ex.date)} · ${e(ex.category)}</small></div><b>${money(ex.gross)}</b></div><small>${e(state.jobs.find(j=>j.id===ex.jobId)?.title||'Allgemeine Betriebsausgabe')}</small><small>Kostenwert ${money(expenseCost(ex,state.settings))} · Beleg ${e(ex.reference||'nicht angegeben')}</small><div class="actions">${btn('Korrigieren','edit-expense','','secondary small',`data-id="${e(ex.id)}"`)}${ex.receipt?btn('Belegfoto','receipt','camera','light small',`data-id="${e(ex.id)}"`):''}</div></article>`).join('')}</div>`}

function financePage(){const f=financials(state,month),small=state.settings.taxMode==='small',shown=financeFilter==='open'?state.invoices.filter(i=>invoiceBalance(i).open>0):f.invoices,overdue=state.invoices.filter(i=>invoiceBalance(i).open>0&&i.due<today());return `${pageHeading('Was verdient wurde. Was noch kommt.', 'Teilzahlungen, offene Beträge, Belege und deine Betriebsausgaben.',btn('Ausgabe erfassen','new-expense','plus'))}<div class="actions" style="margin-bottom:20px"><input type="month" id="finance-month" value="${month}" aria-label="Buchhaltungsmonat" style="width:180px">${btn('CSV exportieren','export-finance','download','secondary')}${btn('Monatsbericht / PDF','finance-print','print','secondary')}</div><div class="metrics">${metric('Bezahlte Einnahmen',money(f.netRevenue),small?'Ohne Umsatzsteuer':'Ohne enthaltene Umsatzsteuer','euro',true)}${metric('Betriebliche Ausgaben',money(f.deductibleExpenses),small?'Brutto · kein Vorsteuerabzug':'Vereinfachter Nettokostenwert','wallet')}${metric('Erfasster Überschuss',money(f.result),'Vor Ertragsteuern · keine amtliche EÜR','leaf')}${metric('Offene Forderungen',money(f.open),'Restbeträge · alle Monate','clock')}</div>${overdue.length?`<div class="notice warn">${overdue.length} Rechnung(en) überfällig · noch ${money(overdue.reduce((a,i)=>a+invoiceBalance(i).open,0))} offen. Bereits erfasste Teilzahlungen sind abgezogen.</div>`:''}<div class="card"><div class="cardhead"><h2>Rechnungen</h2><div class="actions">${btn('Monat','finance-month','','secondary small')}${btn('Alle offenen','finance-open','','light small')}</div></div><p class="fieldhelp">${financeFilter==='open'?'Offene Restbeträge aus allen Monaten':'Ausgestellt im '+month}</p>${shown.length?`${invoiceTiles(shown)}<div class="tablewrap finance-desktop"><table><thead><tr><th>NUMMER / KUNDE</th><th>FÄLLIG</th><th>GESAMT</th><th>BEZAHLT / OFFEN</th><th>STATUS</th><th></th></tr></thead><tbody>${shown.map(i=>{const b=invoiceBalance(i);return `<tr><td class="cellmain">${e(i.number)}<div class="cellsub">${e(i.customer.name)} · ${dateText(i.issued)}</div></td><td>${dateText(i.due)}</td><td class="amount">${money(i.calc.gross)}</td><td>${money(b.paid)} bezahlt<div class="cellsub">${money(b.open)} offen</div></td><td><span class="pill ${b.settled?'':i.due<today()?'red':'amber'}">${paymentStatus(i)}</span></td><td><div class="actions">${btn('PDF','invoice-print','print','secondary small',`data-id="${i.id}"`)}${btn(b.open?'Zahlung erfassen':'Zahlungen ansehen','pay-invoice','','light small',`data-id="${i.id}"`)}${b.open&&i.due<today()?btn('Erinnerung','reminder','','secondary small',`data-id="${i.id}"`):''}</div></td></tr>`}).join('')}</tbody></table></div>`:empty('Noch keine Rechnungen in diesem Monat. Erstelle sie über die Auftragsdetails.','wallet')}</div><div class="card"><h2>Zahlungseingänge in diesem Monat</h2>${f.payments.length?`<div class="tablewrap"><table><thead><tr><th>DATUM</th><th>RECHNUNG / KUNDE</th><th>ZAHLUNGSART</th><th>BETRAG</th></tr></thead><tbody>${f.payments.map(p=>`<tr><td>${dateText(p.date)}</td><td>${e(p.number)}<div class="cellsub">${e(p.customer.name)}</div></td><td>${e(p.method||'Überweisung')}</td><td>${money(p.calc.gross)}</td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Zahlungen im gewählten Monat.','wallet')}</div><div class="card"><h2>Betriebsausgaben & Belege</h2>${f.expenses.length?`${expenseTiles(f.expenses)}<div class="tablewrap finance-desktop"><table><thead><tr><th>DATUM / BELEGNR.</th><th>AUSGABE / AUFTRAG</th><th>KATEGORIE</th><th>BRUTTO</th><th>KOSTENWERT</th><th>BELEG</th></tr></thead><tbody>${f.expenses.map(ex=>`<tr><td>${dateText(ex.date)}<div class="cellsub">${e(ex.reference||'–')}</div></td><td>${e(ex.description)}<div class="cellsub">${e(state.jobs.find(j=>j.id===ex.jobId)?.title||'Allgemeine Betriebsausgabe')}</div></td><td>${e(ex.category)}</td><td>${money(ex.gross)}</td><td>${money(expenseCost(ex,state.settings))}</td><td>${ex.receipt?btn('Beleg','receipt','','secondary small',`data-id="${ex.id}"`):'<span class="cellsub">Kein Beleg</span>'}${btn('Korrigieren','edit-expense','','light small',`data-id="${e(ex.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Material, Fahrt, Entsorgung oder Gerätemiete erfassen und dem Auftrag zuordnen.','wallet')}</div><div class="notice">Einnahmen werden nach Zahlungsdatum ausgewertet. Im Kleinunternehmer-Modus zählen Ausgaben inklusive Umsatzsteuer. Geräteanschaffungen sind im Zahlungsfluss enthalten; Abschreibungen und weitere steuerliche Korrekturen sind nicht automatisch abgebildet. Keine amtliche EÜR und keine GoBD-konforme Buchhaltung.</div>`}
function settingsPage(){return `${pageHeading('Dein Betrieb, deine Regeln.', 'Kleinunternehmer-Modus, Kosten und sichere Datenübernahme.')}<form id="settings-form"><div class="grid"><div><div class="card"><h2>Firmendaten & Rechnungsangaben</h2><div class="formgrid">${field('company','Firmenname',state.settings.company,'text','required maxlength="150"')}${field('owner','Vollständiger Name des Inhabers',state.settings.owner,'text','maxlength="100"')}<div class="wide">${field('address','Vollständige Geschäftsadresse',state.settings.address,'text','maxlength="300"')}</div>${field('email','E-Mail',state.settings.email,'email','maxlength="200"')}${field('phone','Telefon',state.settings.phone,'tel','maxlength="50"')}${field('website','Firmenwebsite',state.settings.website||'','url','maxlength="200"')}${field('taxId','Steuernummer / USt-IdNr. / KU-IdNr.',state.settings.taxId,'text','maxlength="60"')}${field('iban','IBAN',state.settings.iban,'text','maxlength="40"')}${field('paymentDays','Zahlungsziel · Tage',state.settings.paymentDays,'number','min="1" max="180" required')}</div></div><div class="card"><h2>Angebote & Firmenauftritt</h2><div class="formgrid">${field('quotePrefix','Angebotspräfix',state.settings.quotePrefix,'text','required maxlength="12" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,11}"')}${field('quoteDays','Angebotsgültigkeit · Tage',state.settings.quoteDays,'number','min="1" max="365" required')}<div class="wide"><label for="offerFooter">Eigener Abschlusstext für neue Angebote</label><textarea id="offerFooter" name="offerFooter" maxlength="2000" placeholder="Zum Beispiel: Vielen Dank für Ihr Vertrauen.">${e(state.settings.offerFooter||'')}</textarea></div></div><p class="fieldhelp">Nummer und Preisstand werden beim Erstellen eingefroren. Firmenänderungen verändern bestehende Angebote nicht.</p><button type="button" class="btn light small" data-view="rates">Eigene Leistungspreise einrichten</button></div><div class="card"><h2>Steuermodus</h2><div class="formgrid">${select('taxMode','Steuerliche Behandlung',state.settings.taxMode,[['small','Kleinunternehmer · § 19 UStG'],['standard','Regelbesteuerung'],['exempt','Andere Steuerbefreiung']])}${select('tax','Standard-Steuersatz bei Regelbesteuerung',state.settings.tax,[[0,'0 %'],[7,'7 % · nur bei Berechtigung'],[19,'19 %']])}</div><div class="notice">§ 19-Modus: Neue Aufträge ohne Umsatzsteuer, Rechnungshinweis automatisch, Ausgaben ohne Vorsteuerabzug. Bestehende Aufträge behalten ihren Steuermodus; bestehende Rechnungsstände bleiben unverändert. Wähle den Modus passend zu deinem tatsächlichen Steuerstatus.</div><div class="formgrid">${field('businessStart','Beginn der unternehmerischen Tätigkeit',state.settings.businessStart,'date')}${field('watchYear','Jahr der Umsatzüberwachung',state.settings.watchYear,'number','min="2025" max="2100" required')}${field('previousTurnover','Zusätzlicher Vorjahresumsatz · €',state.settings.previousTurnover,'number','min="0" step="0.01" required','Nur Umsätze, die nicht bereits als Zahlung in der App stehen.')}${field('externalTurnover','Zusätzlicher Umsatz im Überwachungsjahr · €',state.settings.externalTurnover,'number','min="0" step="0.01" required','Andere Tätigkeiten / außerhalb der App erfasste Zahlungen, ohne Doppelzählung.')}</div></div><div class="card"><h2>Kosten & Rücklagen</h2><div class="formgrid">${field('hourlyCost','Interne Arbeitskosten · € / Std.',state.settings.hourlyCost,'number','min="0" max="1000" step="0.01" required')}${field('overhead','Betriebskosten · € / Std.',state.settings.overhead,'number','min="0" max="1000" step="0.01" required')}${field('kmCost','Fahrzeugkosten · € / km',state.settings.kmCost,'number','min="0" max="20" step="0.01" required')}${field('targetMargin','Zielmarge · % vom Umsatz',state.settings.targetMargin,'number','min="0" max="90" step="0.1" required')}${field('reservePercent','Planungsrücklage · % vom Überschuss',state.settings.reservePercent,'number','min="0" max="100" step="0.1" required','Frei gewählter Sparwert; keine Berechnung deiner Einkommensteuer.')}</div><div class="divider"></div><button type="submit" class="btn">${icon('check')} Einstellungen speichern</button></div></div><div><div class="card"><h2>Daten sichern & übernehmen</h2><p class="sectiondesc" style="margin-top:0">Version-1-Sicherungen können importiert werden. Alte Vollzahlungen werden als Zahlungseinträge übernommen. Ein bisheriger 0-%-Satz wird nicht automatisch als § 19 eingestuft.</p><div class="actions">${btn('Sicherung herunterladen','backup','download')}${btn('Kunden-CSV','export-customers','download','secondary')}</div><div class="divider"></div><label for="restore">Sicherung wiederherstellen · JSON</label><input type="file" id="restore" accept="application/json,.json"><div class="notice warn">Betriebsdaten liegen in diesem Browser. Vor Gerätewechsel oder Browserbereinigung sichern. Import ersetzt den Datenbestand erst nach Bestätigung.</div></div><div class="card"><h2>Zum Start erledigen</h2>${setupChecklist()}</div><div class="card"><h2>Beispielbetrieb</h2><div class="actions">${btn('Beispieldaten laden','demo','','secondary')}${state.demo?btn('Beispieldaten entfernen','reset-demo','','danger'):''}</div></div><div class="card"><h2>Fachlicher Stand</h2><p class="sectiondesc" style="margin-top:0">Deutschland · Euro · § 19 UStG und § 34a UStDV, geprüft am 08.10.2026. Keine Bankanbindung, Cloud-Synchronisation oder amtliche Buchhaltung. Bereits erstellte Rechnungsstände werden beim Bearbeiten eines Auftrags nicht geändert.</p><a href="https://www.gesetze-im-internet.de/ustg_1980/__19.html" target="_blank" rel="noopener">§ 19 UStG</a> · <a href="https://www.gesetze-im-internet.de/ustdv_1980/__34a.html" target="_blank" rel="noopener">§ 34a UStDV</a></div></div></div></form>`}
function setupChecklist(){return [[!!(state.settings.company&&state.settings.owner&&state.settings.address),'Firmenname, Inhaber und vollständige Adresse'],[!!state.settings.taxId,'Steuernummer / passende Identifikationsnummer'],[!!state.settings.iban,'Bankverbindung für Rechnungen'],[!!state.settings.businessStart,'Tätigkeitsbeginn und Umsatzüberwachung'],[state.customers.length>0,'Ersten Kunden angelegt'],[state.jobs.length>0,'Ersten Auftrag kalkuliert']].map(([done,t])=>`<div class="checkitem">${icon(done?'check':'clock')}<span>${t}<div class="fieldhelp">${done?'Erledigt':'Noch offen'}</div></span></div>`).join('')}
function businessPage(){const a=annualWatch(state);return `${pageHeading('Kleinunternehmer. Klarer Überblick.', 'Umsatzgrenzen, offene Schritte und eine einfache Jahresübersicht.',btn('Einstellungen','settings','settings','secondary'))}<div class="metrics">${metric('Umsatzüberwachung · '+a.year,money(a.turnover),'App-Zahlungen + zusätzliche Umsätze','euro',true)}${metric('Vergleichsgrenze',money(a.limit),a.start?'Jahr der Tätigkeitsaufnahme':'Laufendes Jahr bei erfüllter Vorjahresgrenze','leaf')}${metric('Abstand zur Grenze',money(a.remaining),a.exceeded?'Grenze überschritten':'Nur erfasste Umsätze berücksichtigt','clock')}${metric('Planungsrücklage',money(a.reserve),`${number(state.settings.reservePercent)} % · frei gewählter Sparwert`,'wallet')}</div>${state.settings.taxMode!=='small'?'<div class="notice">Der § 19-Modus ist derzeit nicht aktiviert. Die Umsatzüberwachung hilft bei der Prüfung; sie stellt deinen Steuerstatus nicht automatisch um.</div>':''}<div class="grid"><div><div class="card"><h2>Umsatzgrenzen beobachten</h2><div class="smallstat"><span>Überwachungsjahr</span><strong>${a.year}</strong></div><div class="smallstat"><span>Berücksichtigter Vorjahresumsatz</span><strong>${money(a.previous)}</strong></div><div class="smallstat"><span>Berücksichtigter aktueller Umsatz</span><strong>${money(a.turnover)}</strong></div><div class="bar"><span style="width:${a.percent}%"></span></div><div class="notice ${a.exceeded||a.priorExceeded?'warn':''}">${a.priorExceeded?'Vorjahresumsatz über 25.000 €. Die Voraussetzung für die Kleinunternehmerbefreiung im Überwachungsjahr ist nach diesen Angaben nicht erfüllt.':a.exceeded?'Die aktuelle Grenze wurde überschritten. Bereits der überschreitende Umsatz kann steuerpflichtig sein. Steuerstatus und Rechnungen fachlich prüfen.':a.percent>=80?'Du näherst dich der aktuellen Vergleichsgrenze. Prüfe noch nicht erfasste Umsätze und kommende Zahlungen.':'Nach den erfassten Daten liegt der aktuelle Umsatz innerhalb der Vergleichsgrenze.'}</div>${a.nextYearRisk?'<div class="notice warn">Aktueller Jahresumsatz über 25.000 €: Die Kleinunternehmerbefreiung im Folgejahr ist nach dieser Umsatzannahme gefährdet.</div>':''}<p class="fieldhelp">Allgemeine Grenzen: Vorjahr höchstens 25.000 €, laufendes Jahr höchstens 100.000 €. Im Jahr der Tätigkeitsaufnahme wird mit 25.000 € überwacht. Der Gesamtumsatz nach § 19 Abs. 2 hat gesetzliche Ausnahmen; diese App nimmt gewöhnliche Garten- und Reinigungsumsätze an. Keine automatische Statusentscheidung. <a href="https://www.gesetze-im-internet.de/ustg_1980/__19.html" target="_blank" rel="noopener">Gesetz</a> · <a href="https://www.bundesfinanzministerium.de/Content/DE/Downloads/BMF_Schreiben/Steuerarten/Umsatzsteuer/Umsatzsteuer-Anwendungserlass/2025-03-18-sonderregelung-kleinunternehmer.pdf?__blob=publicationFile&v=2" target="_blank" rel="noopener">BMF-Regelung zur Tätigkeitsaufnahme</a></p></div><div class="card"><h2>Einnahmen & Ausgaben · ${a.year}</h2><div class="summaryrow"><span>Erfasste Einnahmen ohne Umsatzsteuer</span><strong>${money(a.financials.netRevenue)}</strong></div><div class="summaryrow"><span>Erfasste Betriebsausgaben · Kostenwert</span><strong>${money(a.financials.deductibleExpenses)}</strong></div><div class="summaryrow total"><span>Erfasster Überschuss</span><strong>${money(a.financials.result)}</strong></div><div class="summaryrow"><span>Planungsrücklage</span><strong>${money(a.reserve)}</strong></div><div class="summaryrow"><span>Überschuss nach Rücklagenplanung</span><strong>${money(a.financials.result-a.reserve)}</strong></div><div class="actions">${btn('Jahres-CSV','annual-csv','download','secondary')}${btn('Jahresbericht / PDF','annual-print','print','secondary')}</div><p class="fieldhelp">Zusätzliche Umsätze dienen nur der Grenzüberwachung und sind in diesem Überschuss nicht enthalten. Geräteabschreibung, private Anteile und weitere EÜR-Anpassungen werden nicht berechnet.</p></div></div><div><div class="card"><h2>Startcheck für deinen Betrieb</h2>${setupChecklist()}</div><div class="card"><h2>Was darfst du ausgeben?</h2><p class="sectiondesc" style="margin-top:0">Die Rücklage ist ein eigener Planungswert. Einkommensteuer, Krankenversicherung und private Lebenshaltung hängen von deiner Situation ab. Umsatzsteuerbefreiung bedeutet keine Einkommensteuerbefreiung.</p><div class="notice">Für Preise zählt deine Arbeitszeit als Kosten. Für die Finanzübersicht zählen erfasste Zahlungen. Eigene Arbeit ist keine gebuchte Betriebsausgabe.</div></div></div></div>`}
function actualSummary(j){const a=actualResult(state,j);return `<div class="summaryrow"><span>${a.invoiced?'Gespeicherter Rechnungsumsatz':'Geplanter Umsatz'}</span><strong>${money(a.revenue)}</strong></div>${a.invoiced?'<p class="fieldhelp">Der Gewinn verwendet den gespeicherten Rechnungsstand. Spätere Preisänderungen am Auftrag ändern die Rechnung nicht.</p>':''}<div class="summaryrow"><span>Geplante Personenstunden</span><strong>${number(a.plan.hours)} Std.</strong></div><div class="summaryrow"><span>${a.hasTime?'Erfasste Personenstunden':'Zeitansatz · noch geschätzt'}</span><strong>${number(a.hours)} Std.</strong></div><div class="summaryrow"><span>${a.hasExpenses?'Erfasste direkte Kosten':'Direkte Kosten · noch geschätzt'}</span><strong>${money(a.expenseTotal)}</strong></div><div class="summaryrow"><span>Geplanter Gewinn</span><strong>${money(a.plan.profit)}</strong></div><div class="summaryrow total"><span>${a.complete?'Gewinn aus erfassten Werten':'Gewinn mit offenen Annahmen'}</span><strong class="${a.profit<0?'negative':''}">${money(a.profit)}</strong></div><p class="fieldhelp">${a.complete?'Vollständigkeit der Zeit und direkten Kosten wurde bestätigt.':'Erfasste Werte werden verwendet; ohne Einträge gelten Planwerte. Bestätige die Vollständigkeit erst nach Prüfung.'} Nachkalkulation vor Steuern. Bei direkten Ausgaben Fahrt, Verbrauch, Entsorgung und Miete vollständig zuordnen; zusätzliche nicht zugeordnete Kosten fehlen.</p><label class="inlinecheck"><input type="checkbox" data-action="actual-complete" data-id="${j.id}" data-field="actualTimeComplete" ${j.actualTimeComplete?'checked':''}>Arbeits-, Fahrt- und Rüstzeiten vollständig</label><label class="inlinecheck" style="margin-top:10px"><input type="checkbox" data-action="actual-complete" data-id="${j.id}" data-field="actualCostsComplete" ${j.actualCostsComplete?'checked':''}>Direkte Kosten vollständig (auch wenn 0 €)</label>`}
async function expenseForm(jobId='',expenseId=''){const old=expenseId?state.expenses.find(ex=>ex.id===expenseId):null;if(expenseId&&!old)return;const data=old||{description:'',date:today(),category:'Material',gross:'',tax:19,jobId,reference:'',receipt:null,taxMode:state.settings.taxMode};showDialog(old?'Ausgabe korrigieren':'Betriebsausgabe erfassen',`<form id="expense-form"><div class="formgrid">${field('description','Beschreibung',data.description,'text','required maxlength="200"')}${field('date','Zahlungsdatum',data.date,'date',`required max="${today()}"`)}${select('category','Kategorie',data.category,['Material','Geräteanschaffung','Gerätemiete','Entsorgung','Fahrzeug','Versicherung','Sonstiges'].map(x=>[x,x]))}${field('gross','Bezahlter Betrag · € brutto',data.gross,'number','min="0.01" max="1000000" step="0.01" required')}${select('tax','Enthaltene Umsatzsteuer des Lieferanten',data.tax,[[0,'0 %'],[7,'7 %'],[19,'19 %']])}${select('taxMode','Kostenbehandlung',data.taxMode,[['small','Kleinunternehmer · Kosten brutto'],['standard','Regelbesteuerung · vereinfachter Nettowert'],['exempt','Andere Steuerbefreiung · Kosten brutto']])}${select('jobId','Zuordnung zum Auftrag',data.jobId,[['','Allgemeine Betriebsausgabe'],...state.jobs.map(j=>[j.id,j.title])])}${field('reference','Belegnummer / Lieferant',data.reference,'text','maxlength="160"')}<div><label for="receipt-file">${data.receipt?'Belegfoto ersetzen · optional':'Belegfoto · optional'}</label><input id="receipt-file" type="file" accept="image/jpeg,image/png,image/webp">${data.receipt?'<p class="fieldhelp">Das gespeicherte Belegfoto bleibt erhalten, wenn du kein neues auswählst.</p>':''}</div></div><div class="notice">Eine Korrektur aktualisiert Kosten und Nachkalkulation. Geräteanschaffungen zählen hier vollständig; steuerliche Abschreibungen sind nicht enthalten.</div><button class="btn" type="submit">${icon('check')} Ausgabe speichern</button>${old?btn('Falschen Eintrag entfernen','delete-expense','trash','danger',`data-id="${e(old.id)}"`):''}</form>`);const form=document.querySelector('#expense-form');form.onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),file=document.querySelector('#receipt-file').files?.[0];try{if(!validISODate(f.date)||f.date>today())throw Error('Bitte ein gültiges Datum einer bereits erfolgten Zahlung erfassen.');if(!f.description.trim()||!Number.isFinite(+f.gross)||+f.gross<=0||+f.gross>1000000||![0,7,19].includes(+f.tax)||!['small','standard','exempt'].includes(f.taxMode)||f.jobId&&!state.jobs.some(j=>j.id===f.jobId))throw Error('Beschreibung, Betrag, Steuerbehandlung und Zuordnung prüfen.');const receipt=file?await readImage(file):data.receipt;const entry={id:old?.id||uid(),description:f.description.trim(),date:f.date,category:f.category,gross:roundMoney(+f.gross),tax:+f.tax,taxMode:f.taxMode,jobId:f.jobId,reference:f.reference,receipt};if(old)state.expenses[state.expenses.findIndex(ex=>ex.id===old.id)]=entry;else state.expenses.push(entry);for(const id of [old?.jobId,f.jobId]){const j=state.jobs.find(j=>j.id===id);if(j)j.actualCostsComplete=false}if(await commit()){dialog.close();toast(old?'Ausgabe korrigiert. Nachkalkulation aktualisiert.':'Ausgabe gespeichert und Kosten zugeordnet.')}}catch(err){toast(err.message)}};guardForm(form)}
function timerMinutes(){return state.activeTimer?Math.max(0,(Date.now()-state.activeTimer.started)/60000):0}
function timerText(){const sec=Math.floor(timerMinutes()*60);return `${String(Math.floor(sec/3600)).padStart(2,'0')}:${String(Math.floor(sec/60)%60).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`}
function timePage(){const jobs=state.jobs.filter(j=>j.status!=='Storniert'),entries=state.timeEntries.filter(t=>t.date.startsWith(month));return `${pageHeading('Deine Zeit ist dein Geld.', 'Arbeits-, Fahrt- und Rüstzeiten erfassen und Aufträge nachkalkulieren.',btn('Zeit manuell erfassen','manual-time','plus'))}<div class="grid"><div><div class="card"><h2>Stoppuhr für den Einsatz</h2>${state.activeTimer?`<span class="pill">${e(state.jobs.find(j=>j.id===state.activeTimer.jobId)?.title||'Auftrag')}</span><p>${e(state.activeTimer.kind)} · Start ${new Date(state.activeTimer.started).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}</p><div class="timerdisplay" id="timer-clock">${timerText()}</div>${btn('Stoppen & Zeit speichern','stop-timer','check')}<p class="fieldhelp">Die Startzeit bleibt beim Schließen der App gespeichert. Beim Stoppen wird die gesamte vergangene Zeit übernommen; vergessene Stoppuhren vor dem Speichern prüfen.</p>`:`<form id="timer-form"><div class="formgrid">${select('timer-job','Auftrag',window.selectedTimeJob||jobs[0]?.id||'',[['','Bitte auswählen'],...jobs.map(j=>[j.id,j.title])],'required')}${select('timer-kind','Zeitart','Arbeit',['Arbeit','Fahrt','Rüsten'].map(s=>[s,s]))}</div><div class="divider"></div><button type="submit" class="btn">${icon('clock')} Stoppuhr starten</button></form>`}</div><div class="card"><div class="cardhead"><h2>Zeitprotokoll</h2><input type="month" id="time-month" value="${month}" aria-label="Zeiterfassungsmonat" style="width:170px"></div>${entries.length?`<div class="tablewrap"><table><thead><tr><th>DATUM</th><th>AUFTRAG</th><th>ART</th><th>DAUER</th><th>NOTIZ</th><th></th></tr></thead><tbody>${entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${dateText(t.date)}</td><td>${e(state.jobs.find(j=>j.id===t.jobId)?.title||'Auftrag')}</td><td>${e(t.kind)}</td><td>${number(t.minutes)} Min.</td><td>${e(t.note||'')}</td><td>${btn('Korrigieren','edit-time','','secondary small',`data-id="${t.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('Noch keine Zeit im gewählten Monat erfasst.','clock')}<div class="summaryrow"><span>Erfasste Personenstunden</span><strong>${number(entries.reduce((a,t)=>a+t.minutes,0)/60)} Std.</strong></div>${btn('Zeiten als CSV','time-csv','download','secondary small')}</div></div><div><div class="card"><h2>Nachkalkulation je Auftrag</h2>${jobs.length?jobs.map(j=>{const a=actualResult(state,j);return `<div class="resultitem"><div class="cardhead"><h3>${e(j.title)}</h3><button class="linkbtn" data-action="detail" data-id="${j.id}">Öffnen →</button></div><div class="summaryrow"><span>${a.hasTime?'Erfasste Zeit':'Planzeit'}</span><strong>${number(a.hours)} Std.</strong></div><div class="summaryrow"><span>${a.complete?'Gewinn · erfasste Werte':'Gewinn · teilweise geschätzt'}</span><strong class="${a.profit<0?'negative':''}">${money(a.profit)}</strong></div><div class="actions">${btn('Zeit','manual-time','','light small',`data-id="${j.id}"`)}${btn('Ausgabe zuordnen','job-expense','','secondary small',`data-id="${j.id}"`)}</div></div>`}).join(''):empty('Erstelle einen Auftrag, um Zeit und Kosten zuordnen zu können.','jobs')}</div></div></div>`}
function bindV2(){if(view==='time'){document.querySelector('#time-month').onchange=ev=>{month=ev.target.value||today().slice(0,7);render()};if(!state.activeTimer)document.querySelector('#timer-form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),jobId=f.get('timer-job');if(!state.jobs.some(j=>j.id===jobId)){toast('Bitte einen Auftrag auswählen.');return}if(state.activeTimer){toast('Es läuft bereits eine Stoppuhr.');return}state.activeTimer={jobId,kind:f.get('timer-kind'),started:Date.now()};if(await commit())toast('Stoppuhr gestartet.')};}if(view==='settings'){document.querySelector('#taxMode').onchange=ev=>{if(ev.target.value!=='standard')document.querySelector('#tax').value='0';else if(ev.target.value==='standard')document.querySelector('#tax').value='19'}}}
function manualTime(jobId='',timer=false,entryId=''){const original=entryId?state.timeEntries.find(t=>t.id===entryId):null;const jobs=state.jobs.filter(j=>j.status!=='Storniert'||j.id===jobId||j.id===original?.jobId||j.id===state.activeTimer?.jobId);if(!jobs.length){toast('Bitte zuerst einen Auftrag anlegen.');return}const active=timer?state.activeTimer:null;showDialog(timer?'Stoppuhr prüfen & speichern':'Zeit manuell erfassen',`<form id="manual-time-form"><div class="formgrid">${select('jobId','Auftrag',original?.jobId||active?.jobId||jobId||jobs[0].id,jobs.map(j=>[j.id,j.title]),'required')}${select('kind','Zeitart',original?.kind||active?.kind||'Arbeit',['Arbeit','Fahrt','Rüsten'].map(s=>[s,s]))}${field('date','Datum',original?.date||today(),'date',`required max="${today()}"`)}${field('minutes','Personenminuten',original?.minutes??(timer?Math.max(.01,roundMoney(timerMinutes())):60),'number','min="0.01" max="100000" step="0.01" required')}${field('note','Tätigkeit / Notiz',original?.note||'','text','maxlength="300"')}</div><div class="notice">Eine Person × 60 Minuten = 60 Personenminuten. Zwei Personen × 60 Minuten = 120 Personenminuten. Fahrt und Rüsten separat erfassen. ${timer?'Prüfe insbesondere vergessene Pausen; korrigiere die Dauer bei Bedarf.':''}</div><button type="submit" class="btn">${icon('check')} Zeit speichern</button></form>`);document.querySelector('#manual-time-form').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));if(!validISODate(f.date)||f.date>today()||!Number.isFinite(+f.minutes)||+f.minutes<=0||+f.minutes>100000||!state.jobs.some(j=>j.id===f.jobId)){toast('Datum oder Auftrag ungültig.');return}const entry={...f,id:original?.id||uid(),minutes:roundMoney(+f.minutes),source:timer?'Stoppuhr':'Manuell'};if(original){state.timeEntries[state.timeEntries.findIndex(t=>t.id===original.id)]=entry;state.jobs.find(j=>j.id===original.jobId).actualTimeComplete=false}else state.timeEntries.push(entry);state.jobs.find(j=>j.id===f.jobId).actualTimeComplete=false;if(timer)state.activeTimer=null;if(await commit()){dialog.close();view='time';render();toast('Zeit gespeichert. Nachkalkulation aktualisiert.')}};guardForm(document.querySelector('#manual-time-form'))}
function followUpDialog(id){const j=state.jobs.find(j=>j.id===id);if(!j)return;const d=new Date((j.date||today())+'T12:00:00');d.setDate(d.getDate()+7);const next=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');showDialog('Folgeauftrag vorbereiten',`<p><strong>${e(j.title)}</strong> · ${e(jobCustomer(j))}</p><form id="follow-form"><div class="formgrid">${field('date','Erster Folgetermin',next,'date','required')}${select('interval','Wiederholung',7,[[7,'Wöchentlich'],[14,'Alle zwei Wochen'],[28,'Alle vier Wochen'],[0,'Ein einzelner Folgeauftrag']])}${field('count','Anzahl Termine',1,'number','min="1" max="12" step="1" required')}</div><div class="notice">Leistungen, Preise und Kunde werden kopiert. Neue Fotos, Checklisten und Zeiten beginnen leer. Termine werden vor dem Anlegen auf Überschneidungen und Radikalschnitt-Zeiträume geprüft.</div><button type="submit" class="btn">${icon('calendar')} Termine prüfen & anlegen</button></form>`);document.querySelector('#follow-form').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),count=+f.count,interval=+f.interval;if(!validISODate(f.date)||![0,7,14,28].includes(interval)||!Number.isInteger(count)||count<1||count>12||(!interval&&count!==1)){toast('Ohne Wiederholung bitte genau einen Termin wählen.');return}const copies=[];for(let i=0;i<count;i++){const date=new Date(f.date+'T12:00:00');date.setDate(date.getDate()+interval*i);const key=date.getFullYear()+'-'+String(date.getMonth()+1).padStart(2,'0')+'-'+String(date.getDate()).padStart(2,'0');const copy=copyFollowUp(j,key);copy.costSettings={hourlyCost:state.settings.hourlyCost,overhead:state.settings.overhead,kmCost:state.settings.kmCost,targetMargin:state.settings.targetMargin,taxMode:copy.taxMode,tax:copy.tax};if(radicalBlocked(copy)){toast('Folgetermin '+dateText(key)+': Radikalschnitt im gesperrten Zeitraum. Keine Termine angelegt.');return}if(conflicts(copy,[...state.jobs,...copies]).length){toast('Folgetermin '+dateText(key)+' überschneidet sich. Bitte Zeit oder Ausgangsauftrag anpassen. Keine Termine angelegt.');return}copies.push(copy)}state.jobs.push(...copies);if(await commit()){dialog.close();view='calendar';month=f.date.slice(0,7);render();toast(copies.length+' Folgeauftrag/-aufträge angelegt.')}};guardForm(document.querySelector('#follow-form'))}
function exportFinance(period=month){const f=financials(state,period);const rows=[['Typ','Nummer','Datum','Kunde / Beschreibung','Kategorie / Zahlungsart','Netto EUR','USt EUR','Brutto EUR','Kostenwert EUR','Auftrag','Belegnummer','Restbetrag EUR']];for(const i of f.invoices)rows.push(['Rechnungsstand',i.number,i.issued,i.customer.name,'Dienstleistung',i.calc.net.toFixed(2),i.calc.tax.toFixed(2),i.calc.gross.toFixed(2),'',i.job.title,'',invoiceBalance(i).open.toFixed(2)]);for(const p of f.payments)rows.push(['Zahlungseingang',p.number,p.date,p.customer.name,p.method||'Überweisung',p.calc.net.toFixed(2),p.calc.tax.toFixed(2),p.calc.gross.toFixed(2),'','','','']);for(const ex of f.expenses){const net=roundMoney(ex.gross/(1+ex.tax/100));rows.push(['Ausgabe',ex.id,ex.date,ex.description,ex.category,net.toFixed(2),roundMoney(ex.gross-net).toFixed(2),ex.gross.toFixed(2),expenseCost(ex,state.settings).toFixed(2),state.jobs.find(j=>j.id===ex.jobId)?.title||'',ex.reference||'',''])}download('werkpilot-finanzen-'+period+'.csv',csv(rows),'text/csv;charset=utf-8');toast('Export bereit. Einnahmen nur aus Zahlungseingängen summieren, nicht zusätzlich aus Rechnungsständen. Für Kosten die Spalte Kostenwert nutzen.')}
function financePrint(period=month){const f=financials(state,period);printHTML(`<article class="invoicepage"><h1>Einnahmen-Ausgaben-Übersicht · ${period}</h1><p>${e(state.settings.company)} · erstellt am ${dateText(today())}</p><p>Vereinfachte betriebliche Übersicht. Keine amtliche EÜR; Abschreibungen und steuerliche Anpassungen fehlen. ${state.demo?'Beispieldaten.':''}</p><table><tbody><tr><td>Bezahlte Einnahmen ohne Umsatzsteuer</td><td>${money(f.netRevenue)}</td></tr><tr><td>Erfasste Kostenwerte</td><td>${money(f.deductibleExpenses)}</td></tr><tr><td>Erfasster Überschuss</td><td>${money(f.result)}</td></tr><tr><td>Zahlungssaldo brutto</td><td>${money(f.cashBalance)}</td></tr><tr><td>Offene Restbeträge, alle Zeiträume</td><td>${money(f.open)}</td></tr></tbody></table><h2>Zahlungseingänge</h2><table><tbody>${f.payments.map(p=>`<tr><td>${dateText(p.date)}</td><td>${e(p.number)}</td><td>${e(p.customer.name)}</td><td>${money(p.calc.gross)}</td></tr>`).join('')}</tbody></table><h2>Ausgaben</h2><table><tbody>${f.expenses.map(ex=>`<tr><td>${dateText(ex.date)}</td><td>${e(ex.description)}</td><td>${e(ex.reference||'')}</td><td>${money(expenseCost(ex,state.settings))}</td></tr>`).join('')}</tbody></table></article>`)}
function validateV2(s){return validateBackup(s)}
let financeFilter='month';
async function handleV2(action,target){const id=target.dataset.id;switch(action){case'remove-payment':{const i=state.invoices.find(i=>i.id===id);if(confirm('Diesen falsch erfassten Zahlungseintrag entfernen? Dies ist eine Datenkorrektur, keine Rückerstattung an den Kunden.')){removePayment(i,target.dataset.paymentId);if(await commit())paymentDialog(id)}return true;}case'actual-complete':{const j=state.jobs.find(j=>j.id===id);if(j&&['actualTimeComplete','actualCostsComplete'].includes(target.dataset.field)){j[target.dataset.field]=target.checked;await commit();detail(id)}return true;}case'open-time':view='time';render();return true;case'open-business':view='business';render();return true;case'finance-open':financeFilter='open';render();return true;case'finance-month':financeFilter='month';render();return true;case'pay-invoice':paymentDialog(id);return true;case'job-time':dialog.close();window.selectedTimeJob=id;view='time';render();return true;case'edit-time':{const t=state.timeEntries.find(t=>t.id===id);if(t)manualTime(t.jobId,false,t.id);return true;}case'manual-time':manualTime(id||window.selectedTimeJob||'');return true;case'stop-timer':if(state.activeTimer)manualTime(state.activeTimer.jobId,true);return true;case'job-expense':await expenseForm(id);return true;case'follow-up':followUpDialog(id);return true;case'time-csv':download('werkpilot-zeiten-'+month+'.csv',csv([['Datum','Auftrag','Zeitart','Personenminuten','Notiz'],...state.timeEntries.filter(t=>t.date.startsWith(month)).map(t=>[t.date,state.jobs.find(j=>j.id===t.jobId)?.title,t.kind,t.minutes,t.note])]),'text/csv;charset=utf-8');return true;case'annual-csv':exportFinance(String(state.settings.watchYear));return true;case'annual-print':financePrint(String(state.settings.watchYear));return true;case'finance-print':financePrint();return true;case'reminder':{const i=state.invoices.find(i=>i.id===id),b=invoiceBalance(i);printHTML(`<article class="invoicepage"><h1>Zahlungserinnerung</h1><p>${e(i.company.company)}<br>${e(i.company.address)}</p><hr><p>${e(i.customer.name)}<br>${e(i.customer.address)}</p><p>Datum: ${dateText(today())}</p><p>Zu Rechnung ${e(i.number)} vom ${dateText(i.issued)} (${money(i.calc.gross)}) sind ${money(b.paid)} als bezahlt erfasst. Der offene Restbetrag beträgt <strong>${money(b.open)}</strong>. Das ursprüngliche Zahlungsziel war ${dateText(i.due)}.</p><p>Bitte prüfe die Zahlung. Sollte sie bereits erfolgt sein, betrachte diese Erinnerung als gegenstandslos.</p><p>IBAN: ${e(i.company.iban||'Bitte ergänzen')}<br>Verwendungszweck: ${e(i.number)}</p></article>`);return true}}return false}

let assistantContext={},lastSpeechReply='',lastDetailedReply='',lastShortReply='';
function answer(text){if(/\b(?:neuer?|andere[rsn]?)\s+(?:auftrag|kalkulation)\b/i.test(normalizeSpeech(text))){assistantContext={};window.assistantDraft=null}const parsed=parseAssistantRequest(text,assistantContext);const siteUpdate=parseSiteDetails(text);if(assistantContext.awaitingSite&&Object.keys(siteUpdate).length&&window.assistantDraft&&!parsed.lines.some(line=>line.service==='greenhaul')){parsed.intent=(parsed.costIssues||[]).length?'clarify-costs':'calculation';parsed.costOnly=true;parsed.lines=structuredClone(assistantContext.lines)}const names=ids=>ids.map(id=>services.find(s=>s.id===id)?.name).filter(Boolean).join(', ');lastSpeechReply='';if(!['calculation','takeover','decline'].includes(parsed.intent))assistantContext.pendingTakeover=false;const reply=(detailed,spoken='')=>{lastSpeechReply=briefSpokenReply(spoken||detailed);if(parsed.intent!=='repeat'&&parsed.intent!=='details'){lastDetailedReply=detailed;lastShortReply=lastSpeechReply}return detailed};switch(parsed.intent){case'stop':stopVoice();return reply('Sprachausgabe gestoppt.','');case'repeat':lastSpeechReply=lastShortReply||voiceController.lastSpoken||'Stelle mir zuerst eine Frage.';return lastDetailedReply||lastSpeechReply;case'details':lastSpeechReply=lastDetailedReply?briefSpokenReply(lastDetailedReply):'Stelle mir zuerst eine konkrete Frage.';return lastDetailedReply||lastSpeechReply;case'greeting':return reply('Hallo! Nenne mir Leistung und Menge. Zum Beispiel: „Zweihundert Quadratmeter Rasen kalkulieren.“','Hallo! Was möchtest du kalkulieren?');case'takeover':if(window.assistantDraft){draft=structuredClone(window.assistantDraft);view='calc';return reply('Die Kalkulation ist vorbereitet. Ergänze Kunde, Termin und tatsächliche Bedingungen. Erst mit „Auftrag speichern“ wird sie gespeichert.','Die Kalkulation ist geöffnet. Bitte Kunde und Termin ergänzen.')}return reply('Es gibt noch keine vorbereitete Kalkulation. Nenne zuerst Leistung und Menge.');case'decline':assistantContext.pendingTakeover=false;return reply('Okay. Die Kalkulation bleibt ein Entwurf; nichts wurde gespeichert.','Okay. Nichts wurde gespeichert.');case'clarify-service':window.assistantDraft=null;if(parsed.clarification)return reply(parsed.clarification);return reply(parsed.services.length>1?`Welche Leistung meinst du: ${names(parsed.services)}? Bitte Leistung und Menge zusammen nennen.`:'Welche konkrete Leistung meinst du? Zum Beispiel Wand streichen, Fliesen verlegen, Rasen mähen oder Fenster reinigen. Nenne Leistung und Menge; bei allgemeinen Elektro- oder Sanitärarbeiten brauche ich den genauen Umfang.');case'clarify-multiple':window.assistantDraft=null;return reply('Ich habe mehrere Mengen erkannt. Bitte nenne jede Leistung mit genau einer Menge und Einheit.','Bitte jede Leistung mit einer Menge und Einheit nennen.');case'clarify-unit':window.assistantDraft=null;assistantContext.pendingService=parsed.service;return reply(`Für ${names([parsed.service])} brauche ich die Menge in ${parsed.unit}. Erkannt habe ich ${parsed.received}. Bitte die passende Einheit nennen.`, `Für ${names([parsed.service])} brauche ich ${unitSpoken(parsed.unit)}. Bitte die Menge bestätigen.`);case'clarify-quantity':if(parsed.lines.length){window.assistantDraft=prepareAssistantDraft(newDraft(),parsed,state.settings);window.assistantDraft.siteDetails=parseSiteDetails(text);assistantContext={lines:structuredClone(parsed.lines),awaitingCosts:true,awaitingSite:parsed.lines.some(l=>l.service==='felling'),pendingService:parsed.service,pendingTakeover:false};}else{window.assistantDraft=null;assistantContext.pendingService=parsed.service;}return reply(`${parsed.lines.length?'Erfasst: '+parsed.lines.map(l=>number(l.qty)+' '+names([l.service])).join(', ')+'.\n\n':''}Wie viel ${names([parsed.service])}? Bitte die Menge in ${parsed.unit} nennen.`, `Welche Menge in ${unitSpoken(parsed.unit)} soll ich berechnen?`);case'clarify-costs':{if(parsed.lines.length){const base=prepareAssistantDraft(newDraft(),parsed,state.settings,window.assistantDraft);base.siteDetails=mergeSiteDetails(window.assistantDraft?.siteDetails||{},parseSiteDetails(text));window.assistantDraft=base;assistantContext={...assistantContext,lines:structuredClone(parsed.lines),awaitingCosts:true,siteDetails:base.siteDetails,pendingTakeover:false};}const question=(parsed.costIssues||[]).map(issue=>issue.message).join('\n')||'Bitte Maschinenmiete und Materialkosten getrennt in Euro angeben.';return reply(`Erfasst: ${names(parsed.lines.map(l=>l.service))||'dein bisheriger Auftrag'}.\n\n${question}\n\nZum Beispiel: „30 Euro Maschinenmiete und 20 Euro Material“. Noch kein Preis für fehlende Angaben erfunden.`,question)}
case'clarify-tree-work':return reply('Meinst du Baumpflege / Rückschnitt oder eine Baumfällung? Bitte Höhe, Stammdurchmesser und Zugang nennen. Fällung und Rückschnitt werden getrennt kalkuliert.','Meinst du den Rückschnitt oder eine Baumfällung?');
case'calculation':{let lines=parsed.lines.map(l=>({service:l.service,qty:l.qty,rate:serviceRate(l.service)}));const continuing=!!(window.assistantDraft&&(parsed.correction||parsed.costOnly||assistantContext.awaitingCosts||(assistantContext.awaitingSite&&lines.every(l=>['felling','greenhaul'].includes(l.service)))||/\b(?:dazu|zusaetzlich)\b/.test(parsed.text)));if(continuing&&assistantContext.lines?.length){const prior=structuredClone(assistantContext.lines).filter(line=>!(parsed.excludedServices||[]).includes(line.service));for(const l of lines){const index=prior.findIndex(p=>p.service===l.service);if(index>=0)prior[index]={...l,qty:/\b(?:dazu|zusaetzlich)\b/.test(parsed.text)?prior[index].qty+l.qty:l.qty};else prior.push(l)}lines=prior}let j=prepareAssistantDraft(newDraft(),{...parsed,lines:[],followUpCosts:continuing},state.settings,continuing?window.assistantDraft:null);j.lines=lines;j.title=lines.map(l=>services.find(s=>s.id===l.service).name).join(' & ');j.routeFrom||=state.settings.homeBase;j.siteDetails=mergeSiteDetails(continuing?window.assistantDraft?.siteDetails||{}:{},parseSiteDetails(text));if(j.siteDetails.greenVolume===undefined&&j.lines.some(line=>line.service==='greenhaul')&&!(j.siteDetails.uncertain||[]).includes('greenVolume'))j.siteDetails.greenVolume=j.lines.find(line=>line.service==='greenhaul').qty;const volume=(j.siteDetails.uncertain||[]).includes('greenVolume')?0:j.siteDetails.greenVolume??lines.find(l=>l.service==='greenhaul')?.qty;let disposalNote='';if(volume>0&&parsed.costs?.disposal===undefined&&(lines.some(l=>['felling','greenhaul','radical','hedge'].includes(l.service)))){const fee=disposalEstimate(volume,{taxMode:j.taxMode});j.disposal=fee.cost;disposalNote=`Grüngutgebühr Kronach: ${money(fee.cost)} (9 € / m³ + 5 € / Rechnung, ${j.taxMode==='standard'?'ohne':'mit angenommener 19 %'} Umsatzsteuer; amtliches Merkblatt Stand Januar 2025, vor Anlieferung bestätigen). Baumstämme und Äste über 10 cm separat entsorgen.`;}const priced=priceForTargetMargin(j,state.settings);j=priced.job;const c=priced.calc,small=j.taxMode==='small',assessment=assessSite(j,j.siteDetails);assistantContext={lines:structuredClone(j.lines),pendingTakeover:true,awaitingCosts:false,awaitingSite:!assessment.readyForBindingQuote,siteDetails:j.siteDetails};window.assistantDraft=j;const quantities=j.lines.map(l=>`${number(l.qty)} ${services.find(s=>s.id===l.service).unit} ${names([l.service])}`).join(' + '),required=requiredEquipment(j),missing=required.filter(eq=>!state.owned.includes(eq.id));return reply(`Kalkulationsentwurf: ${quantities}\n\n• Leistungen: ${money(c.serviceNet)}\n• Anfahrt: ${number(j.travelHours*60)} Minuten + ${number(j.km)} km → ${money(j.travelPrice)}\n• Maschinenmiete: ${money(j.rental)}\n• Zusätzliches Material: ${money(j.material)}\n• Entsorgung: ${money(j.disposal)}\n• Gesamt: ${money(c.net)} ${small?'ohne Umsatzsteuer':`netto / ${money(c.gross)} brutto`}\n• Zeitbedarf inkl. Fahrt/Rüsten: ${number(c.hours)} Personenstunden\n• Kalkulierte Kosten: ${money(c.costs)}\n• Geschätzter Gewinn vor Steuern: ${money(c.profit)}\n• Marge: ${number(c.margin)} %\n\n${priced.adjusted?'Die Leistungspreise wurden auf deine Zielmarge angehoben.':'Es gelten deine eigenen hinterlegten Leistungspreise.'}\n${disposalNote}\n${j.routeTo?'Route: '+j.routeFrom+' → '+j.routeTo+'. Entfernung und Fahrtzeit aus deinen Angaben, nicht automatisch gemessen.':'Anfahrt: Nicht angegebene Kilometer/Fahrtzeit sind noch nicht enthalten.'}\n\nAusstattung: ${required.map(eq=>eq.name).join(', ')}.\n${missing.length?'Mietkosten für fehlende Maschinen bitte ergänzen. Kauf-Richtwerte sind keine Mietpreise.':''}\n${j.lines.map(l=>services.find(s=>s.id===l.service).hint).join('\n')}\n${assessment.missing.length?'Für ein belastbares Angebot noch klären: '+assessment.missing.join('; ')+'.':''}\n\n„Übernehmen“ öffnet den Entwurf. Kunde, Termin und Aufmaß bestätigen, dann speichern und ein nummeriertes Angebot erstellen.`, `${assessment.readyForBindingQuote?'Gesamt':'Vorläufig insgesamt'} ${spokenMoney(c.gross)}. Fahrt ${spokenMoney(j.travelPrice)}.${j.rental?' Maschinen '+spokenMoney(j.rental)+'.':''}${j.material?' Material '+spokenMoney(j.material)+'.':''}${j.disposal?' Entsorgung '+spokenMoney(j.disposal)+'.':''} Gewinn ${spokenMoney(c.profit)} vor Steuern.${assessment.missing.length?' Noch klären: '+assessment.missing[0]+'.':' Entwurf öffnen?'}`)}
case'equipment':{const ids=parsed.services.length?parsed.services:assistantContext.pendingService?[assistantContext.pendingService]:[];if(!ids.length)return reply('Für welche Leistung brauchst du Geräte? Zum Beispiel Heckenpflege oder Fensterreinigung.');const eq=requiredEquipment({lines:ids.map(service=>({service}))}),missing=eq.filter(eq=>!state.owned.includes(eq.id));return reply(`Für ${names(ids)} brauchst du:\n${eq.map(eq=>`• ${eq.name} – ${state.owned.includes(eq.id)?'im Bestand':'besorgen oder mieten'}`).join('\n')}\n\nFehlende Ausstattung: ca. ${money(missing.reduce((s,eq)=>s+eq.price,0))} als unverbindlicher Kauf-Richtwert.`, `Du brauchst ${eq.slice(0,4).map(eq=>eq.name).join(', ')}.${eq.length>4?' Weitere Ausstattung steht im Chat.':''} ${missing.length} Positionen fehlen im Bestand.`)}case'appointments':{const reference=today(),d=new Date(reference+'T12:00:00');d.setDate(d.getDate()+1);const tomorrow=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;const list=state.jobs.filter(j=>!['Storniert','Erledigt','Angebot'].includes(j.status)&&(parsed.day==='today'?j.date===reference:parsed.day==='tomorrow'?j.date===tomorrow:j.date>=reference)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!list.length)return reply('Für diesen Zeitraum sind keine bestätigten Einsätze eingetragen.');return reply('Deine Einsätze:\n'+list.slice(0,5).map(j=>`${dateText(j.date)} · ${j.time}: ${j.title} bei ${jobCustomer(j)}`).join('\n'),`Dein ${parsed.day==='next'?'nächster Einsatz':'erster Einsatz '+(parsed.day==='today'?'heute':'morgen')} ist ${list[0].title}, um ${list[0].time} Uhr. ${list.length>1?`${list.length} Einsätze sind eingetragen.`:''}`)}case'finance':{const f=financials(state,today().slice(0,7));return reply(legacyAnswer('Umsatz'),`Diesen Monat sind ${spokenMoney(f.netRevenue)} ohne Umsatzsteuer eingegangen. Insgesamt sind noch ${spokenMoney(f.open)} offen.`)}case'profit':return reply(legacyAnswer('Wie erhöhe ich meinen Gewinn?'),`Deine Zielmarge ist ${number(state.settings.targetMargin)} Prozent. Erfasse eigene Arbeitszeit, Fahrt und direkte Kosten. Den empfohlenen Preis findest du in der Kalkulation.`);case'procedure':{const s=services.find(s=>s.id===parsed.service);return reply(`${s.name}\n\n${s.tasks.map(t=>'• '+t).join('\n')}\n\n${s.hint}`,s.id==='radical'?'Prüfe zuerst Zeitraum und Artenschutz. Radikale Heckenschnitte sind grundsätzlich von März bis September gesperrt. Details stehen im Chat.':`${s.tasks.slice(0,2).join('. ')}. Den vollständigen Ablauf findest du im Chat.`)}default:return reply('Das habe ich nicht eindeutig verstanden. Nenne eine Leistung und eine Menge, zum Beispiel „Hundert Quadratmeter Rasen mähen“, oder frage nach Geräten, Terminen oder Umsatz.','Das habe ich nicht eindeutig verstanden. Welche Leistung und welche Menge meinst du?')}}
function unitSpoken(unit){return {'m²':'Quadratmetern',lfm:'laufenden Metern','Std.':'Stunden',Etage:'Etagen',Stück:'Stück', 'm³':'Kubikmetern'}[unit]||unit}
async function ask(text,{voiceInput=false}={}){const clean=String(text||'').trim();if(!clean)return;releaseRecognition();voiceController.pendingSpeech='';clearTimeout(voiceController.pendingTimer);voiceController.utterance=null;voiceController.speaking=false;if('speechSynthesis'in window)window.speechSynthesis.cancel();if(!voiceInput)voiceController.continueAllowed=false;voiceController.manualPending=false;const before=view;chatMessages.push({role:'user',text:clean});const result=answer(clean);chatMessages.push({role:'assistant',text:result});if(before!==view)render();else if(view==='assistant'){const chat=document.querySelector('#chat');if(chat){chat.innerHTML=chatMessages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'DU':'WERKPILOT'}</small>${e(m.text)}</div>`).join('');chat.scrollTop=chat.scrollHeight}const input=document.querySelector('#chat-text');if(input)input.value='';}else render();if(parseAssistantRequest(clean).intent==='stop'){setVoiceStatus('Bereit.');return}if(voiceInput||state.settings.speech)speak(state.settings.shortVoice===false?result:lastSpeechReply||briefSpokenReply(result));else setVoiceStatus('Antwort bereit.');}

const voiceController={recognizer:null,finalTimer:null,generation:0,listening:false,starting:false,speaking:false,status:'Bereit. Mikrofon antippen und sprechen.',heard:'',lastSpoken:'',manualPending:false,continueAllowed:false,pendingSpeech:'',pendingTimer:null,utterance:null};
function availableVoices(){return 'speechSynthesis'in window?window.speechSynthesis.getVoices():[]}
function setVoiceStatus(text){voiceController.status=text;const el=document.querySelector('#voice-status');if(el)el.textContent=text;const heard=document.querySelector('#voice-heard');if(heard)heard.textContent=voiceController.heard?'Erkannt: '+voiceController.heard:'';const button=document.querySelector('[data-action="voice"]');if(button){const active=voiceController.listening||voiceController.starting;button.setAttribute('aria-pressed',String(active));button.setAttribute('aria-label',active?'Mikrofon stoppen':'Spracheingabe starten');button.classList.toggle('listening',active)}const stop=document.querySelector('[data-action="voice-stop"]');if(stop)stop.disabled=!(voiceController.listening||voiceController.starting||voiceController.speaking||voiceController.pendingSpeech)}
function releaseRecognition(){clearTimeout(voiceController.finalTimer);voiceController.generation++;const r=voiceController.recognizer;voiceController.recognizer=null;voiceController.listening=false;voiceController.starting=false;if(r)try{r.abort()}catch{}}
function stopVoice(){releaseRecognition();voiceController.continueAllowed=false;voiceController.pendingSpeech='';clearTimeout(voiceController.pendingTimer);if('speechSynthesis'in window)window.speechSynthesis.cancel();voiceController.utterance=null;voiceController.speaking=false;voiceController.manualPending=false;setVoiceStatus('Gestoppt. Mikrofon antippen für eine neue Frage.')}
function refreshVoiceControls(){const voices=availableVoices(),chosen=chooseGermanVoice(voices,state.settings.voiceURI),selectEl=document.querySelector('#voice-choice');if(selectEl){const german=voices.filter(v=>/^de(?:[-_]|$)/i.test(v.lang));selectEl.innerHTML=`<option value="">Automatisch${chosen?' · '+e(chosen.name):' · Stimmen werden geladen'}</option>`+german.map(v=>`<option value="${e(v.voiceURI)}">${e(v.name)}${isMaleVoice(v)?' · männlich erkannt':''}${v.localService?' · lokal':''}</option>`).join('');selectEl.value=german.some(v=>v.voiceURI===state.settings.voiceURI)?state.settings.voiceURI:'';}const hint=document.querySelector('#voice-hint');if(hint)hint.textContent=!voices.length?'Stimmenliste wird vom Gerät bereitgestellt.':!chosen?'Keine deutsche Stimme verfügbar. In den Spracheinstellungen des Geräts eine deutsche Stimme installieren.':isMaleVoice(chosen)?`Ausgewählt: ${chosen.name}. ${chosen.localService?'Lokale Stimme – keine zusätzliche Netzwerkanfrage für diese Ausgabe.':'Diese Stimme kann den Sprachdienst des Geräts verwenden.'}`:`Ausgewählt: ${chosen.name}. Keine bekannte deutsche Männerstimme gefunden. Stimmen in den Spracheinstellungen des Geräts ergänzen oder hier probehören.`;if(voiceController.pendingSpeech&&chosen){const text=voiceController.pendingSpeech;voiceController.pendingSpeech='';clearTimeout(voiceController.pendingTimer);speak(text)}}
function speak(text,{resume=true}={}){if(!('speechSynthesis'in window)||typeof SpeechSynthesisUtterance==='undefined'){setVoiceStatus('Sprachausgabe wird in diesem Browser nicht unterstützt. Die Antwort steht im Chat.');return}releaseRecognition();window.speechSynthesis.cancel();voiceController.speaking=false;voiceController.utterance=null;const spoken=String(text||'').replace(/€/g,' Euro').replace(/m²/g,' Quadratmeter').replace(/lfm/g,' laufende Meter').replace(/Std\./g,' Stunden').trim();if(!spoken)return;const chosen=chooseGermanVoice(availableVoices(),state.settings.voiceURI);if(!chosen){if(!availableVoices().length){voiceController.pendingSpeech=spoken;setVoiceStatus('Stimme wird vom Gerät bereitgestellt …');clearTimeout(voiceController.pendingTimer);voiceController.pendingTimer=setTimeout(()=>{voiceController.pendingSpeech='';setVoiceStatus('Keine deutsche Stimme bereit. Bitte Stimmenauswahl prüfen; Antwort steht im Chat.')},600)}else setVoiceStatus('Keine deutsche Stimme verfügbar. Die Antwort steht im Chat.');return}voiceController.pendingSpeech='';clearTimeout(voiceController.pendingTimer);const utterance=new SpeechSynthesisUtterance(spoken);utterance.lang='de-DE';utterance.voice=chosen;utterance.rate=Math.min(1.25,Math.max(.85,Number(state.settings.speechRate)||1.08));utterance.pitch=1;utterance.volume=1;voiceController.utterance=utterance;voiceController.lastSpoken=spoken;voiceController.speaking=true;setVoiceStatus('Ich antworte …');utterance.onend=()=>{if(voiceController.utterance!==utterance)return;voiceController.speaking=false;voiceController.utterance=null;setVoiceStatus('Bereit für deine nächste Frage.');if(resume&&voiceController.continueAllowed&&state.settings.handsFree&&view==='assistant')setTimeout(()=>{if(!voiceController.speaking&&voiceController.continueAllowed&&view==='assistant')voice()},120)};utterance.onerror=ev=>{if(voiceController.utterance!==utterance)return;voiceController.speaking=false;voiceController.utterance=null;if(!['canceled','interrupted'].includes(ev.error))setVoiceStatus('Sprachausgabe fehlgeschlagen. Andere Stimme wählen; Antwort steht im Chat.')};window.speechSynthesis.speak(utterance)}
function voice(){if(voiceController.listening||voiceController.starting){stopVoice();return}const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition){setVoiceStatus('Spracheingabe hier nicht unterstützt. Bitte den Android-Sprachdienst prüfen oder tippen.');return}stopVoice();voiceController.continueAllowed=true;const recognition=new Recognition(),generation=++voiceController.generation;voiceController.recognizer=recognition;voiceController.starting=true;recognition.lang='de-DE';recognition.continuous=true;recognition.interimResults=true;recognition.maxAlternatives=5;let sent=false,failed=false,finalText='',interimText='';
const submit=()=>{if(generation!==voiceController.generation||sent||failed||!finalText||interimText)return;sent=true;releaseRecognition();if(state.settings.voiceAutoSubmit!==false){ask(finalText,{voiceInput:true}).catch(()=>setVoiceStatus('Antwort konnte nicht erstellt werden. Bitte erneut versuchen.'))}else{voiceController.manualPending=true;setVoiceStatus('Text erkannt. Prüfen und mit Senden bestätigen.')}};
setVoiceStatus('Mikrofon wird geöffnet …');recognition.onstart=()=>{if(generation!==voiceController.generation)return;voiceController.starting=false;voiceController.listening=true;setVoiceStatus('Ich höre zu …')};
recognition.onresult=ev=>{if(generation!==voiceController.generation||sent)return;clearTimeout(voiceController.finalTimer);const results=Array.from(ev.results);finalText=results.filter(r=>r.isFinal).map(r=>bestTranscript(r,assistantContext)).join(' ').trim();interimText=results.filter(r=>!r.isFinal).map(r=>r[0]?.transcript||'').join(' ').trim();const shown=[finalText,interimText].filter(Boolean).join(' '),input=document.querySelector('#chat-text');if(input)input.value=shown;voiceController.heard=shown;setVoiceStatus('Ich höre zu …');if(finalText&&!interimText){const parsed=parseAssistantRequest(finalText,assistantContext);if(parsed.lines.length||!['clarify-service','unknown'].includes(parsed.intent))voiceController.finalTimer=setTimeout(submit,900)}};
recognition.onerror=ev=>{if(generation!==voiceController.generation)return;failed=true;releaseRecognition();const errors={'not-allowed':'Mikrofon nicht freigegeben. App-Berechtigung prüfen.','service-not-allowed':'Der Sprachdienst ist nicht verfügbar.','audio-capture':'Kein nutzbares Mikrofon gefunden.','network':'Sprachdienst nicht erreichbar. Offline-Modell oder Verbindung prüfen.','no-speech':'Keine Sprache erkannt. Mikrofon prüfen und erneut antippen.','language-not-supported':'Deutsch wird vom Sprachdienst nicht unterstützt.','aborted':'Spracheingabe gestoppt.'};setVoiceStatus(errors[ev.error]||'Spracheingabe fehlgeschlagen. Bitte tippen oder erneut versuchen.')};
recognition.onend=()=>{if(generation!==voiceController.generation)return;voiceController.starting=false;voiceController.listening=false;clearTimeout(voiceController.finalTimer);if(!sent&&!failed&&finalText&&!interimText){submit();return}voiceController.recognizer=null;if(!sent&&!failed)setVoiceStatus(interimText?'Text noch nicht vollständig bestätigt. Bitte prüfen und mit Senden übernehmen.':'Kein fertiger Satz erkannt. Bitte erneut sprechen oder Text senden.')};try{recognition.start()}catch{releaseRecognition();setVoiceStatus('Mikrofon konnte nicht gestartet werden. Sprachdienst und Berechtigungen prüfen.')}}

function bindSpeechControls(){if(view!=='assistant')return;refreshVoiceControls();setVoiceStatus(voiceController.status);document.querySelector('#voice-choice').onchange=async ev=>{state.settings.voiceURI=ev.target.value;refreshVoiceControls();try{await persist()}catch{toast('Stimmenwahl konnte nicht gespeichert werden.')}};document.querySelector('#voice-speed').onchange=async ev=>{state.settings.speechRate=+ev.target.value;try{await persist()}catch{toast('Sprechtempo konnte nicht gespeichert werden.')}};for(const [id,key]of [['voice-auto','voiceAutoSubmit'],['voice-short','shortVoice'],['voice-handsfree','handsFree']])document.querySelector('#'+id).onchange=async ev=>{state.settings[key]=ev.target.checked;if(key==='handsFree'&&!ev.target.checked)voiceController.continueAllowed=false;try{await persist()}catch{toast('Spracheinstellung konnte nicht gespeichert werden.')}}}
async function handleVoiceAction(action){switch(action){case'open-voice':view='assistant';render();voice();return true;case'voice-stop':stopVoice();return true;case'voice-preview':stopVoice();speak('Guten Tag. Ich bin dein WerkPilot-Assistent. Ich helfe dir schnell bei Aufträgen, Preisen und Geräten.',{resume:false});return true;case'voice-repeat':speak(voiceController.lastSpoken||lastSpeechReply||'Stelle mir zuerst eine Frage.',{resume:false});return true;}return false}
function initVoice(){if('speechSynthesis'in window){window.speechSynthesis.getVoices();window.speechSynthesis.addEventListener?.('voiceschanged',refreshVoiceControls)}document.addEventListener('visibilitychange',()=>{if(document.hidden)stopVoice()});window.addEventListener?.('pagehide',stopVoice);window.addEventListener?.('werkpilot-native-back',ev=>{if(view!=='dashboard'){ev.preventDefault();stopVoice();view='dashboard';render();window.scrollTo?.({top:0})}})}

function assistantPage(){return `${pageHeading('Sprich. Ich rechne mit.', 'Natürliche Mengen, kurze Rückantworten und eine passende deutsche Stimme.')}<div class="grid"><div class="card"><div class="cardhead"><h2>${icon('spark')} WerkPilot-Fachassistent</h2><span class="pill">Direkte Sprachantwort</span></div><div class="voice-panel"><div class="voice-status" id="voice-status" role="status" aria-live="polite">${e(voiceController.status)}</div><div id="voice-heard" class="fieldhelp" aria-live="off">${e(voiceController.heard?'Erkannt: '+voiceController.heard:'')}</div><div class="actions" style="margin-top:12px">${btn('Sprechen','voice','mic','voice-main')}${btn('Stoppen','voice-stop','close','secondary')}${btn('Noch einmal hören','voice-repeat','','secondary')}</div></div><div id="chat" class="chat" role="log" aria-live="polite">${chatMessages.map(m=>`<div class="message ${m.role==='user'?'user':''}"><small>${m.role==='user'?'DU':'WERKPILOT'}</small>${e(m.text)}</div>`).join('')}</div><form id="chat-form"><div class="chatinput"><input id="chat-text" name="text" required maxlength="1000" placeholder="8 Bäume, 30 Minuten Anfahrt, 20 Euro Material …" aria-label="Nachricht an Fachassistent"><button class="btn" type="submit" aria-label="Nachricht senden">${icon('send')}</button></div></form><div class="suggestions">${['Acht Bäume zurückschneiden, 30 Minuten Anfahrt, 20 Euro Material','Zwei Bäume fällen und Grünschnitt abtransportieren','Was brauche ich dafür?','Was steht heute an?','Wie viel Umsatz habe ich?'].map(s=>`<button data-action="ask" data-text="${e(s)}">${e(s)}</button>`).join('')}</div><p class="fieldhelp">Das erkannte Gesprochene bleibt sichtbar. Bei falscher Erkennung kannst du korrigieren: „Nein, hundertfünfzig Quadratmeter“. Preise bleiben Schätzungen. Aufträge werden erst im Formular gespeichert.</p></div><div><div class="card"><h2>Deine Stimme</h2><label for="voice-choice">Deutsche Stimme auswählen</label><select id="voice-choice"><option value="">Automatisch · Männerstimme bevorzugt</option></select><p id="voice-hint" class="fieldhelp"></p><label for="voice-speed" style="margin-top:15px">Sprechtempo</label><select id="voice-speed">${[[.95,'Ruhig'],[1.08,'Zügig und klar'],[1.2,'Schnell']].map(([v,t])=>`<option value="${v}" ${Math.abs((state.settings.speechRate||1.08)-v)<.01?'selected':''}>${t}</option>`).join('')}</select><div class="actions" style="margin-top:15px">${btn('Stimme testen','voice-preview','mic','light')}</div><div class="divider"></div><label class="inlinecheck"><input id="voice-short" type="checkbox" ${state.settings.shortVoice!==false?'checked':''}>Kurze gesprochene Antworten</label><label class="inlinecheck" style="margin-top:12px"><input id="voice-auto" type="checkbox" ${state.settings.voiceAutoSubmit!==false?'checked':''}>Nach fertigem Satz direkt antworten</label><label class="inlinecheck" style="margin-top:12px"><input id="voice-handsfree" type="checkbox" ${state.settings.handsFree?'checked':''}>Nach jeder Antwort weiter zuhören</label><label class="inlinecheck" style="margin-top:12px"><input type="checkbox" data-action="speech-toggle" ${state.settings.speech?'checked':''}>Auch getippte Antworten vorlesen</label><p class="fieldhelp">Sprachfragen werden vorgelesen. „Stoppen“ beendet Mikrofon und Ausgabe. Beim Wechsel der Seite oder Ausblenden der App wird die Sprachsitzung beendet.</p></div><div class="card"><h2>So verstehe ich dich besser</h2><p style="font-size:12px">„Kalkuliere zweihundert Quadratmeter Rasen und dreißig Meter Hecke.“</p><p style="font-size:12px">„Was brauche ich dafür?“<br>„Nein, bei der Hecke vierzig Meter.“<br>„Übernehmen.“ oder „Ja bitte.“</p><div class="notice">Mengen, Einheiten und Rückfragen werden lokal interpretiert, ohne Sprachmodell-Download. Die eigentliche Spracherkennung kommt vom Browser und kann dessen Onlinedienst nutzen. Qualität und Geschwindigkeit hängen auch von Mikrofon, Browser und Verbindung ab. Dies ist kein freies ChatGPT-Sprachmodell.</div></div></div></div>`}

function workspaceHero(){const p=quotePipeline(state),checks=companySetup(state),done=checks.filter(c=>c.done).length;return `<section class="workspace-hero"><div class="hero-grid"><div class="hero-copy"><span class="company-badge">${icon('leaf')} DEIN BETRIEBSARBEITSPLATZ</span><h1>${e(state.settings.company===defaults.company?'Dein Betrieb. Klar organisiert.':state.settings.company)}</h1><p>Vom Aufmaß zum Angebot. Vom Einsatz zur Zahlung.</p><div class="workspace-actions">${btn('Auftrag kalkulieren','new-job','plus')}${btn('Angebote ansehen','open-offers','mail','secondary')}${btn('Firmenprofil','open-workspace','users','secondary')}</div></div><div class="hero-kpis"><div><span>Offenes Angebotsvolumen</span><strong>${money(p.openGross)}</strong><small>${p.open} gültige Angebote · noch kein Umsatz</small></div><div><span>Firmeneinrichtung</span><strong>${done} / ${checks.length}</strong><small>Schritte erledigt</small></div></div></div></section>`}
function setupRows(){return companySetup(state).map(check=>`<div class="setup-item"><span class="setup-icon">${icon(check.done?'check':'clock')}</span><div><strong>${e(check.label)}</strong><small>${check.done?'Eingerichtet':'Noch offen'}</small></div>${check.action?btn(check.done?'Öffnen':'Einrichten',check.action,'','light small'):`<button class="btn light small" data-view="${check.view}">${check.done?'Öffnen':'Einrichten'}</button>`}</div>`).join('')}
function pipelineHTML(){const p=quotePipeline(state);return `<div class="pipeline">${[['Entwürfe',p.draft],['Versendet',p.sent],['Angenommen',p.accepted],['Rechnungen',state.invoices.length]].map(([label,value])=>`<div class="pipeline-step"><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`}
function workspacePage(){const checks=companySetup(state),p=quotePipeline(state),done=checks.filter(c=>c.done).length;return `${workspaceHero()}<div class="business-hub"><section class="card"><div class="cardhead"><h2>Deinen Betrieb einrichten</h2><span class="pill">${done} von ${checks.length}</span></div><div class="setup-progress" role="progressbar" aria-label="Firmeneinrichtung" aria-valuemin="0" aria-valuemax="${checks.length}" aria-valuenow="${done}"><span style="width:${done/checks.length*100}%"></span></div>${setupRows()}</section><section class="card"><h2>Dein Weg zur Zahlung</h2>${pipelineHTML()}<div class="summaryrow"><span>Angenommene Angebotswerte</span><strong>${money(p.acceptedGross)}</strong></div><div class="summaryrow"><span>Nachfassen empfohlen</span><strong>${p.followUps.length}</strong></div><div class="summaryrow"><span>Abgelaufene offene Angebote</span><strong>${p.expired}</strong></div><p class="fieldhelp">Annahme dokumentiert eine Kundenentscheidung. Umsatz entsteht in der Finanzübersicht erst durch erfasste Zahlungen. Termine und geänderten Umfang separat prüfen.</p>${btn('Angebote bearbeiten','open-offers','mail','secondary')}</section><section class="card"><h2>Deine Region</h2><strong>${e(state.settings.homeBase||'Ausgangsort ergänzen')}</strong><p>${e(state.settings.serviceArea||'Einsatzgebiet ergänzen')}</p><p class="fieldhelp">Start und Ziel pro Auftrag festhalten. Fahrzeit und Kilometer werden aus deinen Angaben kalkuliert.</p><button class="btn secondary" data-view="rates">Regionale Kosten & Preise</button></section><section class="card"><h2>Deine Firmendaten gehören dir</h2><p>Aufträge, Angebote und Belege liegen lokal auf diesem Gerät. Eine Sicherung außerhalb der App ist wichtig.</p><div class="actions">${btn('Sicherung exportieren','backup','download')}<button class="btn secondary" data-view="settings">Daten übernehmen</button></div><p class="fieldhelp">Eine weitere Installation hat ihren eigenen Bestand. Eine automatische Cloud- oder Team-Synchronisation ist nicht eingerichtet.</p></section></div>`}
const offerLabels={draft:'Entwurf',sent:'Versendet',accepted:'Angenommen',declined:'Abgelehnt',withdrawn:'Zur Überarbeitung'};
function offersPage(){const p=quotePipeline(state),list=state.quotes.filter(q=>offerFilter==='all'||(offerFilter==='expired'?quoteSummary(q).expired:q.status===offerFilter)).sort((a,b)=>b.created.localeCompare(a.created)||b.sequence-a.sequence);return `${pageHeading('Angebote, die Klarheit schaffen.','Feste Preisstände, Gültigkeit und die Entscheidung deines Kunden.',btn('Neues Angebot','new-offer','plus'))}${pipelineHTML()}<div class="offer-tabs" role="group" aria-label="Angebote filtern">${[['all','Alle'],['draft','Entwürfe'],['sent','Versendet'],['accepted','Angenommen'],['declined','Abgelehnt'],['withdrawn','Zur Überarbeitung'],['expired','Abgelaufen']].map(([id,label])=>`<button class="btn ${offerFilter===id?'':'secondary'} small" data-action="offer-filter" data-filter="${id}" aria-pressed="${offerFilter===id}">${label}</button>`).join('')}</div>${p.followUps.length?`<div class="notice">${p.followUps.length} versendete Angebote warten seit mindestens drei Tagen auf eine Entscheidung.</div>`:''}<div class="offer-list">${list.map(q=>{const summary=quoteSummary(q);return `<article class="offer-card"><div class="cardhead"><div><small>${e(q.number)}</small><h3>${e(q.job.title)}</h3><p>${e(q.customer.name)}</p></div><span class="pill ${summary.expired?'red':q.status==='declined'?'gray':q.status==='draft'?'amber':''}">${summary.expired?'Abgelaufen':offerLabels[q.status]}</span></div><div class="summaryrow total"><span>Gesamtpreis</span><strong>${money(q.calc.gross)}</strong></div><p class="fieldhelp">Erstellt ${dateText(q.created)} · gültig bis ${dateText(q.validUntil)}</p><div class="actions">${btn('Details','offer-detail','','secondary small',`data-id="${q.id}"`)}${btn('PDF','offer-print','print','light small',`data-id="${q.id}"`)}${q.status==='draft'||q.status==='sent'?btn('E-Mail-Entwurf','offer-email','mail','light small',`data-id="${q.id}"`):''}</div></article>`}).join('')||`<section class="card">${empty('Noch keine Angebote. Zuerst einen Auftrag kalkulieren und daraus ein Angebot erstellen.','mail')}${btn('Auftrag kalkulieren','new-job','plus')}</section>`}</div>`}
function offerDetail(id){const q=state.quotes.find(q=>q.id===id);if(!q)return;const current=state.jobs.find(j=>j.id===q.jobId),changed=current&&(JSON.stringify(current.lines)!==JSON.stringify(q.job.lines)||calculate(current,state.settings).gross!==q.calc.gross);showDialog('Angebot '+e(q.number),`<div class="actions"><span class="pill">${offerLabels[q.status]}</span><span class="pill gray">Gültig bis ${dateText(q.validUntil)}</span></div><h3>${e(q.job.title)}</h3><p>${e(q.customer.name)} · ${e(q.customer.address||'Adresse ergänzen')}</p><div class="summaryrow total"><span>Fester Gesamtpreis</span><strong>${money(q.calc.gross)}</strong></div>${changed?'<div class="notice warn">Der aktuelle Auftrag wurde nach diesem Angebot verändert. Vor der Ausführung den bestätigten Umfang und Preis mit diesem Angebotsstand abgleichen.</div>':''}<div class="actions">${btn('Angebot / PDF','offer-print','print','',`data-id="${q.id}"`)}${btn('E-Mail-Entwurf öffnen','offer-email','mail','secondary',`data-id="${q.id}"`)}${current?btn('Auftrag öffnen','detail','','secondary',`data-id="${q.jobId}"`):''}</div><p class="fieldhelp">PDF selbst an den E-Mail-Entwurf anhängen. Öffnen der E-Mail-App bestätigt keinen Versand.</p><div class="divider"></div><h3>Kundenentscheidung dokumentieren</h3><div class="actions">${q.status==='draft'?btn('Als versendet markieren','offer-status','','secondary',`data-id="${q.id}" data-status="sent"`):''}${q.status==='sent'?btn('Annahme dokumentieren','offer-status','check','',`data-id="${q.id}" data-status="accepted"`):''}${['draft','sent'].includes(q.status)?btn('Zur Überarbeitung zurückziehen','offer-status','','secondary',`data-id="${q.id}" data-status="withdrawn"`):''}${['draft','sent'].includes(q.status)?btn('Ablehnung dokumentieren','offer-status','','danger',`data-id="${q.id}" data-status="declined"`):''}</div><p class="fieldhelp">Die dokumentierte Annahme plant keinen Einsatz automatisch. Termin, Artenschutz und tatsächlichen Leistungsumfang vor Arbeitsbeginn prüfen.</p><div class="divider"></div><h3>Verlauf</h3>${q.events.map(event=>`<div class="summaryrow"><span>${offerLabels[event.status]}<small class="fieldhelp">${e(event.note)}</small></span><strong>${dateText(event.date)}</strong></div>`).join('')}`)}
function newOfferDialog(){const jobs=state.jobs.filter(j=>j.status!=='Storniert');if(!jobs.length){toast('Zuerst einen Auftrag mit Kunde und Leistungen kalkulieren.');view='calc';draft=newDraft();render();return}showDialog('Angebot erstellen',`<form id="offer-form">${select('offerJob','Kalkulierter Auftrag',jobs[0].id,jobs.map(j=>[j.id,j.title+' · '+jobCustomer(j)]))}<p class="fieldhelp">Preis, Empfänger und Firmenangaben werden als eigener Angebotsstand gespeichert. Ein bereits bestehender Entwurf wird geöffnet.</p><button class="btn" type="submit">${icon('check')} Entwurf erstellen</button></form>`);document.querySelector('#offer-form').onsubmit=async ev=>{ev.preventDefault();await handleProAction('create-offer',{dataset:{id:new FormData(ev.target).get('offerJob')}})};guardForm(document.querySelector('#offer-form'))}
function ratesPage(){return `${pageHeading('Deine Preise. Deine Marge.','Eigene Richtpreise für neue Kalkulationen und transparente Fahrtkosten.')}<form id="rates-form"><div class="business-hub"><section class="card"><h2>Region & Anfahrt</h2><div class="formgrid">${field('homeBase','Ausgangspunkt',state.settings.homeBase,'text','required maxlength="200"')}${field('serviceArea','Einsatzgebiet',state.settings.serviceArea,'text','maxlength="500"')}${field('travelHourlyRate','Verkaufspreis Fahrt · € / Std.',state.settings.travelHourlyRate,'number','min="0" max="10000" step="0.01" required')}${field('travelKmRate','Zusätzlich · € / km',state.settings.travelKmRate,'number','min="0" max="100" step="0.01" required')}</div><p class="fieldhelp">30 Minuten Fahrt kosten nach deinem aktuellen Satz ${money(state.settings.travelHourlyRate/2)}, zuzüglich angegebener Kilometer. Bei Regelbesteuerung sind dies Nettopreise; im §-19-Modus Endpreise.</p><div class="notice">Arbeitskosten und Betriebskosten in den Einstellungen sind deine Kostenbasis. Diese Fahrtpreise werden dem Kunden berechnet.</div><button class="btn" type="submit">${icon('check')} Eigene Preise speichern</button></section><section class="card"><h2>Leistungen & Aufmaß</h2><p class="fieldhelp">Die Katalogwerte sind anpassbare Startannahmen. Gespeicherte Aufträge und Angebote behalten ihren Preis. Baumpflege vom Boden und Baumfällung sind getrennte Leistungen.</p>${services.map(service=>`<div class="setup-item"><div><strong>${e(service.name)}</strong><small>${e(groupName(service.category))} · ${e(service.unit)}</small></div>${field('serviceRate-'+service.id,'€ / '+service.unit,serviceRate(service),'number','min="0" max="100000" step="0.01" required')}</div>`).join('')}</section></div></form>`}
async function saveCompanySettings(ev){ev.preventDefault();try{const f=Object.fromEntries(new FormData(ev.target));for(const key of ['company','owner','address','email','phone','website','quotePrefix'])if(typeof f[key]==='string')f[key]=f[key].trim();if(!f.company)throw Error('Bitte einen Firmennamen eingeben.');for(const k of ['tax','hourlyCost','overhead','kmCost','targetMargin','paymentDays','watchYear','previousTurnover','externalTurnover','reservePercent','quoteDays'])if(k in f)f[k]=Number(f[k]);if(f.taxMode!=='standard')f.tax=0;const validated=validateRestore({...state,settings:{...state.settings,...f}});state.settings=validated.settings;if(await commit())toast('Firmeneinstellungen gespeichert.')}catch(err){toast('Einstellungen prüfen: '+err.message)}}
function bindProPage(){if(view!=='rates')return;document.querySelector('#rates-form').onsubmit=async ev=>{ev.preventDefault();try{const f=new FormData(ev.target),rates={};for(const service of services){const value=Number(f.get('serviceRate-'+service.id));if(!Number.isFinite(value)||value<0||value>100000)throw Error('Preis für '+service.name+' prüfen.');rates[service.id]=roundMoney(value)}const settings={...state.settings,serviceRates:rates,homeBase:String(f.get('homeBase')||'').trim(),serviceArea:String(f.get('serviceArea')||'').trim(),travelHourlyRate:Number(f.get('travelHourlyRate')),travelKmRate:Number(f.get('travelKmRate'))};if(!settings.homeBase)throw Error('Bitte den Ausgangsort ergänzen.');state.settings=validateRestore({...state,settings}).settings;if(await commit())toast('Eigene Preise gespeichert. Neue Kalkulationen verwenden diese Sätze.')}catch(err){toast(err.message)}}}
async function handleProAction(action,target){const id=target.dataset.id;switch(action){case'open-workspace':view='workspace';dialog.close();render();return true;case'open-offers':view='offers';dialog.close();render();return true;case'offer-filter':offerFilter=target.dataset.filter;render();return true;case'new-offer':newOfferDialog();return true;case'quote':case'create-offer':{const q=createQuote(state,id);if(!state.quotes.some(other=>other.id===q.id)){state.quotes.push(q);state.settings.nextQuoteNumber=Math.max(state.settings.nextQuoteNumber,q.sequence+1);if(!await commit())return true}offerDetail(q.id);return true}case'offer-detail':offerDetail(id);return true;case'offer-print':{const q=state.quotes.find(q=>q.id===id);if(q){const assessment=assessSite(q.job,q.job.siteDetails||{});let html=documentHTML(q.job,assessment.readyForBindingQuote?'Angebot':'Angebotsentwurf',{...q,issued:q.created});if(!assessment.readyForBindingQuote)html=html.replace('<hr>','<hr><p><strong>Vorläufiger Preisstand: '+e(assessment.missing.join('; '))+'. Vor verbindlicher Freigabe vor Ort prüfen.</strong></p>');printHTML(html);}return true}case'offer-email':{const q=state.quotes.find(q=>q.id===id);if(!q)return true;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(q.customer.email||'')){toast('Bitte eine E-Mail-Adresse im Kundenprofil ergänzen. Bereits gespeicherte Angebote behalten ihren Empfängerstand.');return true}const body=`Guten Tag ${q.customer.name},\n\nanbei unser Angebot ${q.number} für ${q.job.title}.\nGesamtbetrag: ${money(q.calc.gross)}\nGültig bis: ${dateText(q.validUntil)}\n\nBitte bestätigen Sie den Leistungsumfang vor der Ausführung.\n\nFreundliche Grüße\n${q.company.company}\n${q.company.owner}`;window.location.href='mailto:'+encodeURIComponent(q.customer.email)+'?subject='+encodeURIComponent('Angebot '+q.number+' · '+q.job.title)+'&body='+encodeURIComponent(body);toast('E-Mail-Entwurf geöffnet. PDF selbst anhängen; Versand danach dokumentieren.');return true}case'offer-status':{const index=state.quotes.findIndex(q=>q.id===id);if(index<0)return true;const status=target.dataset.status,message=status==='sent'?'Hast du dieses Angebot tatsächlich an den Kunden versandt?':status==='withdrawn'?'Diesen Angebotsstand zur Überarbeitung zurückziehen? Er bleibt im Verlauf erhalten. Danach kannst du einen neuen Stand erstellen.':status==='accepted'?'Hat der Kunde dieses Angebot mit genau diesem Umfang und Preis angenommen?':'Die Ablehnung dieses Angebots dokumentieren?';if(!confirm(message))return true;state.quotes[index]=changeQuoteStatus(state.quotes[index],status,{note:status==='withdrawn'?'Angebot zur Überarbeitung zurückgezogen':'Kundenentscheidung bzw. Versand manuell dokumentiert'});if(await commit())offerDetail(id);return true}case'calculate-travel':readDraft(document.querySelector('#job-form'));draft.travelPrice=configuredTravelPrice(draft,state.settings);render();toast('Fahrtpreis aus Gesamtzeit und Kilometern berechnet.');return true;case'draft-route':readDraft(document.querySelector('#job-form'));if(!draft.routeFrom||!draft.routeTo){toast('Bitte Start und Ziel eintragen.');return true}window.location.href='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(draft.routeFrom)+'&destination='+encodeURIComponent(draft.routeTo)+'&travelmode=driving';return true;}return false}

function siteDetailsForm(job){const ids=job.lines.map(l=>l.service);const crafts=job.lines.map(l=>services.find(s=>s.id===l.service)).filter(s=>s&&tradeGroups.some(g=>g.id===s.category)&&s.id!=='customwork');if(!crafts.length&&!ids.some(id=>['felling','greenhaul','tree','radical','deep','window','practice'].includes(id)))return '';const site=job.siteDetails||{},felling=ids.includes('felling'),tree=felling||ids.includes('tree'),green=ids.some(id=>['felling','greenhaul','radical'].includes(id)),keys=new Set();if(felling)SITE_CHECKS.forEach(check=>keys.add(check.key));if(crafts.length)keys.add('siteInspected');if(crafts.some(s=>['electrical','building_services','roofing','demolition','metal','masonry'].includes(s.category))){keys.add('qualifiedWorkers');keys.add('safetyPlanConfirmed')}if(crafts.some(s=>['electrical','building_services','roofing','demolition','masonry'].includes(s.category)))keys.add('permissionsChecked');if(ids.some(id=>['tree','window'].includes(id))){keys.add('siteInspected');keys.add('safetyPlanConfirmed')}if(ids.includes('greenhaul')||ids.includes('deep'))keys.add('siteInspected');if(ids.includes('practice')){keys.add('siteInspected');keys.add('qualifiedWorkers')}if(ids.includes('radical'))keys.add('permissionsChecked');return `<div class="divider"></div><h3>Aufmaß & Ausführungsumfang bestätigen</h3><div class="formgrid">${tree?field('site-treeHeight','Baumhöhe · m',site.treeHeight??'','number','min="0.1" max="100" step="0.1"'):''}${felling?field('site-trunkDiameter','Stammdurchmesser · cm',site.trunkDiameter??'','number','min="0.1" max="500" step="0.1"'):''}${green?field('site-greenVolume','Bestätigtes Grüngutvolumen · m³',site.greenVolume??'','number','min="0" max="10000" step="0.1"'):''}${tree||green?select('site-access','Zugänglichkeit',site.access||'unknown',[['unknown','Noch prüfen'],['easy','Frei / gut zugänglich'],['limited','Eingeschränkt'],['difficult','Schwierig / Spezialtechnik']]):''}</div>${SITE_CHECKS.filter(check=>keys.has(check.key)).map(check=>`<label class="inlinecheck" style="margin-top:12px"><input name="site-${check.key}" type="checkbox" ${site[check.key]?'checked':''}>${e(check.label)}</label>`).join('')}${green?`<div class="actions" style="margin-top:16px">${btn('Kronach-Grüngutgebühr berechnen','regional-disposal','calc','light small')}</div><p class="fieldhelp">Die Grüngutgebühr gilt für zulässiges kompostierbares Material. Baumstämme und Äste über 10 cm benötigen eine eigene Entsorgungslösung.</p>`:''}`}

function knowledgePage(){return `${pageHeading('Fachwissen. Lokal verfügbar.','Handwerks- und Dienstleistungskatalog mit regionaler Entsorgungsbasis.')}<div class="grid"><section class="card"><h2>Mitwitz & Umgebung</h2><p><strong>${e(LOCAL_REGION.base||state.settings.homeBase)}</strong><br>${e(state.settings.serviceArea)}</p><h3>Gewerbliche Grüngutentsorgung · Kronach</h3><p>Amtlich verlinktes Merkblatt, Stand Januar 2025: 9 € / m³ und 5 € Rechnungspauschale, jeweils zuzüglich Umsatzsteuer.</p><p class="fieldhelp">Die Pauschale gilt je Rechnung. Für die Auftragsplanung wird eine Rechnung angenommen. Privatfreimengen werden nicht auf deinen Gewerbeauftrag übertragen.</p><a href="https://www.landkreis-kronach.de/media/22639/information-kompostplatze-2025.pdf" target="_blank" rel="noopener">Kronach: Tarif und Annahme prüfen</a><p>Für Aufträge in Sonnefeld / Landkreis Coburg gelten andere Annahme- und Gebührenregeln. Den passenden Entsorger vor der Fahrt bestätigen.</p><a href="https://www.landkreis-coburg.de/fileadmin/Downloads/Leben/Bauen-Wohnen-Umwelt-Klima-Natur/Gebuehrensatzung_01.2026.pdf" target="_blank" rel="noopener">Coburg: Gebührensatzung 2026</a><div class="notice">Leistungspreise werden aus deinen eigenen Sätzen, Arbeitskosten, direkten Kosten und der Zielmarge kalkuliert. Ein regional einheitlicher Dienstleistungstarif existiert nicht.</div><button class="btn secondary" data-view="rates">Eigene Preise einstellen</button></section><section class="card"><h2>Leistung auswählen</h2><div class="more-grid">${services.map(s=>`<button data-action="knowledge-service" data-id="${s.id}"><span>${icon(groupIcon(s.category))}</span><b>${e(s.name)}</b>${icon('arrow')}</button>`).join('')}</div><p class="fieldhelp">Der Fachkatalog ist in der App gespeichert. Die Spracheingabe nutzt den Android-Sprachdienst; dessen Offline-Verfügbarkeit hängt vom Gerät ab.</p></section></div>`}
function knowledgeDetail(id){const k=knowledgeFor(id),service=services.find(s=>s.id===id);if(!k||!service)return;showDialog(e(service.name),`<p>${e(k.summary)}</p><h3>Für einen belastbaren Preis klären</h3>${k.questions.map(q=>`<div class="checkitem">${icon('check')}<span>${e(q)}</span></div>`).join('')}<h3>Preisgrundlage</h3><p>${e(k.pricingBasis)}</p>${k.risks.length?`<div class="notice warn">${k.risks.map(e).join('<br>')}</div>`:''}<h3>Benötigte Ausstattung</h3>${equipmentSummary({lines:[{service:id}]})}<h3>Arbeitsumfang</h3>${service.tasks.map(t=>`<div class="checkitem">${icon('check')}<span>${e(t)}</span></div>`).join('')}`)}
const previousProAction=handleProAction;
handleProAction=async function(action,target){if(action==='knowledge-service'){knowledgeDetail(target.dataset.id);return true}if(action==='regional-disposal'){readDraft(document.querySelector('#job-form'));try{const fee=disposalEstimate(draft.siteDetails?.greenVolume,{taxMode:draft.taxMode});draft.disposal=fee.cost;render();toast('Kronach-Grüngutgebühr angesetzt: '+money(fee.cost)+'. Tarif und Annahme vor Anlieferung bestätigen.')}catch(err){toast(err.message)}return true}if(action==='offer-status'&&target.dataset.status==='accepted'){const q=state.quotes.find(q=>q.id===target.dataset.id);if(q){const check=assessSite(q.job,q.job.siteDetails||{});if(!check.readyForBindingQuote){toast('Vor verbindlicher Freigabe fehlen: '+check.missing.join('; ')+'. Auftrag ergänzen und einen neuen Angebotsstand erstellen.');return true}}}return previousProAction(action,target)};

const businessGroups=[{id:'garden',name:'Garten & Landschaft',icon:'leaf',description:'Pflege, Rückschnitt, Baumarbeiten und Grünschnitt.'},{id:'clean',name:'Gebäudereinigung',icon:'clean',description:'Haushalt, Büro, Praxis, Glas und Grundreinigung.'},...tradeGroups];
let tradeFilter='all',tradeSearch='';
const groupName=id=>businessGroups.find(g=>g.id===id)?.name||'Handwerk';
const groupIcon=id=>businessGroups.find(g=>g.id===id)?.icon||'tools';
const lineName=line=>line.description?.trim()||services.find(s=>s.id===line.service)?.name||'Individuelle Leistung';
const lineUnit=line=>line.unit||services.find(s=>s.id===line.service)?.unit||'Std.';
function serviceSelect(name,label,value,extra='',placeholder=false){return `<div><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${placeholder?'<option value="">Leistung bestätigen</option>':''}${businessGroups.map(group=>`<optgroup label="${e(group.name)}">${services.filter(s=>s.category===group.id).map(s=>`<option value="${e(s.id)}" ${s.id===value?'selected':''}>${e(s.name)}</option>`).join('')}</optgroup>`).join('')}</select></div>`}
function tradesPage(){const shown=services.filter(s=>(tradeFilter==='all'||s.category===tradeFilter)&&(!tradeSearch||(s.name+' '+groupName(s.category)).toLowerCase().includes(tradeSearch.toLowerCase())));return `${pageHeading('Das richtige Gewerk. Ein klarer Auftrag.','Leistungen, Aufmaß, Material und Maschinen gemeinsam planen.',btn('Individuelle Leistung','craft-add','plus','', 'data-id="customwork"'))}<div class="trade-browser"><section class="card"><form id="trade-search-form" class="catalog-toolbar">${field('trade-search','Leistung suchen',tradeSearch,'search','placeholder="z. B. streichen, Fliesen oder Fenster" maxlength="200"')}<button class="btn secondary" type="submit">${icon('search')} Suchen</button></form><div class="trade-filter" style="margin-top:16px"><button data-action="trade-filter" data-id="all" aria-pressed="${tradeFilter==='all'}">Alle Bereiche</button>${businessGroups.map(g=>`<button data-action="trade-filter" data-id="${g.id}" aria-pressed="${tradeFilter===g.id}">${e(g.name)}</button>`).join('')}</div></section>${tradeFilter==='all'&&!tradeSearch?`<div class="trade-grid">${businessGroups.map(g=>`<button class="trade-card" data-action="trade-filter" data-id="${g.id}"><span class="trade-icon">${icon(g.icon||'tools')}</span><strong>${e(g.name)}</strong><p>${e(g.description||'Leistungen und Ressourcen auftragsbezogen abstimmen.')}</p><small>${services.filter(s=>s.category===g.id).length} Vorlagen</small></button>`).join('')}</div>`:''}<section class="card"><div class="cardhead"><h2>${shown.length} passende Vorlagen</h2><span class="pill gray">Eigene Preise gelten</span></div><div class="craft-service-list">${shown.map(s=>`<article><div class="cardhead"><h3>${e(s.name)}</h3><span class="pill gray">${e(s.unit)}</span></div><small>${e(groupName(s.category))} · Startwert ${money(serviceRate(s))} / ${e(s.unit)} · ${number(s.minutes)} Min. / Einheit</small><p>${e(s.hint)}</p><div class="actions">${btn('Auftrag planen','craft-add','plus','',`data-id="${s.id}"`)}${btn('Material & Anforderungen','knowledge-service','tools','secondary',`data-id="${s.id}"`)}</div></article>`).join('')||empty('Keine passende Vorlage. Mit „Individuelle Leistung“ kannst du den Umfang selbst beschreiben.','tools')}</div></section><div class="notice">Die Vorlagen enthalten bearbeitbare Planungsannahmen. Zulassungspflichtige Tätigkeiten, Untergrund, Herstellerangaben und benötigte Qualifikationen vor einem verbindlichen Auftrag prüfen.</div></div>`}
function resourceSummaryHTML(job){const t=resourceTotals(job.resources||[]);return `<div class="resource-summary"><div class="summaryrow"><span>Materialkosten</span><strong>${money(t.material)}</strong></div><div class="summaryrow"><span>Maschinen · Einsatz / Miete</span><strong>${money(t.rental)}</strong></div><div class="summaryrow total"><span>Bestätigte direkte Kosten</span><strong>${money(t.total)}</strong></div>${t.missing.length?`<p class="planner-note">${t.missing.length} ausgewählte Positionen benötigen noch eine gültige Menge und bestätigte Kosten. Sie sind in dieser Summe noch nicht enthalten.</p>`:''}<p class="fieldhelp">${job.resourceCostsApplied?'Kosten in die Kalkulation übernommen. Katalog-Verbrauchsmaterial wird dabei nicht doppelt gezählt.':'Planwerte noch nicht übernommen. Nach Änderungen erneut bestätigen und übernehmen.'}</p></div>`}
function resourceForm(job){return `<section class="card resource-planner"><div class="cardhead"><h2>Material & Maschinen planen</h2><span class="pill gray">${job.taxMode==='standard'?'Kosten netto':'Kosten brutto'}</span></div><p class="fieldhelp">Materialmengen sind prüfbare Verbrauchsvorschläge. Produkt, Untergrund und Verschnitt bestätigen. Maschinen-Kaufpreise sind keine Mietkosten.</p><div class="actions">${btn(job.resources?.length?'Mengen neu berechnen':'Vorschläge erstellen','resource-suggest','spark','secondary')}${btn('Material ergänzen','resource-add','plus','light','data-kind="material"')}${btn('Maschine ergänzen','resource-add','tools','light','data-kind="machine"')}</div>${(job.resources||[]).map((r,i)=>`<article class="resource-row"><label class="inlinecheck"><input type="checkbox" name="resource-use-${i}" data-resource-index="${i}" data-resource-field="use" ${r.use?'checked':''}>Einplanen</label><div>${field('resource-name-'+i,r.kind==='material'?'Material / Produkt':'Maschine / Werkzeug',r.name,'text',`maxlength="300" required data-resource-index="${i}" data-resource-field="name"`)}<small>${e(r.note||'Eigene auftragsbezogene Position.')}</small></div>${field('resource-quantity-'+i,'Menge',r.quantity,'number',`min="0.000001" max="1000000" step="0.01" required data-resource-index="${i}" data-resource-field="quantity"`)}${field('resource-unit-'+i,'Einheit',r.unit,'text',`maxlength="30" required data-resource-index="${i}" data-resource-field="unit"`)}${field('resource-cost-'+i,'Kosten € / Einheit',r.unitCost,'number',`min="0" max="1000000" step="0.01" required data-resource-index="${i}" data-resource-field="unitCost"`)}${r.kind==='machine'?select('resource-mode-'+i,'Beschaffung',r.mode||'rent',[['owned','Eigenes Gerät'],['rent','Besorgen / mieten']],`data-resource-index="${i}" data-resource-field="mode"`):''}<label class="inlinecheck"><input type="checkbox" name="resource-confirmed-${i}" data-resource-index="${i}" data-resource-field="costConfirmed" ${r.costConfirmed?'checked':''}>Kosten bestätigt · auch 0 €</label><button type="button" class="iconbtn" data-action="resource-remove" data-index="${i}" aria-label="Position entfernen">${icon('trash')}</button></article>`).join('')||empty('Erstelle Vorschläge aus den gewählten Leistungen oder ergänze eigene Produkte und Maschinen.','tools')}<div id="resource-summary">${resourceSummaryHTML(job)}</div>${btn('Bestätigte Kosten übernehmen','resource-apply','check')}<p class="fieldhelp">Ersetzt die Felder „Zusätzliches Material“ und „Maschinenkosten“. Bestehende andere Kosten vor dem Übernehmen prüfen. Einkaufskosten werden weiterberechnet; Gewinn entsteht über die Leistungspreise.</p></section>`}
function plannerPage(){draft??=newDraft();const p=planningSummary(draft,state.settings);return `${pageHeading('Vom Aufmaß zum fertigen Einsatz.','Ressourcen und Termin mit der Kalkulation abstimmen.',btn('Kalkulation öffnen','planner-calc','calc'))}<section class="card"><div class="formgrid">${select('planning-job','Gespeicherten Auftrag laden',state.jobs.some(j=>j.id===draft.id)?draft.id:'',[['','Aktuellen Entwurf planen'],...state.jobs.filter(j=>j.status!=='Storniert').map(j=>[j.id,j.title])])}<div><h3>${e(draft.title||'Neuer Auftragsentwurf')}</h3><p class="fieldhelp">${p.serviceCount} Positionen · ${number(p.personHours)} kalkulierte Personenstunden</p></div></div></section><div class="job-workflow">${p.checks.map((check,i)=>`<div class="workflow-step ${check.done?'done':''}"><span class="step-number">${check.done?icon('check'):i+1}</span><div><strong>${e(check.label)}</strong><small>${check.done?'Erfasst':'Noch ergänzen'}</small></div></div>`).join('')}</div><form id="planner-form"><div class="planner-grid"><div>${resourceForm(draft)}</div><aside><section class="card work-order-summary"><h2>Preis & Zeit prüfen</h2>${calcSummary(draft)}<p class="fieldhelp">Zeitbedarf: ${number(p.personHours)} Personenstunden. Bei einer Person und ohne weitere Pausen entspricht das ca. ${number(p.recommendedDuration)} Einsatzstunden. Bei mehreren Personen Terminzeit selbst anpassen.</p>${btn('Dauer für eine Person übernehmen','planner-duration','clock','secondary')}${btn('Leistungspreis auf Zielmarge','planner-margin','calc','light')}<div class="divider"></div><h3>Benötigte Maschinen</h3>${equipmentSummary(draft)}</section><section class="card"><h2>Aufmaß & Freigaben</h2>${siteDetailsForm(draft)||'<p>Leistungsumfang und örtliche Bedingungen im Auftrag dokumentieren.</p>'}${btn('Auftrag & Termin bearbeiten','planner-calc','calendar','secondary')}</section></aside></div></form>`}
function updateResourceField(target){const index=Number(target.dataset.resourceIndex),row=draft?.resources?.[index],key=target.dataset.resourceField;if(!row||!['use','costConfirmed','name','unit','quantity','unitCost','mode'].includes(key))return false;row[key]=['use','costConfirmed'].includes(key)?target.checked:['quantity','unitCost'].includes(key)?Number(target.value):target.value;if(['name','unit','quantity'].includes(key))row.source='manual';draft.resourceCostsApplied=false;return true}
function bindHandworkPage(){document.querySelector('#trade-search-form')?.addEventListener('submit',ev=>{ev.preventDefault();tradeSearch=String(new FormData(ev.target).get('trade-search')||'').trim();render()});if(view==='planner'){document.querySelector('#planning-job').onchange=ev=>{const job=state.jobs.find(j=>j.id===ev.target.value);if(job)draft=structuredClone(job);render()};document.querySelector('#planner-form').addEventListener('input',ev=>{if(updateResourceField(ev.target)){document.querySelector('#resource-summary').innerHTML=resourceSummaryHTML(draft);return}if(ev.target.name?.startsWith('site-'))readPlannerSite(ev.target)});document.querySelector('#planner-form').addEventListener('change',ev=>{updateResourceField(ev.target);document.querySelector('#resource-summary').innerHTML=resourceSummaryHTML(draft);if(ev.target.name?.startsWith('site-'))readPlannerSite(ev.target)})}}
function readPlannerSite(target){draft.siteDetails||={};const key=target.name.replace('site-','');if(['siteInspected','qualifiedWorkers','permissionsChecked','safetyPlanConfirmed'].includes(key))draft.siteDetails[key]=target.checked;else if(key==='access')draft.siteDetails.access=target.value;else if(['treeHeight','trunkDiameter','greenVolume'].includes(key)){if(target.value==='')delete draft.siteDetails[key];else draft.siteDetails[key]=Number(target.value)}}
async function handleHandworkAction(action,target){switch(action){case'photo-trade':{const service=services.find(s=>s.id===target.dataset.id);if(service){rememberPhotoForm();showDialog(e(groupName(service.category)),`<p>Das Foto zeigt einen Bereich. Wähle den tatsächlichen Arbeitsumfang und bestätige danach die gemessene Menge.</p><div class="craft-service-list">${services.filter(s=>s.category===service.category).map(s=>`<article><h3>${e(s.name)}</h3><p>${e(s.hint)}</p>${btn('Diese Leistung wählen','photo-service','check','',`data-id="${s.id}"`)}</article>`).join('')}</div>`);}return true}case'photo-cancel':photoRecognizer.cancel();return true;case'photo-retry':photoRecognizer.retry();await analyzePhoto();return true;case'photo-clear':photoRecognizer.cancel();++photoSelection;++photoAnalysis;photo=null;photoCollection=[];photoSuggestions=[];photoRecognitionResult=null;photoServiceChoice='';photoQuantity='';render();return true;case'photo-select':{const selected=photoCollection[Number(target.dataset.index)];if(!selected)return true;rememberPhotoForm();attachPhotoMetadata();photoRecognizer.cancel();++photoSelection;++photoAnalysis;photo=selected;photoSuggestions=[];photoRecognitionResult=null;photoServiceChoice='';photoQuantity='';photoStage=selected.stage||'before';photoCaption=selected.caption||'';photoRecognizer.retry();render();return true}case'photo-attach-all':{rememberPhotoForm();if(!draft){draft=newDraft();draft.lines=[];draft.km=0;draft.travelHours=0;draft.travelPrice=0;}attachPhotoMetadata();for(const p of photoCollection)mergeDraftPhoto(p);view='calc';render();toast('Ausgewählte Bilder zum Auftragsentwurf übernommen.');return true}case'open-trades':view='trades';render();return true;case'open-planner':view='planner';render();return true;case'trade-filter':tradeFilter=target.dataset.id;render();return true;case'craft-add':{const s=services.find(s=>s.id===target.dataset.id);if(!s)return true;const add=Boolean(draft);if(!draft){draft=newDraft();draft.lines=[];draft.km=0;draft.travelHours=0;draft.travelPrice=0;}draft.lines.push({service:s.id,qty:s.unit==='m²'?10:1,rate:serviceRate(s)});draft.title||=s.name;draft.resourceCostsApplied=false;view='calc';dialog.close();render();toast(add?'Leistung zum aktuellen Entwurf ergänzt.':'Neuen Auftragsentwurf geöffnet.');return true}case'planner-calc':view='calc';render();return true;case'planner-duration':{const duration=planningSummary(draft,state.settings).recommendedDuration;if(duration>72){toast('Zeitbedarf über 72 Stunden. Bitte in mehrere Einsätze aufteilen und Termine einzeln planen.');return true}draft.duration=duration;render();}toast('Dauer für eine Person übernommen. Pausen und Mitarbeitende selbst prüfen.');return true;case'planner-margin':draft=priceForTargetMargin(draft,state.settings).job;render();return true;case'resource-suggest':{if(view==='calc')readDraft(document.querySelector('#job-form'));draft.resources||=[];if(draft.resources.length&&!confirm('Materialmengen anhand der aktuellen Leistungen neu berechnen? Einkaufspreise bleiben erhalten; geänderte Mengen neu bestätigen. Eigene Zusatzpositionen bleiben bestehen.'))return true;const suggestions=suggestResources(draft,state.owned);draft.resources=refreshResourceSuggestions(draft.resources,suggestions);draft.resourceCostsApplied=false;render();return true}case'resource-add':draft.resources||=[];draft.resources.push({id:uid(),kind:target.dataset.kind==='machine'?'machine':'material',name:'',unit:target.dataset.kind==='machine'?'Einsatz':'Stück',quantity:1,unitCost:0,use:true,costConfirmed:false,mode:'rent',source:'manual',note:''});draft.resourceCostsApplied=false;render();return true;case'resource-remove':draft.resources.splice(Number(target.dataset.index),1);draft.resourceCostsApplied=false;render();return true;case'resource-apply':{if(view==='calc')readDraft(document.querySelector('#job-form'));const totals=resourceTotals(draft.resources||[]);if(!totals.complete){toast('Kosten oder Menge noch bestätigen: '+totals.missing.join(', '));return true}if((draft.material||draft.rental)&&!confirm('Die bisherigen Material- und Maschinenkosten durch die bestätigten Plansummen ersetzen?'))return true;draft=applyResourceCosts(draft);render();toast('Bestätigte Material- und Maschinenkosten übernommen. Leistungspreis und Marge prüfen.');return true}}return false}

let photoSelection=0,photoAnalysis=0,photoCollection=[],photoServiceChoice='',photoQuantity='',photoNotes='',photoStage='before',photoCaption='',photoRecognitionResult=null;
let photoRecognizer=createPhotoRecognizer({services,onStatus:status=>{if(view!=='photos')return;const output=document.querySelector('#analysis-state');if(output)output.innerHTML=recognitionStatusHTML(status);const button=document.querySelector('[data-action="analyze-photo"]');if(button)button.disabled=status.busy;}});
function recognitionStatusHTML(status=photoRecognizer.getState()){return `<div class="recognition-status ${status.stage==='error'?'warn':''}" role="status"><strong>${status.busy?'Erkennung läuft':status.stage==='error'?'Erkennung benötigt Aufmerksamkeit':'Fotoerkennung'}</strong><p>${e(status.message||'Erkennung starten oder Leistung manuell bestätigen.')}</p>${status.progress?.percent!=null?`<progress max="100" value="${status.progress.percent}" aria-label="Modelldatei herunterladen"></progress><small>${number(status.progress.percent)} % · ${e(status.progress.file||'Modelldatei')}</small>`:''}${status.detail?`<details><summary>Technische Meldung</summary><p>${e(status.detail)}</p></details>`:''}${status.stage==='error'?btn('Erneut versuchen','photo-retry','spark','secondary small'):status.busy?btn('Erkennung stoppen','photo-cancel','close','secondary small'):''}</div>`}
function photoResultsHTML(){const results=photoRecognitionResult?.status==='uncertain'?photoRecognitionResult.alternatives||[]:photoSuggestions;return `<div class="recognition-results">${photoRecognitionResult?.status==='uncertain'?'<div class="notice warn">Das Motiv ist nicht eindeutig. Diese Alternativen sind unverbindlich; die Leistung selbst auswählen.</div>':''}${results.map((r,i)=>`<article class="recognition-candidate"><div><strong>${e(r.categoryOnly?groupName(r.service?.category):(r.service?.name||'Bereich prüfen'))}</strong><small>Modellrang ${i+1} · Modellwert ${number(r.score*100)} % · keine kalibrierte Wahrscheinlichkeit</small></div>${r.service?btn(r.categoryOnly?'Passende Leistung wählen':'Leistung bestätigen',r.categoryOnly?'photo-trade':'photo-service','check','secondary small',`data-id="${r.service.id}"`):''}${r.relatedServices?.length?`<div class="actions">${r.relatedServices.map(s=>btn(e(s.name),'photo-service','','light small',`data-id="${s.id}"`)).join('')}</div>`:''}</article>`).join('')}</div>`}
function photosPage(){return `${pageHeading('Vom Foto zum geplanten Auftrag.','Bilder erfassen, sichtbaren Bereich vorschlagen lassen und Aufmaß bestätigen.')}<div class="photo-workspace"><section class="card"><div class="cardhead"><h2>Bilderfassung</h2><span class="pill gray">Lokal · ohne API-Key</span></div><div class="dropzone">${icon('camera')}<p>JPG, PNG oder WebP auswählen.<br>Mehrere Detail-, Vorher- und Nachherbilder sind möglich.</p><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp" multiple aria-label="Auftragsfotos auswählen"></div><div class="photo-stage">${photo?`<img class="photopreview" src="${photo.data}" alt="${e(photo.name)}">`:empty('Deine Auftragsbilder erscheinen hier.','camera')}</div>${photoCollection.length>1?`<div class="photogrid">${photoCollection.map((p,i)=>`<button class="iconbtn" data-action="photo-select" data-index="${i}" aria-label="${e(p.name)} auswählen"><img src="${p.data}" alt="${e(p.name)}"></button>`).join('')}</div>`:''}${photo?`<div class="photo-actions">${btn('Bild erkennen','analyze-photo','spark')}${btn('Foto zum Entwurf','attach-photo','plus','secondary')}${photoCollection.length>1?btn('Alle Bilder übernehmen','photo-attach-all','camera','secondary'):''}${btn('Fotoauswahl leeren','photo-clear','trash','light')}</div><div id="analysis-state">${recognitionStatusHTML()}</div><div id="photo-results">${photoResultsHTML()}</div>`:''}<p class="fieldhelp">Beim ersten Start werden die Bildbibliothek und Modelldateien aus dem Internet geladen, bis zu ca. 200 MB. Danach wird das Foto lokal verarbeitet. Fotos werden dabei nicht an einen KI-Server gesendet. Ein vollständiger Modellcache nach einem Neustart hängt vom Gerätespeicher ab.</p></section><section class="card photo-measurements"><h2>Leistung & Aufmaß bestätigen</h2><p class="sectiondesc">Das Modell kann sichtbare Bereiche vergleichen. Verdeckte Mängel, Materialeigenschaften, sichere Ausführung und Maße benötigen deine Prüfung.</p><form id="photo-measure-form"><div class="formgrid">${serviceSelect('photo-service','Leistung',photoServiceChoice,'required',true)}${field('photo-qty','Bestätigte Menge · '+(services.find(s=>s.id===photoServiceChoice)?.unit||'Leistungseinheit'),photoQuantity,'number','min="0.01" max="1000000" step="0.01" required')}${select('photo-stage','Bildart',photoStage,[['before','Vorher / Bestand'],['during','Während der Arbeit'],['after','Nachher / Abnahme'],['detail','Detail / Aufmaß']])}${field('photo-caption','Bildbeschreibung',photoCaption,'text','maxlength="1000" placeholder="z. B. Wohnzimmer, Nordwand"')}<div class="wide">${field('photo-height','Maße, Material / Untergrund, Zugang & Zustand',photoNotes,'text','maxlength="1000" placeholder="z. B. 30 m² Wand, glatter Putz, 2 Anstriche"')}</div></div><div class="divider"></div><button type="submit" class="btn">${icon('calc')} In Kalkulation übernehmen</button><p class="fieldhelp">Eine weitere bestätigte Fotoleistung ergänzt deinen aktuellen Entwurf. Material- und Maschinenvorschläge danach im Einsatzplan erstellen.</p></form><div class="divider"></div><h3>Dein nächster Schritt</h3><div class="job-workflow">${['Foto erfassen','Leistung bestätigen','Maße eingeben','Material & Preis planen'].map((t,i)=>`<div class="workflow-step"><span class="step-number">${i+1}</span><div><strong>${t}</strong></div></div>`).join('')}</div></section></div>`}
async function readImage(file){return preparePhoto(file)}
function rememberPhotoForm(){const svc=document.querySelector('#photo-service'),qty=document.querySelector('#photo-qty'),notes=document.querySelector('#photo-height'),stage=document.querySelector('#photo-stage'),caption=document.querySelector('#photo-caption');if(svc&&services.some(s=>s.id===svc.value))photoServiceChoice=svc.value;if(qty&&qty.value!=='')photoQuantity=qty.value;if(notes)photoNotes=notes.value||'';if(stage&&['before','during','after','detail'].includes(stage.value))photoStage=stage.value;if(caption)photoCaption=caption.value||'';}
function mergeDraftPhoto(item){if(!draft||!item)return;const index=draft.photos.findIndex(p=>p.data===item.data);if(index<0)draft.photos.push(structuredClone(item));else draft.photos[index]={...draft.photos[index],...structuredClone(item)};}
function attachPhotoMetadata(item=photo){if(item){item.stage=photoStage;item.caption=photoCaption.trim();}return item}
async function analyzePhoto(){if(!photo)return;rememberPhotoForm();const selected=photo,request=++photoAnalysis;photoSuggestions=[];photoRecognitionResult=null;const result=await photoRecognizer.recognize(selected,{imageId:photoSelection});if(request!==photoAnalysis||photo!==selected||result.status==='cancelled')return;photoRecognitionResult=result;photoSuggestions=result.status==='ok'?result.suggestions:[];if(view==='photos'){render();const button=document.querySelector('[data-action="analyze-photo"]');if(button)button.disabled=false;if(result.status==='ok')toast('Bildvorschläge bereit. Leistung und Aufmaß bestätigen.');}}
function bindPhotosPage(){const fileInput=document.querySelector('#photo-file');fileInput.onchange=async ev=>{const files=Array.from(ev.target.files||[]);if(!files.length)return;rememberPhotoForm();attachPhotoMetadata();const request=++photoSelection;++photoAnalysis;photoRecognizer.cancel();photoSuggestions=[];photoRecognitionResult=null;photoServiceChoice='';photoQuantity='';photoNotes='';photoCaption='';photoStage='before';if(files.length>12)toast('Bis zu 12 Fotos je Auswahl. Die ersten 12 werden verarbeitet.');const loaded=[];for(const file of files.slice(0,12)){try{const next=await readImage(file);if(request!==photoSelection)return;loaded.push(next)}catch(err){if(request===photoSelection)toast(err.message)}}if(request!==photoSelection||!loaded.length)return;photoCollection=[...photoCollection,...loaded].slice(-30);photo=loaded[0];photoRecognizer.retry();if(view==='photos')render();};const form=document.querySelector('#photo-measure-form');form.addEventListener('input',rememberPhotoForm);form.addEventListener('change',ev=>{rememberPhotoForm();if(ev.target.name==='photo-service'){const service=services.find(s=>s.id===photoServiceChoice),label=document.querySelector('label[for="photo-qty"]');if(label)label.textContent='Bestätigte Menge · '+(service?.unit||'Leistungseinheit')}});form.onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),s=services.find(s=>s.id===f.get('photo-service')),qty=Number(f.get('photo-qty'));if(!s||!Number.isFinite(qty)||qty<=0||qty>1000000){toast('Bitte Leistung und gültige gemessene Menge auswählen.');return}photoServiceChoice=s.id;photoQuantity=qty;photoNotes=String(f.get('photo-height')||'');photoStage=['before','during','after','detail'].includes(f.get('photo-stage'))?f.get('photo-stage'):'before';photoCaption=String(f.get('photo-caption')||'');if(!draft){draft=newDraft();draft.lines=[];draft.km=0;draft.travelHours=0;draft.travelPrice=0;}draft.lines.push({service:s.id,qty,rate:serviceRate(s)});draft.title||=s.name;draft.notes=(draft.notes+'\n'+photoNotes).trim();draft.resourceCostsApplied=false;if(photo)mergeDraftPhoto(attachPhotoMetadata());view='calc';render();}}

await load();initNative();initVoice();const requestedView=new URLSearchParams(location.search||'').get('view');if(appNavigation().some(([id])=>id===requestedView))view=requestedView;initPlatform(()=>{if(['install','dashboard'].includes(view))render()});render();if(typeof setInterval==='function')setInterval(()=>{const el=document.querySelector('#timer-clock');if(el&&state.activeTimer)el.textContent=timerText()},1000);
